/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20211006-4","meetingId":"r03-c-settlement","date":"2021年10月6日","dateIso":"2021-10-06","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を147件整理しています。","topics":[{"id":"topic-01","title":"◯渡部委員長 ただいまより決算特別委員会を開きます。 それでは、令和２年度品川区一般会計歳入歳出決算","agenda":"◯渡部委員長 ただいまより決算特別委員会を開きます。 それでは、令和２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"湯澤委員","kind":"質問・要望","question":"２８４ページ、それから２９６ページ、お伺いさせてほしいと求めました。これはＤＶまで発展してしまうほどの社会問題になっておりますけれども、運動不足やメンタルケアといったところへの取組みがあれば示すよう求めました。","respondent":"高山健康課長","answer":"しながわ健康プラン２１という、その中で４つの柱を設け、計画的に健康推進事業を進めているところです。様々、保健所機能を通じて、こころに変調を来したような方に寄り添うような形での相談などを実施しています。","id":"exchange-001"},{"speaker":"湯澤委員","kind":"質問","question":"特に育児や介護を行っている方は、自分の時間がほとんどない、１人での外出ができないとのことでありました。外で運動することが難しいという方々に対して、区はどのようなアドバイスをしているか、説明を求めました。","respondent":"高山健康課長","answer":"動画配信などを通じまして、自宅で気軽に取り組めるような、運動に関して丁寧な動画などを作成しております。そうしたものも利用していただくことで、屋内・屋外における運動習慣の定着に努めていただければと考えております。","id":"exchange-002"},{"speaker":"湯澤委員","kind":"提案","question":"例えば東京２０２０大会の区応援競技となった、品川区の魅力発信にもつながるのではないかと思うのですけれども、いかがでしょうか。こちらはもちろん相手があることでありますので、先方と協議して各所管が連携を取っていただくのが前提となりますが、ご意見をお伺いしますとの意見を述べました。","respondent":"高山健康課長","answer":"まさに世代別に料理などの動画を作成いたしまして、品川区内の栄養士会のご協力を頂く中で、これまでも動画などの配信をしてきているところです。","id":"exchange-003"},{"speaker":"湯澤委員","kind":"提案","question":"２年に１度を逃した場合は、２年後と延びてしまっているのでしょうか。ないならば区民の健康を最優先に考えると、何らかの救済措置が必要ではないかと思いますが、いかがか尋ねました。","respondent":"高山健康課長","answer":"２つがあるわけなのですけれども、例えばがん検診に関して言えば、翌年度も受診期限を延長するなどといった柔軟な対応を取らせていただいております。そうは申しましても、健康を確認する意味で必要なことと考えておりますので、その辺は柔軟に対応しています。","id":"exchange-004"},{"speaker":"湯澤委員","kind":"意見","question":"品川区のプラスチックごみの回収の現状と、この法律によって、どう取り組んでいこうと考えているのか。品川区でも来年の施行に向けて基本方針や期間を定めているのかも併せてお知らせくださいとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"品川区は平成２０年から、容器包装リサイクル法に伴って、こういったものについては回収してリサイクルしているというところを進めております。","id":"exchange-005"},{"speaker":"湯澤委員","kind":"質問・要望","question":"自治体としての方針は、いずれしっかりと決めていかなければならないと思いますので、他区の動向も研究しながら取り組んでほしいと求めました。個人がごみを減らしていく、分別をしていく取組みについて、区のお考えを示すよう求めました。","respondent":"品川品川区清掃事務所長","answer":"区としても、常に区民に対して啓発活動等を行ったり、環境学習等も進めているところです。目に見えるものというか、触って感じ取るものなど、そういった感覚のところをいろいろ工夫しながら進めていきたいと考えています。","id":"exchange-006"},{"speaker":"湯澤委員","kind":"質問・要望","question":"企業努力が求められるワンウェイプラスチックが削減されることによって、製品がなくなれば、私たちがごみを出す必要もなくなってくると思います。最後に、品川区として、企業に求めていきたいと思っているところをお知らせほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"求めていくですが、やはりごみの分別というところで、区民の方にはやっていただくというところが１つあるかと思います。いかに分かるような分別を進めていくかというところを、区としても常に研究して進めていかなければならないと考えています。","id":"exchange-007"},{"speaker":"つる委員","kind":"提案","question":"２９２ページ、３１３ページ、エコルとごしでの環境講演やサステナブルファッションショーなどについて伺っていきたいと思います。児童手当については、６月だったでしょうか、国会で法改正があって、これによらない形で済むようになりましたとの意見を述べました。","respondent":"鷹箸保健予防課長","answer":"一部自治体で実施されていることは十分認識していますが、私が認識している限り、小さいシステムであればできるということで伺っています。２３区統一の中では、あと間違いをなくすという観点からも、十分考えていかなくてはいけない問題かと思います。","id":"exchange-008"},{"speaker":"つる委員","kind":"提案","question":"ほかの自治体をいろいろ確認しながら、紙媒体とデータでなるときにも、そうしたことが少しでも軽減されるようなことを事前に対応していただきたい。","respondent":"河内環境課長","answer":"例えばリメイクファッションなどを行うような団体と連携いたしまして、イベントなどによりまして、検討して進めてまいりたいと考えているところです。こういった２点を踏まえまして、ユニフォームの選定につきまして進めてまいりたいと考えているところです。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"人がなかなか集まらなかったり、本当にメッセージを届けたい区民の方に届いていなかったりということにならないような講師の選定というのでしょうか。ぜひその辺りを積極的に検討してほしいと求めましたので、また引き続き質問もしていきたいと思いますし、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鈴木（博）委員","kind":"意見","question":"２８４ページ、２８７ページ、順不同でお尋ねしてまいります。歳入審査でも、あくつ委員による見識あふれる質疑応答がありましたが、まず初めにＨＰＶワクチンについてお尋ねいたしますとの意見を述べました。","respondent":"鷹箸保健予防課長","answer":"予防接種法の第２条に、主に小児を対象として接種努力義務があるＡ類疾病と、高齢者を対象として接種努力義務がないＢ類疾病があります。","id":"exchange-011"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この８年の間、様々な研究が世界中で行われてきて、信頼できる報告が集まってきています。その信頼できるデータについて、簡単にご説明をお願いします。","respondent":"鷹箸保健予防課長","answer":"前提といたしまして、ＨＰＶワクチンは２年前の時点で、世界９２か国で予防接種を実施すべきというプログラムとして取り入れられているワクチンです。","id":"exchange-012"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ＷＨＯは２０２０年、予防接種ストレス関連反応、ＩＳＲＲという新たな病態の概念を提示しました。この予防接種ストレス関連反応、ＩＳＲＲについて、簡単なご説明をお願いいたしますとの意見を述べました。","respondent":"鷹箸保健予防課長","answer":"つまり注射をするということそのものに対する不安が高じて起こる様々な症状を表す概念といたしまして、２０２０年１月にＷＨＯが提唱したものです。特に、ＨＰＶワクチン接種後に生じる様々な症状に当てはまるものが多いとされております。","id":"exchange-013"},{"speaker":"鈴木（博）委員","kind":"質問","question":"定期接種のワクチンの情報提供に、これは一体どういう意味なのでしょうか。勧奨を行うことに問題があるのなら、なぜ定期接種から外すという議論が起こらないのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"一旦中止という方針を決めたときに、ＨＰＶワクチンが子宮頸がんを減らすという根拠自体が否定されていたわけではありませんので、定期接種から外すという方向性にはならなかったものと考えております。","id":"exchange-014"},{"speaker":"鈴木（博）委員","kind":"質問","question":"このような厚生労働省の不誠実で無責任な対応で最も被害を受けたのは、品川区民を含む若い女性たちです。２０１３年６月に積極的勧奨が中断されてから、子宮頸がんの発病を６０％から７０％予防できるということ、区は今どのようにお考えか尋ねました。","respondent":"鷹箸保健予防課長","answer":"非常に残念だと言わざるを得ないと考えております。１年で１,２００人から１,３００人と考えまして、既に１万人近くになるわけでございまして、じくじたる思いを抱くところです。","id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"質問","question":"なぜならば、９価ＨＰＶワクチンは、子宮頸がんを９５％予防できること、２回接種で十分効果が上がることが分かっているからです。区のご見解はいかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"それも９価、９つのタイプが予防できるという、大幅に進化してきたところです。本来、接種対象だったこの方々に対して何らかの対応を考えるということは、今後の重要な課題だと認識しています。","id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、４か月児健診についてお伺いいたします。ＣＯＶＩＤ－１９の流行下、４か月児健診の集団健診の対象人数と受診人数の推移について、ご説明をお願いいたします。","respondent":"柏木品川保健センター所長","answer":"令和３年度、８月までの実績になりますが、対象者１,４８７名、受診者１,３７０名、受診率９２.１％です。今年度、まだ残り６か月ありますが、今年度も例年同様の受診率ではないかと考えております。","id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問","question":"コロナ前は大体９５％ぐらいだったと思いますが、集団健診を補完する位置づけで始めた個別健診の受診人数の推移と、個別健診は、家庭のご事情をよくご存じのかかりつけ医で行われるという、非常にメリットがあると思うのですが、今後の見通しについて簡単にご説明をお願いします。","respondent":"柏木品川保健センター所長","answer":"令和３年度２月から始めまして、令和２年度は４名、３年度、今年度は８月までですが、１２名となっております。今後につきましては、コロナの状況を見ての判断になりますが、延長等については柔軟に考えていきたいと考えております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、区はこの冊子を意義あるものとして評価しているのかどうか。区のホームページに記載はあるのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは、東京都で基本的には１人１冊ということで配っているということで認識しています。区としてどういう形で周知するか、あるいはそういう冊子の提供についても、今後検討していければと考えているところです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"１人１冊、東京都が１冊、区内５か所の総合支所等で配布しています。配って配布を依頼するなど、もろもろ求めたいと思うのですけれども、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"若者等就業支援事業の中で、ぜひ相談してくださいということで、様々周知などもしてきたところです。その辺については、今の委員ご指摘のポケット労働法なども踏まえて、様々な形で検討させていただければと思っているところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"提案","question":"区教育委員会の検査の考え方はどうなったのですか、感染者が１人出たら、品川区教育委員会としてはやるつもりはないのですかと質問しました。ちょっと保健所に伺いたいのですが、区教育委員会はどうしてこういう判断になったのか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"ですから、クラスで１人感染者が出たとしたら、基本的にはクラスで検査をするということでよろしいのでしょうか。伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"内容を入念に検討しましたところ、実施してきた内容と何ら変わりがなく、今さら何でしょうというような議論は致しました。ほとんど検査をしていないということはないのですけれども、今後につきましても、必要な対象には広く検査を実施してまいります。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"希望がなくてもやるべきだと思うのですけれども、唾液等で負担もなくできるわけですから、それで間違いないでしょうか。伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"その中で、必要に応じて必要だと判断した場合に実施しておりまして、これは、希望される生徒あるいは保護者の方を対象に実施するものではありません。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"きちんと検査して、確かに感染者はいませんというところまでなって初めて、感染者がいなかったということが証明されるわけですから。ですから私は、このガイドラインをしっかりと使って、検査をしていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"くにば委員","kind":"提案","question":"衛生費から、２８７ページ、コロナワクチン接種関連について、順不同でお伺いいたします。３月の予算特別委員会にて、プレミアム付区内共通商品券のデジタル化についてご提案申し上げましたとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"１つは、区内の消費喚起という部分があります。これをきっかけに、私どもでもデータを取りながら、キャッシュレスをどのような形で進められるかというような検証ができればと考えているところです。","id":"exchange-025"},{"speaker":"くにば委員","kind":"提案","question":"より積極的に実施して勧奨してみてはいかがでしょうかという点がまず１点と、もう一つ、費用補助が様々出ました。区内事業者のキャッシュレス決済導入の状況について改めて伺いたいのと、それで１つご提案なのですけれども、ご所見を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"キャッシュレスの端末の機械の補助ですけれども、現在、私どもで新型コロナウイルス感染症対応特別助成というものを実施しています。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問・要望","question":"これは要望なのですけれども、品川区には様々な支援のメニューがありますけれども、なかなか事業者で分かりづらいという部分があると思います。続きまして、３０９ページ、企業連携推進事業から、五反田バレー情報発信・ネットワークづくり事業等を伺っていきます。","respondent":"遠藤商業・ものづくり課長","answer":"商店街の連携事業ということで、より効率的な運営ができないかということで、様々検討していたところです。コロナ禍でできないということで、昨年度につきまして大きく２点、やらせていただいたものがあります。","id":"exchange-027"},{"speaker":"くにば委員","kind":"提案","question":"あのときは、例えば５つの商店街で複数の指定店舗を回ったら、商店街で利用できるポイントなどをプレゼントするといった形の事業の提案でした。ココシル品川ではなく五反田バレーと連携して実施するなど、改めて検討がどういう状況であるかなどを伺いたいのですけれども、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"昨年の１１月に実施させていただきまして、商店街と企業とで何かできないかということを、個別に相談などをさせていただいたところです。今年の１１月に大商業まつりというのを商店街連合会でやられるのですけれども、今、進めているところです。","id":"exchange-028"},{"speaker":"くにば委員","kind":"質問・要望","question":"その辺をお聞かせいただきたいのと、あわせまして、これに関しては個店に関するサポートだという切り分けだと認識しています。９００万円が決算額となっておりますけれども、こちらもその事業内容等についてお伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"その課題解決に結びつけて実施するというものでございまして、人数は６人という形になりますけれども、動いているところです。他支援制度の周知あるいは現状把握、支援するもので、商店街を含めて５８件に個別支援を実施させていただいたというものです。","id":"exchange-029"},{"speaker":"くにば委員","kind":"質問・要望","question":"だけれども、ワクチンを接種した後も、ブレークスルー感染、２回接種が終わっても感染するリスクがあるのだと。今、３回目接種というところで言われておりますけれども、ワクチン接種会場でチラシを渡したりする積極的な広報についてお伺いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ、接種を受けたからといって、かからないということではないとも報道はされております。まずはホームページで皆さんに告知していくほうが、より伝わるのではなかろうかと考えますので、その辺りは検討させていただきたいと思います。","id":"exchange-030"},{"speaker":"くにば委員","kind":"質問・要望","question":"確かに、２回接種がかなり進んで終わっているので、マスクを外しているのは意外と高齢者の方が多かったりするというのを伺っております。ふれあい掲示板等で、そちらについての広報をするなりして、２回接種後も決して気を緩めないように広報していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから、３０６ページの産業経済費から、若者等就業支援事業について伺います。それからきちんと健診を受けていただく、その両方をきちんと進めていっていただきたいのですが、見解を伺います。","respondent":"柏木品川保健センター所長","answer":"訪問はできませんが、お母様やお子様の状況、あと相談等を聞き取りながら対応しています。前年比で５割強も電話相談が増えておりますので、そういう部分では対応できていると考えております。","id":"exchange-032"},{"speaker":"吉田委員","kind":"提案","question":"当事者の方たちに伺うと、やはり制度として使いにくいということをおっしゃいます。要は、障害者の方のかかりつけの歯科医で検診ができるようにしていただきたいと思うのですが、いかがか尋ねました。","respondent":"高山健康課長","answer":"本事業につきましては、品川区内の歯科医師会との協力事業ということで進めしています。基本的には公益事業として進めておりまして、歯科医師会の歯科クリニックの方々がご案内先として適切と考えております。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"もし何か見解があったら伺います。区が率先して発生抑制の姿勢を示す施策が必要だと思いますが、見解を伺います。","respondent":"高山健康課長、品川品川区清掃事務所長","answer":"私は、障害者歯科検診についてということで、さらなるご答弁となりますが、本事業は平成２４年にスタートいたしまして、１０年を迎える事業です。そういったものも踏まえながら、今後、歯科医師会とも様々協議を重ねながら… １つ大切なところですが、企業に、それから自然素材等を使って研究をしていくというようなところも大きな１つのポイントとなっております。具体的なやり方等については、いろいろと検討していきたいと考えています。","id":"exchange-034"},{"speaker":"吉田委員","kind":"提案","question":"そのほかに、区内の商店に対して、昔ながらの、容器持参の区民に量り売りを推奨するなど、区として提案する施策に取り組むべきと考えます。","respondent":"品川品川区清掃事務所長","answer":"それから、国への要望等につきましては、法律等でしっかりと国が進めてあります。こういった状況を見ながら、自治体としては動いていきたいと考えています。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"この新しい法律によって、回収が増えるわけですから、自治体の負担増が私には想定されてしまうのです。今後、区として、国に対して拡大生産者責任の拡大を改めて主張するよう求めたいのですが、いかがか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"１つ、素早い動きで対応しているのが、大きく動いているのではないかと考えています。ただ、国も、これはもう十分に意識して進めているものかと思いますので、少し状況を見ながら、その辺は様子を見ていきたいと考えています。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川・生活者ネットワークとしては、自死、自殺を防止する施策を求めておりますが、職を失った人への支援はその意味でも重要だと考えております。区の事業や作業の中から仕事を切り出して任せられるような、何とか仕事を生み出すということも検討すべきと考えますが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"昨年度につきましては就職された方が１６件ということで調査できたのですが、今年度については、まだ調査はこれからという形になっているところです。新たに雇うことが難しいというような形ですので、引き続き、就業センター等で支援していただければと考えているところです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"事業者も、働く人も、両方支援しなければいけないということで、ぜひ何か方法を編み出してほしいと考えています。ぜひそこと連携しながら、各団体の意見も聞いて施策を進めてほしいと考えますが、その辺についてはいかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"現在、直接、子ども若者応援ネットワークとのつながりというのはないところですけれども、こちらを所管している各課と会議などを開いてやっているところですので、今後そういう部分も含めまして検討させていただければと思います。","id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"お伺いしたいのですけれども、令和２年度の燃やすごみ、資源ごみで出す場合もあると思います。そこで、令和２年度の燃やすごみ・資源ごみの、前年度までとの比較で、何か変化があったのか、伺います。","respondent":"品川品川区清掃事務所長","answer":"大体、５％か１０％ぐらいの割合で増えているのではないかという傾向があります。ざっくりですが、そのうち燃えるごみが７万５,０００ｔ、それから資源ごみが２万５,０００tぐらいというような割合となっております。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"ではプラスチックごみ、お店でのレジ袋ではないビニールの袋はどうなったのかということについて、特に見解は述べていないということだと思います。それとも、少なくとも数字上は分からないという結論になるのか、お伺いいたします。","respondent":"品川品川区清掃事務所長","answer":"スーパー等では大体５割ぐらいから７割、８割ぐらいに増えているというような形で、一定の効果は出ているかと思います。多分、それから通信販売等が多くなってきている傾向があるので、段ボールの量が増えているといった傾向はあります。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問・要望","question":"これまでも議会で、自宅療養者の関係は、いろいろ質疑はあったのですけれども、連絡が取れなかった場合の対応のところだけお伺いできればと思います。実際に保健所が連絡を取ろうとしても連絡が取れない場合に、どういう対応をされているのか、お願いいたします。","respondent":"鷹箸保健予防課長","answer":"夜９時や１０時に警察に電話をして、やはり連絡が取れないので来てくださいとお願いすると、一緒に安否確認をしていただいている状況にあります。それは、区内どこの警察、派出所も同じ対応です。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問・要望","question":"どうなのかと思っていたのですけれども、しかもやはり労働量が本当に大変な中でやられているというところで、感謝申し上げます。１つだけ要望というか、再考をお願いしたいと要望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"松澤委員","kind":"確認","question":"１つお聞きしたいというか確認したいことがありまして、亡くなられた方はもうお答えできないではないですか。そういうところを教えていただけますか。","respondent":"鷹箸保健予防課長","answer":"ＮＰＯ法人の自殺対策支援センターライフリンクが実施されました、「自殺実態１０００人調査」という非常に大規模な調査が基になってあります。","id":"exchange-043"},{"speaker":"松澤委員","kind":"質問","question":"オンラインゲートキーパー研修を、これはＹｏｕＴｕｂｅ配信で、今年の１月２１日から開始されました。約２７分の動画を５つに分けて無料で閲覧できるようになっておりますが、これの作成に至った経緯を説明するよう求めました。","respondent":"鷹箸保健予防課長","answer":"ご視聴、どうもありがとうあります。ＮＰＯ法人ＯＶＡが作られたものを、品川区のサイトでも流させていただけるような委託契約を結びまして、今年の１月から配信しているものです。","id":"exchange-044"},{"speaker":"松澤委員","kind":"質問","question":"研修動画にも書いてありましたけれども、ゲートキーパーも１人で抱えない。要は１つに絞ったほうが、ではこの悩みはこの相談窓口にというふうに思いやすいかと考えるのですけれども、これについてどう思いますか尋ねました。","respondent":"鷹箸保健予防課長","answer":"先ほどご説明したとおり、その方のお悩みを整理させていただいて、必要な窓口につないでいく。庁内で今、その方に必要な窓口をご紹介できるような庁内連携も取っておりますので、区役所どちらかの窓口にご相談いただければと考えております。","id":"exchange-045"},{"speaker":"松澤委員","kind":"質問・要望","question":"これは要望です。商店街については、次回質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"提案","question":"私からは、２９５ページ、品川区立環境学習交流施設、３０３ページ、中小企業経営支援事業費、２８７ページ、各種がん検診から質問します。危機感を感じられるような展示内容にしてはいかがですかということをご提案したことがありますが、今どのような形で進んでいるのか、説明を求めました。","respondent":"河内環境課長","answer":"一層緊張感などを持つことで、環境学習、温暖化に対する心構えの効果が増すと考えております。気温や天候、季節感など、危機感を体感しながら学習効果を上げていきたいと考えているところです。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問","question":"次に、３０３ページ、中小企業経営支援事業費で、持続化給付金・感染拡大協力金申請の相談窓口について伺います。決算の中での事業の目的、そして誰が委託されてこの事業を実施したのか、一体何を相談する窓口だったのか、説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"その後も引き続き第２期ということで、今年の１月１５日まで、引き続きやらせていただいたところです。当初、東京都中小企業診断士協会城南支部の方に委託という形でお願いして、中小企業センター１階ロビーに臨時窓口を設置させていただいたところです。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問","question":"１７回ですから。何で申請代行ができないのか、やらなかったのか、そこについて説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"いわゆる書類が準備できていた段階ですと、入力の代行ということであれば、国で設置した申請の窓口が全国に置かれたですので、そちらをご案内したです。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２,７００万円の予算を計上して、みんな手持ちの資料を持っていって、これはどうすればいいのですか。きちんとニーズにマッチした窓口をつくっていただきたいのですが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"そうなると、中小企業診断士にその中身を確認していただいて、こんなふうですよというような部分もあったかというところで認識しています。私どものほうで、相談窓口などがありますので、その中でご相談をお受けできればと思っているところです。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２８７ページの各種がん検診について伺いたいと思います。これは必要性を認めるというご答弁を前に頂いていますけれども、これはぜひ実現してほしいと求めましたが、いかがか尋ねました。","respondent":"高山健康課長","answer":"昨年の中旬から、日本対がん協会がそういった啓発活動に取り組んでおりまして、ＦＭしながわでの番組などを通じて広報などをしてきているところです。","id":"exchange-051"},{"speaker":"せお委員","kind":"質問","question":"新型コロナウイルスワクチン接種対応経費の主な内訳を教えてください。さらに、国からの補助があると思うのですけれども、このうち区の持ち出しはどのくらいあるのか、説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"そして４００万円が、システムの改修費という形になります。こちらは、国からの補助金ということで、全額負担ということになっております。","id":"exchange-052"},{"speaker":"せお委員","kind":"質問・要望","question":"そして、コロナワクチンの３回目接種の準備状況についてなのですけれども、検討だけはしておいていただきたいという思いからお聞きします。これまでの実施状況や課題というのは、具体的にはどんなことか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"特にかかりつけにかかっていらっしゃる被接種者の方に関しましては、医師が診療履歴から、きめ細かな対応が可能といった利点があります。かつ８か月後ということが示されており、バランスよく会場を設置して、皆様の接種を進めていければと考えております。","id":"exchange-053"},{"speaker":"せお委員","kind":"質問・要望","question":"さらには、看護師の方とお話ししていたら、７月からは、ワクチン接種のシフト希望を出しても全然入れなかったとお聞きしました。３回目の対象者は、３回目接種の際の会場の準備をしていただきたいと私は考えますけれども、その辺の細かいところの見解を伺います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"当然、３回目のお話も現在進めているところで、会場設営については、現在まさに協議しています。引き続き、皆様がスムーズに接種できるような体制を取れるように、今後、協議してまいりたいと考えております。","id":"exchange-054"},{"speaker":"せお委員","kind":"質問","question":"令和２年度の当初予算を見ると、いわゆる母子健康手帳の１冊の単価は１１０円となっていますが、平成３１年度は１０８円でした。少しではありますが、なぜ上がったのかを、ご存じでしたら説明を求めました。","respondent":"高山健康課長","answer":"母子健康手帳の購入価格の変更理由です。いわゆる消費税が改定になったという点を踏まえて、その辺の部分が単価に反映されているところです。","id":"exchange-055"},{"speaker":"せお委員","kind":"提案","question":"母子健康手帳に関しては昨年の決算特別委員会で取り上げましたが、今日は３点ほど提案させていただきたいと思っています。こちらの見解を伺いますとの意見を述べました。","respondent":"高山健康課長","answer":"父親なども受け入れやすいネーミングなどは検討すべき時期にはなっているかと考えておりますので、その辺は柔軟に考えていくべきかと思います。転居された先でもやはりご認識いただかなければなりませんので、併記なり何なりという形で、重要かと考えております。","id":"exchange-056"},{"speaker":"せお委員","kind":"確認","question":"予算の面でも、少し単価が上がっても、区内産業の支援にもつながりますし、費用対効果は高いのではないでしょうか。こちらの見解を伺います。","respondent":"高山健康課長","answer":"やはり１冊１００円ちょっとと安価で、医師会の定める任意様式が、コンパクトに１００ページ前後で十分にまとまっている。貸与するということも十分検討の範囲だと思いますので、先ほどのネーミングのご提案も含めて、今後検討してまいりたいと考えております。","id":"exchange-057"},{"speaker":"せお委員","kind":"提案","question":"母子健康手帳に加えて、小さな成長も大きく喜べるような工夫がなされている手帳があると前向きになれると提案させていただきました。それをホームページでご紹介してほしいと要望したところ、「より行き届いたホームページの掲載などは、こちらの進捗状況をお願いいたしますとの意見を述べました。","respondent":"高山健康課長、柏木品川保健センター所長","answer":"様々な方々が見ることを前提に、必要な情報が今段階で十分でないということであれば、ホームページについてはさらなる充実・拡充に努めてまいります。様々、そういったものも１つ採用していくに十分な状況になりつつありますので… 私からは、すくすく赤ちゃん訪問での手帳の配布等についてですが、手帳の採用が決まりましたら、その点についても検討はしたいと思います。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私からは、２８５ページから２８９ページにかけて、新型コロナ感染症対策について伺いたいと思います。１年９か月も過労死ラインを超える残業が続くことになったことに対して、また改善の方法はなかったのか、伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"コロナ対応に従事している職員の状況ですけれども、特に第５波においては、対応してきたところです。平常時よりも３０人ぐらい多い人数で対応しておりましたので、今回の第５波は乗り切ったところですが、第６波に向けての検討も進めているところです。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"午後８時頃と、私は保健所としての、これまでの検証や今後に向けた対策というのを考えることが必要なのではないかと思うのです。こういった検証・分析を行い、次につなげていく取組みも必要なのではないかと思いますが、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"今後につきましては、感染状況を把握する、あるいは区民の方の感染予防に役立つ情報については、公表も含めて考えていきたいと思います。第６波に向けて、保健所だけで対応するというのではなく、あるいは支援するといったことについても。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区の状況を伺いたいのですが、亡くなられた方は、８月と９月２６日までで３９名となっております。５０代以下の死者数、それから重傷者数が何人か、分かったら説明を求めました。","respondent":"鷹箸保健予防課長","answer":"運ばれて、死後、陽性と分かる方もいらっしゃったり、統計の取り方に非常に難しい部分があろうかと思います。現在までのところ、品川区の１４５人、確認した死亡者のうち、最年少が４０歳、最高齢が１００歳の方で、平均８０.１歳という状況です。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どうしたら重症化や死亡者をなくすことができるかという対策が必要だと思いますけれども、２８人に実施して、伺いたいと思います。混乱はしないのではないかと思うのですれけども、ぜひこの公表も検討してほしいと求めましたが、改めていかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"発症後７日以内、特に４日頃から治療するのが一番効果があるということもありますので、積極的に患者をつなぐ努力はしてまいりました。そこは医療機関とも、常に情報交換できる関係ですので、ご相談しながら考えてまいりたいと思います。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"調理師や用務の方、ワクチンを希望する方は全員できるようにということでしていただきたいと思うのですけれども、その点が１点です。本当に子どもたちに密接に接しますので、定期的なＰＣＲ検査を改めて求めますが、いかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、鷹箸保健予防課長","answer":"保育士への接種についてですが、集団接種会場が開設された当初から、集団接種会場のキャンセル枠の分を、優先的にリストを作りまして接種していくという体制を整えまして、そのリストの方が打ち終わったと報告を聞いております。 保育士への定期的な検査については、また今後の課題としていただきたいと存じます。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう方々というのは常にリスクがあるわけですから、やはり考えていくべき時期に来ているのではないかと思いますが、そのお考えをお聞きします。それはどういうふうにお考えになるか尋ねました。","respondent":"鷹箸保健予防課長、遠藤商業・ものづくり課長","answer":"できないの部分も含めまして、非常に難しい部分がありますので、なかなか公表することは難しいのではないかと考えております。ワクチン接種後の抗体検査ですけれども、まだ国の方針等も不明確な部分もありますので… そういう部分で、個人的な考えはありますけれども、一定程度、当時はやむを得なかった部分はあるのかと思っているところです。","id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜそれを公に言わないのですか。そこを言っているのですけれども、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"第６波に向けて、ホームページが分かりにくいのではないかというところも認識しておりますので、分かりやすく変更することを考えております。","id":"exchange-065"},{"speaker":"西本委員","kind":"質問","question":"やっているのですから、それをきちんと公表してください。そして、区民の皆さんに安心を持たせていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"こんの委員","kind":"質問","question":"項目は５点ありますので、分けてお聞きしたいと思います。もう一つが、医師会との連携や接種体制について、まずこの２点をお聞きしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今後３回目の接種に向かいまして、改修もしくはシステムの変更も視野に入れながら、これから検討を進めてまいりたいと考えています。集団接種会場もやはり置くことを念頭に置きながら、個別接種会場とのバランスも踏まえながら、今後検討を進めてまいりたいと考えています。","id":"exchange-067"},{"speaker":"こんの委員","kind":"質問","question":"２０代と接種が進む頃が、薬の供給というところも国としてどういうふうにするのか、接種しやすい環境になるといいと思います。もう一つは、当日キャンセルが出た場合のワクチンの活用についてはどんなふうにお考えか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"前回の自治体説明会ではありましたが、今後、検討を進めてまいりたいと考えております。週に１回、どのような運用方法ができるかということも協議を進めていきながら、庁舎の中でも協力を仰ぎつつ検討を進めてまいりたいと考えております。","id":"exchange-068"},{"speaker":"こんの委員","kind":"意見","question":"もう１回目と２回目というのがなく、私としては、一気に全員に接種券を配るという考え方もあっていいのではないかと思います。必ず２回目以降、８か月後となっていますので、接種券についてだけお答えくださいとの意見を述べました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"まさに委員ご指摘のとおり、段階的に発送する方法と、それから一括して発送する方法、現在、検討を進めております。ただ、一括で発送するか、段階的に発送するかというのは、今後の状況を踏まえて検討してまいりたいと考えております。","id":"exchange-069"},{"speaker":"こんの委員","kind":"意見","question":"今後、この体制について区としてどのように考えているか、お答えを頂きたいところですが、一応、時間もないので。そうしたことが分かりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"医師会の先生方から頂いた要望で、ワクチン接種に関わる経済的負担の支援についての確認をさせてほしいと求めました。医師会の先生方から要望いただいたのですが、それについてはもう実施されているとお聞きしたのですけれども、そこの確認をしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"両医師会の皆様とは、そういったお金の面につきましても、協議をずっと重ねてまいりました。その辺りにつきましては、医師会との協議の上、お支払いをするということでお話しさせていただきました。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、全てにおいてではないのかとは思うのですが、でもそのための費用は国から出るということでいいのでしょうか。そしてこれは、私たちは７月に要望を頂いたのですけれども、その後、いつぐらいに実施決定がされたのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"国から全額補助金が出るということで、国からは通知を頂いております。新たに発生する費用もありますので、その辺りについてはいろいろ協議を重ねた結果で、お支払いするということになりました。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今後も、特にやはりコロナの対策においては、様々、要望に応えていただきたいですし、さらに強く連携してほしいと求めました。全額助成された下での、インフルエンザ予防接種の実施率を説明するよう求めました。","respondent":"鷹箸保健予防課長","answer":"昨年のインフルエンザ予防接種ですが、６５歳以上の対象の中で、実施人員８万３,２５６人のうち、５万３,２４２名の方が接種されまして、６３.９％でございました。","id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問","question":"そして、状況は昨年と変わっていないのに、なぜ昨年と同様ではないのか。全額助成が継続されないのはなぜか、伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"重症化予防も含めて負担するという方針を出されたために、そのような都からの追加の措置はないということを確認した上で、これまでどおりの２,５００円の負担ということで進めしています。","id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"第６波の可能性も強く言われているという下で、去年も、翌年の１月の第３波を控える下での１０月のインフルエンザの予防接種だったのです。そして東京都がやらないのであれば品川区として、全額助成できるのではないかと思うのですけれども、その状況の違いを説明するよう求めました。","respondent":"鷹箸保健予防課長","answer":"繰り返しのご説明になりまして恐縮ですが、昨年と今年の違いは、昨年はコロナワクチン接種が始まっていなかったという部分。これまでどおりと考えさせていただいておりまして、今回の決算書の１２５ページにあります、１億３,０３０万８,０００円です。","id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区独自で、私たち共産党は、誰もが費用の負担を気にせずに安心してインフルエンザ予防接種ができるように無料化を求めてまいりました。先ほどの６３％という接種率を考えれば、実施していく効果はあると思うのですけれども、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"港区において６５歳以上全員無料というのは、もともとそれ以前から無料ですので、そこと品川区を比べていただいても検討する土台が違うかと思います。本当にその他の感染症も、感染予防についての普及啓発をまたしっかり広めていくことも、区としては重要かとも考えております。","id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"コロナにかかわらず、安心に打てるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"高橋（し）委員","kind":"質問","question":"衛生費の第１項で、先ほどの約４億円というものが生じているにもかかわらず、項と項で流用せざるを得なかったという理由をお尋ねします。もう一つですが、同一の項の中において、職員給与費の不足が生じた場合、ほかの目からの流用はできないのか、お尋ねします。","respondent":"黒田財政課長","answer":"そういった中では、執行状況に鑑みながら、流用できる事業や科目というところを見て流用しています。基本的には１課１目ですので、近いと申しましょうか、基本的には性質別予算という特性の中で流用しています。","id":"exchange-078"},{"speaker":"高橋（し）委員","kind":"質問","question":"ほかの項からの流用があるにもかかわらず、健康推進費にその金額以上、４,０００万円以上を流用しています。このようなことから、当初予算の組み方と予算流用のあり方について、また不一致について、財政当局のお考えをお伺いいたします。","respondent":"黒田財政課長","answer":"新型コロナウイルス感染症の感染状況で、特に年末から年明けにかけての感染急増の中で、年度末までの執行見込みがなかなか立てられなかったと。当初の段階で見込めるものについては、見込んで予算を立てなければなりませんが、議会の議決を頂くと。","id":"exchange-079"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほど一部ご説明いただきましたが、先ほどの質問とも関連し、監査委員からこのような意見が出ていると。区として予算執行のあり方について、このようなご指摘を受けて、どのようにお考えになっているか、お伺いいたします。","respondent":"黒田財政課長","answer":"いわゆる指定管理者制度を取っていても、利用料金制度を取っている施設とそうでない施設であれば、そういった財政上の違いがあると認識しています。それに対してどのように対応するかということで、流用で対応できるのか、今回についてはこのような執行になったと認識しています。","id":"exchange-080"},{"speaker":"高橋（し）委員","kind":"質問","question":"これは今後も、そういった協議が契約事項などに記入されて、来年度以降もそういうことがあるのでしょうかということが１つ。今回の１億円以上の事業間流用ということに関して、それとの違い、その点についていかがか尋ねました。","respondent":"黒田財政課長","answer":"これから年度協定を結ぶ中で、どういった協定を結ぶかについては、各所管で事業者と様々協議がなされるものと認識しております。年度末までの施設の、どのように開けられるかというような状況が見えなかったという中で、このような執行となったというものです。","id":"exchange-081"},{"speaker":"西村委員","kind":"提案","question":"３０５ページ、産業支援交流施設運営費、３０９ページ、五反田バレーについて、順不同で伺ってまいります。実際に、五反田バレーの理事企業から３社、既に上場していると伺っていますとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"先ほど今度の大商業まつりでスマホを使ったスタンプラリーを実施するという部分と、また武蔵小山でＶＲを使ったイベントなどを今考えているです。","id":"exchange-082"},{"speaker":"西村委員","kind":"質問","question":"今おっしゃった中延商店街ですか、２０２０年の年末からの指導かと思うのですけれども、その辺りも併せて説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"ウェブサイトを運用するにあたって、なかなかうまくできないというようなところが一番あったようです。この辺も早速取り入れて、一部の店舗でやられているというような話は聞いているところです。","id":"exchange-083"},{"speaker":"西村委員","kind":"質問","question":"コロナウイルスがまん延する前に、一度、五反田バレーにお話を伺ったことがあるのですが。実際にやらなければならないという雰囲気に変わったように感じると、先日お話を伺いましたら、おっしゃっておられました。","respondent":"遠藤商業・ものづくり課長","answer":"商店街がなかなか痛んでいるというところがございまして、中にはなかなか会費が取れないなど、いろいろな相談を受けたところです。そういう中において、そういう部分につきましては、私どもが昨年からやらせていただいているエリアサポーターなどでも話を聞いているところです。","id":"exchange-084"},{"speaker":"西村委員","kind":"質問","question":"区内には産業支援交流施設が幾つかありますが、私はいろいろな区民の方からお話を伺いまして、ＳＨＩＰが大変人気だという印象があります。大手銀行の資金調達相談会や個室もすぐに埋まるとか、３Ｄプリンタなどのある工房もコロナ禍で利用者が増えたと、区民委員会で伺いました。","respondent":"遠藤商業・ものづくり課長","answer":"武蔵小山創業支援センターは当初から、なかなか子育ての関係があってできないという方も、そういうところで運営をさせていただいているところです。子育てのところという部分ですので、例えばセミナーなどという部分も含めて、今後も充実させていきたいと考えているところです。","id":"exchange-085"},{"speaker":"西村委員","kind":"質問・要望","question":"本当に、キャッチコピーでもいいぐらい、前面に出していただきたいと考えています。保健センターに案内を置いていること、また区内保育園・幼稚園にチラシを配布していくなどもいいと思うのですが、ご意見を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"そのようなセミナーを、ＳＴＯＲＥＳという企業なのですけれども、そちらと共催でやらせていただいたようなところがあります。あるいは各保健センター、保育園等に関係各課と相談しながら、できるだけ周知はしていければと考えているところです。","id":"exchange-086"},{"speaker":"西村委員","kind":"意見","question":"例えばホームページを拝見しておりますと、満員御礼でキャンセル待ちというふうな、マネジャーとの相談会などがございまして、今、武蔵小山創業支援センターで人気のセミナー、満員になるほどのセミナーはどのような内容か、説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"これは比較的早く埋まってしまったので、また機会があれば、そういうものをやっていければと思っているところです。","id":"exchange-087"},{"speaker":"西村委員","kind":"質問・要望","question":"ちょこっと起業予備軍、プチ起業家、２つの利用者像を想定したと書かれております。ターゲットがもう少し分かりやすいように、区民の方が迷わないように検討をお願いしたいと思うのですが、ご意見を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"表現の仕方は、いろいろと私どもも工夫して、できるだけ伝わるようにというところでやらせていただいているところです。いろいろな案が出ようかと思いますので、できるだけ伝わるような、いろいろな表現を考えていきたいと考えています。","id":"exchange-088"},{"speaker":"西村委員","kind":"意見","question":"その表現がいいのかどうかはぜひとも熟考いただいてと思うのですが、ご検討をお願いしたいと思います。若者をどうやって西大井に呼び集めてくるかというようなところで、何か戦略がございましたら説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"学生が比較的若いというところで、それぞれの大学にこのようなものができますということで既にお話などをさせていただいているところです。","id":"exchange-089"},{"speaker":"西村委員","kind":"質問・要望","question":"確かに西大井駅には横須賀線も相鉄線も湘南新宿ラインも、いろいろ通っていて便利なのですが、なかなか若者はチラシなどを見ないという現状もありますので、ぜひＳＮＳも戦略に取り入れていただいて、若い方たちに知ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"木村委員","kind":"質問・要望","question":"メードイン品川ＰＲ事業は平成２４年度から始まった事業ですが、幾つの製品が世に出たのか、ご紹介ください。そして、中には世界に誇れるような製品もあろうかと思いますけれども、お聞かせほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは、件数といたしましては、今まで３１件の認定をさせていただいたところです。販売促進のために、「メードイン品川」ということで選ばれましたということで、広くお使いいただいているということは聞いているところです。","id":"exchange-091"},{"speaker":"木村委員","kind":"質問・要望","question":"区内景況と、現在の区内事業者の状況と、新型コロナウイルス感染症に伴う各企業への影響と支援についてお尋ねいたします。現在の区内企業の景況についてお聞かせいただきたいのと、今後の景況感についてどのように考えていらっしゃるのか、お聞かせほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"逆に１０月になりまして、緊急事態宣言が解除になったところです。全般的な景況としては、かなり動き始めているのかなというところがありますので、このままどんどん改善していけばいいと考えているところです。","id":"exchange-092"},{"speaker":"木村委員","kind":"意見","question":"例えば飲食業の方からの申請はあったのかどうか。今年度も引き続き、こちらの新型コロナウイルス感染症対応特別助成は行われたかと思いますが、今年度の申請状況についても説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"販路拡大助成金と新型コロナウイルス感染症対応特別助成金を合わせまして、１,４０９件で、２億１,７１０万７,０００円です。１期ということで５００件ほどを見込んでいたところ、予定より多く申請頂いているところでございまして、今年につきましても。","id":"exchange-093"},{"speaker":"木村委員","kind":"質問","question":"コロナ禍での商店街のにぎわいについてお聞きいたしますが、商店街は、地域住民の交流の場として重要な役割を担っております。お伺いいたしますけれども、どのような課題があり、またどのような対策をされるのかをお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"昨年の商店街イベント実施状況ですけれども、実施に至ったのが１４件、実施したものについても縮小というような傾向があったところです。イベント実施に向けて商店街課題解決支援等を行うとともに、今、助成率を３分の２から５分の４に引き上げたところです。","id":"exchange-094"},{"speaker":"大沢委員","kind":"質問・要望","question":"それと、２９７ページ、ワンウェイプラスチック削減ということで、今日は淡々と質問させてほしいと求めました。このところで、まず環境学習交流施設、来年５月ということですけれども、メインとなるコンセプトやテーマというのは何なのか尋ねました。","respondent":"河内環境課長","answer":"１秒で何が起こっている、その日に自分で考えたこと、来館された方が思いを共有する展開を予定しています。生活しやすいという点で、自分の生活の中にある環境について学べるようにというようなところを大事にしていきたいと考えているところです。","id":"exchange-095"},{"speaker":"大沢委員","kind":"意見","question":"彼ら彼女らが余計理解しやすいように、どのような工夫を施すように考えていらっしゃるのか、お願いしますとの意見を述べました。","respondent":"河内環境課長","answer":"中には、環境に対して少しシリアスに考えさせるような内容もありますが、おばあ様に対する内容が盛り込めますよう工夫しながら進めているところです。","id":"exchange-096"},{"speaker":"大沢委員","kind":"質問","question":"ＺＥＢについて少し聞きたいのですけれども、ＺＥＢ以外のネット・ゼロ・エネルギーというのはほかに何があるのですか。説明を求めました。","respondent":"河内環境課長","answer":"そのほか、ＺＥＶといいまして、vehicle、車用などがあります。ＺＥＢの中でも７５％以上ということで、こういった魅力を活かしながら、他のＺＥＢについても普及促進に努めていきたいと考えているところです。","id":"exchange-097"},{"speaker":"大沢委員","kind":"質問","question":"最初に聞かなければいけなかったのですけれども、エコルとごしということですけれども、募集方法など、どのぐらい応募があったのか。その思いについて、課長はどのように捉えられているか、説明を求めました。","respondent":"河内環境課長","answer":"豊葉の杜学園など、近隣の学校と連携しながら、こういった広報を進めたところです。今後の館の運営について努力していきたい、非常に身の引き締まる思いですが、頑張りたいと考えています。","id":"exchange-098"},{"speaker":"大沢委員","kind":"質問","question":"ぜひお願いします。プラスチック削減についてですけれども、エコルとごしではワンウェイプラスチック削減についてどのような取組みをされるのか、説明を求めました。","respondent":"河内環境課長","answer":"そういったものの運用によりまして、まずはペットボトルの削減に努めるとともに、再生木材を使いました容器でやっていきたいと考えているところです。","id":"exchange-099"},{"speaker":"大沢委員","kind":"質問","question":"では最後の質問になりますけれども、ハクビシンについて聞かせてください。ここは先ほどページ数を言いました２９５ページに入っていますけれども、過日、目撃件数や捕獲件数を説明するよう求めました。","respondent":"河内環境課長","answer":"箱わなを設置いたしまして捕獲いたしますが、令和２年１年間で９件、また令和３年では８月末現在で１件です。","id":"exchange-100"},{"speaker":"中塚委員","kind":"質問","question":"３１１ページのマイスター店等支援事業に関わって、飲食店支援について、それぞれ伺いたいと思います。区有施設のＣＯ２削減ですけれども、どのように取り組んでいるのか、伺いたいと思います。","respondent":"河内環境課長","answer":"区有施設の省エネ設備など改修時の対応です。そういった省エネ機器の検討を行いまして、置き換えていくというようなところをもちまして、まずは省エネに努めてきているところです。","id":"exchange-101"},{"speaker":"中塚委員","kind":"質問","question":"どこでどう電力使用量を減らすことができるのか、探すことも必要だと思いますけれども、現状の取組みを伺いたいと思います。計画当初から発電量の確保を位置づけて進めていくことが、区として必要ではないかと思いますが、いかがか尋ねました。","respondent":"河内環境課長","answer":"比率として６５％の方が、やはり新築の方がというところで、後から乗せるとなると荷重的な問題もあって難しいという認識です。先ほど他の委員の質問に出ましたＺＥＨ、こういったものを推進しながら、ＣＯ２の削減に向けてというところで取り組んでいるところです。","id":"exchange-102"},{"speaker":"中塚委員","kind":"質問・要望","question":"区有施設のことを伺っているのですけれども、従来の施設の場合も、再生可能エネルギーの普及をしっかりと位置づけてほしいと求めました。新規事業は規制していく、抑制していくという対応が必要だと私は思いますが、いかがか尋ねました。","respondent":"小林施設整備課長、河内環境課長","answer":"私から、区有施設の太陽光発電の設置の現状についてご説明いたします。反射光が近隣の皆さんに影響が出る区有施設も中にはございまして、それらを総合的に判断しながら、可能な限り太陽光の設置を進めているところです。 再開発におきまして、新しい施設というところで、熱源設備など新しい技術を用いますとＣＯ２の削減につながることもあるということで、ストレートに規制というところでは、考えとして持っているものはございません。","id":"exchange-103"},{"speaker":"中塚委員","kind":"質問・要望","question":"飲食店のオーナーにお話を伺うと、自分の給料はゼロで、貯金を切り崩して生活やお店を回していると切実に訴えておりました。お店の売りや味を知っていただいて、コロナ収束後の来店につなげることに期待したいと思いますけれども、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"飲食店の支援という部分ですけれども、品川区商店街連合会と連携させていただきまして、それをご利用いただいているところです。各店舗の売りの商品などが載っているというところでございまして、現在、２０６店舗の掲載があるです。","id":"exchange-104"},{"speaker":"中塚委員","kind":"質問・要望","question":"語り合ったり、はしゃいだり、１人で飲むこともあります。支援を強めていただきたいと思うのですけれども、今後の支援の強化もご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"今年の２月に、飲食店への支援といたしまして、飲食店の売上につながるような施策などもいろいろとやらせていただいたところです。いろいろな支援を、その辺と連携しながら、ぜひ飲食店の灯を消さないような形で施策をやっていくような形で努めてまいります。","id":"exchange-105"},{"speaker":"中塚委員","kind":"質問・要望","question":"コロナ危機がここまで長期化していて、そもそも飲食店業界というのは１０年後の生存率がとても低いのです。ぜひ様々なことを具体化していただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"たけうち委員","kind":"質問・要望","question":"どのような状況、どれくらい集まったのかという、その辺があれば教えてほしいと求めました。そこには全部は出せないのでしょうけれども、このようなお店が使えますよというのをどのような形で考えていらっしゃるのか、説明を求めました。","respondent":"品川品川区清掃事務所長、遠藤商業・ものづくり課長","answer":"それで、年間のスケジュールとしましては、今年度末をもちまして閉店というようなスケジュールで進めていきたいと考えています。区民の混乱に対してですが、広報等、いろいろな媒体を使いまして周知をしていきまして… それから当然、アプリを入れていただいていますので、アプリ上で使える店舗については出てくるような仕組みを取っているところです。それを見て、この店は使えるのだということで判断いただければと思っているところです。","id":"exchange-107"},{"speaker":"たけうち委員","kind":"質問","question":"そういう中で、やはりもう少し積極的に、ＰａｙＰａｙから情報をもらえないのですか。そんなにお金がかからないのですから、これは早急にやってもらったらいいのではないかと思うのですが、お話を伺いたいと思います。","respondent":"品川品川区清掃事務所長、遠藤商業・ものづくり課長、佐藤企画調整課長","answer":"環境省が、引き続き、アフターメダルプロジェクトということで、小型家電回収を進めているというところは把握しています。これにつきまして… 店舗の広報の仕方ですけれども、リスト自体は私どもで、今現在という形になりますけれども、頂いているところです。その辺… リサイクルショップ「リボン」跡の活用についてです。委員ご指摘のとおり、周辺環境、建物の状況や、立地や広さも含めて、今後検討を進めてまいります。","id":"exchange-108"},{"speaker":"芹澤委員","kind":"提案","question":"私からは、２９５ページ、環境啓発・推進事業、３０９ページ、販路拡大事業、３１１ページ、商店街にぎわい創出事業についてお伺いします。これは具体的な提案になりますが、今、我々の目の前にあるアクリル板のリサイクルをぜひ検討していただけないかという趣旨でご提案しますとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"不純物がほとんどないようなものになりますので、こういうものに関しては、リサイクルは非常にしやすいのかなとは感じているところです。","id":"exchange-109"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ご見解をお聞かせいただきたいのと、店舗もかなりの数を持っていて、これも多分いずれ捨てるのだろうと思うのです。何か象徴、シンボルとなるようなものを作るというような環境の啓発というのもあるのかと思うのですが、そのご見解についても併せて説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"リサイクルは非常にしやすい素材ではあるということもありますので、答弁が重なりますが、いろいろな方向から研究は進めていきたいと思います。うまく地域等と絡める方法等といったところも含めて、いろいろと研究していきたいと思います。","id":"exchange-110"},{"speaker":"芹澤委員","kind":"質問","question":"では、次に、販路拡大事業についてお伺いします。新型コロナウイルス感染症対応特別助成という名前で、コロナウイルスが明けた後のこれからの展開というのを、まずご見解を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"途中から、第２回目からは新型コロナウイルス感染症対応特別助成と名前を変えさせていただいて、広く周知に至ったです。業種によっていろいろあろうかと思いますけれども、そういう部分の支援策みたいなものを、今後積極的にやっていければと考えているところです。","id":"exchange-111"},{"speaker":"芹澤委員","kind":"質問・要望","question":"まさにそれが私の要望でありまして、まず５分の４の補助金というのはぜひ続けていただきたいという思いがあります。営業の補助というのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"ウェブ広告、今度は対面的なものもいろいろ出てくるものかと考えています。実際にどこまでできるかというところはありますけれども、いろいろな形で企業の支援につながっていくような施策を検討していきたいと考えています。","id":"exchange-112"},{"speaker":"芹澤委員","kind":"質問・要望","question":"地域のご支援というのもぜひご検討いただきたいと思っていまして、どうしたらいいのか分からない、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"それぞれの商店街に合った支援という部分になろうかと思います。それは費用助成という形になりますので、そのようなものを使って、それぞれの特徴を出しながら、商店街の振興につなげていければと考えております。","id":"exchange-113"},{"speaker":"芹澤委員","kind":"提案","question":"最後に、商店街にぎわい創出事業のところで、商品券についてお伺いします。あわせて、当然ですが、例えば品川区の商店街の中の目黒区の店舗や大田区の店舗でも商品券が使えるような考え方にならないかという思いでの提案ですとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"品川区と目黒区にまたがっている商店街で、もしかすると、そういう部分ではお使いいただけるケースもあるのかと考えているところです。今、意見、お話を頂戴いたしましたので、そこにつきましては商店街連合会に伝えていきたいと考えています。","id":"exchange-114"},{"speaker":"大倉委員","kind":"質問・要望","question":"この約３００万円は毎年、どのように捉えていますでしょうかということと、その辺を教えてほしいと求めました。第１・第３（の何曜日）は、ほかの自治体等でも進んでいるのですが、こういった考え方について教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長、品川品川区清掃事務所長","answer":"この方法が適切かというところで検討してまいりまして、一応、昨年度で検討ということを一旦休止という形にさせていただいているところです。今後、ＳＮＳを活用したものが、今、集客という部分で大きいところがありますので… やはり啓発の部分では難しいところの部分ではないかと考えています。それからチャットもそうなのですけれども、そういったところもいろいろと検証しながら、今後こういう部分については進めていきたいと考えております。","id":"exchange-115"},{"speaker":"大倉委員","kind":"質問・要望","question":"なかなか結構画期的な取組みだったということを伺ったのですが、１個、その辺に関してのお考えを教えてほしいと求めました。１点、品川区はあるのでしょうかというところと、その辺を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長、品川品川区清掃事務所長","answer":"店舗の支援ということで、うまいもの巡りみたいな形で、効果的な個店の支援みたいな形でやらせていただく部分もあります。いろいろな方法があるかと思いますので、今後も検討していきたいと考えています。 そういう啓発の一環として、強化月間というのも１つの考えとして参考にしていきたいと考えております。","id":"exchange-116"},{"speaker":"須貝委員","kind":"質問","question":"区内産業の実態について、またお聞きしますが、認識を教えてください。そして、今、区がこれを改善するために取り組んでいる有効な、中小規模の商店や事業所への支援は何なのか、説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"現在の産業に関する認識ですけれども、区ではありませんけれども、厳しい状況ではあるというところは認識しています。その部分、１４０万円を直接渡すという方法もあるかと思いますけれども、やはりこちらをベースにやっていきたいと考えております。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"それから産業支援交流施設運営費等、あと就業支援費ですか、様々なものを支援しています。意味が、完全に効果がなくなったのではないかと思うのですが、その辺についてご見解を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"それぞれいろいろな助成や支援をさせていただいたところです。そのほかにつきましても様々いろいろありますけれども、基本的には私どもの支援につながっているものということで考えているところです。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"確かに、一時的に融資あっせんなど、様々支援をしても、それはあくまで一時しのぎであって、延命だけではないのでしょうか。ですから、この支援金、そして様々な助成云々のほうに予算を投入すべきだったのではないか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"ただ一方で、まずそれをやらない限りは現状維持ができないということで、融資なども拡充させていただいたところです。区内の経済を回すというところに重点を置いて施策を展開していますので、引き続き、そのような形の考えは持っていきたいと考えています。","id":"exchange-119"},{"speaker":"須貝委員","kind":"質問","question":"例えば１軒ずつ回って、改善をしてください、感染リスクを減らすように努力してください、そういう対応をしたのでしょうか。商業・ものづくり課で、この制度に際してどのような協力・対応をしたのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"私ども、各商店街に、あるいは区の助成金を使ってそれに合うようなものをやってくださいというようなことで周知などをさせていただいたところです。","id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"本来なら東京都がやるべき仕事なのかもしれないのですけれども、回れるかどうかはあれですが、１軒ずつ回る。改善させていくべきだったのではないのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"都でいろいろ検討されてつくられたものでございまして、正直、どういう仕組みになっているかというのを確認しながらやらせていただいたところです。","id":"exchange-121"},{"speaker":"須貝委員","kind":"質問","question":"学校でも庁舎でも、様々な区有施設で、それなりの感染対策を実行しているではないですか。だったら、小さな、中規模の商店に対しても、産業振興として、経営支援として、しっかりやるべきだったのではないのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"飲食店のほうでの指導という形になろうかと思います。なかなかこちらでそこまで推奨するというのは難しいのかなとは思っているところですが、いろいろな店舗で考えていただければと思っているところです。","id":"exchange-122"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、先ほどからお話が出ていますけれども、ワクチン接種が全世界に行き渡るまで、コロナは５年、１０年かかるわけです。この間、コロナが変異している以上、日本でもそういうことがありますので、私は末永く共存するということを考えて対策をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"のだて委員","kind":"質問・要望","question":"家賃支援給付金の２回目の支給を国に要望するよう求めましたが、特別区長会から国に要望しているとして、区として要望する考えはないと答弁しました。既に半年が経っていますが、いまだに実現していないのに、なぜ改めて区として国に要望することを考えていないのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"その後、状況等も変わったところもあって、今は特別区長会からも要望などをしていないような状況だったかと認識しております。現状では、ほかの支援策がありますので、そういうところでの支援をまた充実していただければと考えているところです。","id":"exchange-124"},{"speaker":"のだて委員","kind":"質問・要望","question":"なので、やはり区として２回目の持続化給付金、家賃支援給付金を求めてほしいと求めましたが、いかがでしょうか。２回目の支給で、区内の事業者を助けることになるとは思わないのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"直接給付というところについては、一定程度、終わったといいますか、収まっているのかというところがあります。そのほかの給付金がありますので、そちらで十分というわけではございませんけれども、そちらで対応いただく形になろうかと考えているところです。","id":"exchange-125"},{"speaker":"のだて委員","kind":"質問・要望","question":"事業者の方々が給付を求めているというのは、やはり収益が出ていないということだと思うのです。給付もぜひ、区として考えてほしいと求めましたが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"例えば私どもの新型コロナウイルス感染症対応特別助成であれば、ほかの何かを購入するという話になります。原材料を仕入れるというところで、ぐるぐる回っていくという部分での支援策のほうが、より少ないお金で波及効果が大きいのかと考えているところです。","id":"exchange-126"},{"speaker":"のだて委員","kind":"質問・要望","question":"特定の業種にかかわらず、様々な影響が出ていますし、やはり給付を求めているという声が、この中にも出ていると思います。こうした困っている中小企業へさらなる支援が必要だと思わないのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"なかなか業種限定でというのは、飲食業以外は読めないと、景況調査などを見ていると考えているところです。支援を考えざるを得ないかというところで、そういうもので一応、支援させていただいているです。","id":"exchange-127"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひやっていただきたいと思うのですが、マイナスの影響が引き続き継続していると答えたところが５５.９％で一番多くなっています。多くの方が利用されて、つまり助かったということだと思いますので、２回目の実施が求められていると思いますが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"繰り返しになりますけれども、現在、既に緊急事態宣言が終わりまして、今後は経済をより前向きに向けていくというような支援が望まれているところだと考えていますので、持続化給付金について国に要望する考えはございません。","id":"exchange-128"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほど、声も紹介しましたけれども、現在の支援で十分だと考えているのでしょうか、伺います。なぜ月次支援金の上乗せをしないのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"月次支援金ですけれども、こちらは国の制度ですけれども、東京都がさらに上乗せを給付されているですので、そちらのほうで足りているのかと考えているところです。","id":"exchange-129"},{"speaker":"のだて委員","kind":"質問・要望","question":"５０％も売上が落ちたらやっていけないのだということで、支援の拡充を求めていました。やはり、こうした状況で、貯金を崩しながらやっているわけですから、続いていったら閉店にもつながるということになるのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"高橋（伸）委員","kind":"質問","question":"初めに、２９３ページ、省エネルギー対策事業の中の、太陽光発電システム設置助成についてお伺いします。３５件がどういう内訳になっているかをお聞きしたいと思います。","respondent":"河内環境課長","answer":"同様に、家庭用の令和３年ですが、９月末現在で８件、業務用が２件という状況です。おのおの、kW数が、３kWと５kWの上限を設けておりまして、そういう運用をやりながら、温暖化防止に努めているです。","id":"exchange-131"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。両方だと思うのですけれども、そこが事業所なのか、ご家庭に対しての啓発を重点的にやるのかというところを教えてほしいと求めました。","respondent":"河内環境課長","answer":"家庭、事業者ともに、両方とも非常に大切だと思っているところではありますが、役割が少し異なってきているという認識です。そういったところも含めまして、こういった趣旨の中で進めさせていただいているです。","id":"exchange-132"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２９５ページ、アスベスト対策事業についてお伺いします。まだまだ昭和６２年以前の建築物がある中で、どのぐらいの相談件数があるのか、教えていただきたい。","respondent":"河内環境課長","answer":"現在でも年間８０件以上の相談というところでございまして、レベル３といいまして、ケイ酸カルシウム板も規制対象になってまいりました。そういったものが、令和１０年をピークにしながら、今後もきちんと対応していきたいと考えているところです。","id":"exchange-133"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。そのとき所管の職員も、当然同行はしていると思うのですけれども、いかがか尋ねました。","respondent":"河内環境課長","answer":"幅広く迅速にやるために、まず業者の派遣、それからその報告を受けまして、必要に応じて、例えば防護服を着た職員が行くなどといった形で、多くの数がこなせるようにということで、工夫しながら対応しています。","id":"exchange-134"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続いて３０７ページ、午前中も質疑があったかと思うのですけれども、商店街店舗ＩＴ導入支援についてお尋ねしたいと思います。個店を中心にして４４０件の応募に対して、５０件ということだったと思うのですけれども、もう一度教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは、ＩＴサポーターは１５人いたのですけれども、そちらが各商店を中心に回って、４４０店を訪問させていただいたところです。その中で、いろいろ御用聞きなどをさせていただきながら、特に支援を希望される５５軒に対して、個別の支援を行わせていただいたというものです。","id":"exchange-135"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。これは２点お聞きしたいのですけれども、決算が９００万円ということなので、そこの２点を確認させてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは令和２年だけといいますか、今は１つにまとめましたので、エリアサポーター事業の予算を増やすことでやらせていただいたところです。","id":"exchange-136"},{"speaker":"塚本委員","kind":"質問・要望","question":"これまでも何人かの委員からご質疑がありましたけれども、私は地中熱調査業務委託というところについて質問をさせてほしいと求めました。ＺＥＢというものをどのように実現していくのか、地中熱の活用というのは一体どういうものなのかということで、初めにお伺いしたいと思います。","respondent":"小林施設整備課長","answer":"施設建設の技術的なご質問ですので、施設整備課でお答えいたします。冬場は外気温度より地中温度のほうが高いというところの温度差を利用して、効率的な冷房等に活用されるものです。","id":"exchange-137"},{"speaker":"塚本委員","kind":"質問","question":"私もホームページなどで調べたのですけれども、地中熱による、いわゆる空調ですか。どういった方式を採用しているのか、また採用した理由等は何なのかなど、もう少し詳しく説明していただけますか尋ねました。","respondent":"小林施設整備課長","answer":"約１００ｍほど掘った、直径が約２０cmほどの穴に配管を通しまして、特殊な液体を流すものです。設計を進めていく中では、今回一番効率的な方法ということで、クローズドループを使わせていただいたところです。","id":"exchange-138"},{"speaker":"塚本委員","kind":"質問","question":"もちろんＣＯ２の削減、費用対効果というのですか、こういったことは当然出てくるかと思います。今後の区内への展開について、どのような認識でいらっしゃるのか、お伺いいたします。","respondent":"小林施設整備課長","answer":"そもそも機械の設置場所など、そもそも地中熱が取れるかどうかの把握など、いろいろな立地条件にも左右されるものです。まずは施設完成後の利活用の状況や実績、それから効果等を検証して、今後の施設づくりに活かしていきたいと考えています。","id":"exchange-139"},{"speaker":"塚本委員","kind":"質問","question":"１つの大きな一歩になってくるですので、活用できるところにおいては活用していただけるという考えで進めていってほしいと求めました。残りの２５％はなぜ残ったのか、あるいは２５％のところを１００％にし得なかったところというところを、最後にお伺いしたいと思います。","respondent":"小林施設整備課長","answer":"設計をしていく上で、１００％を目指したいという気持ちは、やはり我々技術職としても思っていたことです。施設のある規模感等から、そこまでには届かないというところがございまして、最終的にはＮｅａｒｌｙ ＺＥＢというランクに落ち着いたところです。","id":"exchange-140"},{"speaker":"塚本委員","kind":"質問・要望","question":"１０月になって、いないので、急にフルな形で開業できないというような声も幾つか伺いました。最初に、雇用環境整備事業助成はどういった内容の事業であったのか、お伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"昨年の４月１日から実施させていただいた事業でございまして、それから休暇や時差出勤などの規定整備、就業規則の改定です。そういうものにかかった部分の経費についても助成するというものです。","id":"exchange-141"},{"speaker":"塚本委員","kind":"質問・要望","question":"第６波が来ると言われているのだけれど、やはり次への一手というのは、非常に迷っているというような状況にあるかと思います。新しい時代に合った経営のあり方といったものが求められてくると思うので、その支援についての考えについてお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"いろいろな仕事といいますか、やはり業態変更という部分でのお問合せといいますか、経営相談なども受ける部分が多くなっているところです。カタリストというのがありますので、そういうものの幅を広げるなど、いろいろな形で対応していきたいと考えているところです。","id":"exchange-142"},{"speaker":"渡辺委員","kind":"質問","question":"２９５ページ、環境啓発、それと３１１ページ、商店街エリアサポーターの２点を伺います。環境保全という観点で、やはりターゲットを絞るべきと私は思っていますが、その辺の考え方をまず説明を求めました。","respondent":"河内環境課長","answer":"ターゲットという言い方があれかどうかはあれなのですけれども、２０３０年、２０５０年に向けて、ＣＯ２の削減が進んでまいります。しっかりとした認識の中でやっていただきたいということで、メッセージを届けてまいりたいという考えで、進めているところです。","id":"exchange-143"},{"speaker":"渡辺委員","kind":"質問","question":"やはり今、いろいろな数値目標がある中で、もっと協力者が増えてほしいはずだと思います。何か大きな仕掛けも含めて、担い手不足を突破できるようなことの対策、ヒントでもあれば説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"どういうふうに集団回収を進めていけばいいのかというところ、それから、区としてどんどん啓発していかなければいけないと考えています。こういうところも進めながら、集団回収を行っていきたいと考えています。","id":"exchange-144"},{"speaker":"渡辺委員","kind":"質問・要望","question":"何が言いたいかというと、国は国だけど、このキーワードを基に、品川区がもう一段かませられないかというところで伺います。以上、この辺を伺えればと思います。","respondent":"品川品川区清掃事務所長、河内環境課長","answer":"各町会などに、やはり情報収集をしていくというところが必要かと思います。それと、繰り返しになりますけれども、報奨金を上げたところで、その状況についても検証していくことが必要かと考えています。 現在、環境課の職員が間に入りながら、手探りで進めているような状況です。こういったところを委託化も含めまして検討していきながら、そういったところはスピード感を持って対応していきたいと考えているところです。","id":"exchange-145"},{"speaker":"渡辺委員","kind":"質問","question":"これは１年で終わる話ではなくて、当然ながら、事業の中には、３年物、５年物とか中長期があると思います。その辺のあらましを説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"助成制度等の支援の周知や、商店街事務局のＩＴ支援、若手会員のイベント実施の。特に、世代交代というところがキーポイントになるのかと思っているところですので、そこは丁寧に進めていければと考えています。","id":"exchange-146"},{"speaker":"渡辺委員","kind":"質問・要望","question":"もう思い浮かべるだけで、環境から、地域の子育てや高齢者支援から、ほぼ全ての、本来行政が深く関わるべきものを、商店街はもうとっくに担っている。それはなぜかというと、これは本当に重点事業にしてほしいと求めましたが、答弁をお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは私どもも力を入れている事業です。こちらは非常に前向きに取り組んでいただいているところですので、しっかり検証して、ここにつなげていきたいと思っているところです。","id":"exchange-147"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701177?Template=document&Id=1506#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":121470,"voices":336}},{"id":"r03-20211011-4","meetingId":"r03-c-settlement","date":"2021年10月11日","dateIso":"2021-10-11","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を151件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"意見","question":"３５１ページ、３５５ページ、帰宅困難者を聞きたいと思います。道路安全施設費の中にあります未就学児移動経路等の安全施設整備工事、この事業についてご説明をお願いいたしますとの意見を述べました。","respondent":"溝口道路課長","answer":"私からは、未就学児移動経路等の安全施設整備工事に関する内容についてご説明をします。この令和元年度に行った安全点検に基づきまして、引き続きまして残りの９６か所ありまして、それを令和２年度に工事を実施したものです。","id":"exchange-001"},{"speaker":"松澤委員","kind":"意見","question":"小学校１年生が６年生の約３.７倍、死者になりますと９倍に上がる、未就学児から上がったばかりの１年生の事故が大変多いと感じております。説明を求めました。","respondent":"川口交通安全担当課長","answer":"一方、都内の小学校６年生の子どもについては６件という数字で、やはり低学年のほうが発生件数が非常に多いというのは理解をしています。併せて、その判断能力を小学校入学時にしっかりと養ってもらうことが必要ではないかなというふうに考えております。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"このキッズ・ゾーンというのは保育関連になりますので、ここではゾーン３０ですか、交通安全の新しい取組みと記載がありました。道路課が担当しますハード面、この両面が重なってこそ、危険である地域は安全に変わるものではないか尋ねました。","respondent":"溝口道路課長、川口交通安全担当課長","answer":"そういった視点で、ハード面ではありますが、そういったところの取組みを進めてきているところです。必要な交通安全対策はしっかりとやっていきたいと考えていますし、ハード… 警察と連携しまして、なるべくそういうような実際に感じてもらえるような、アイデアを絞ったような交通安全教育ができればと思います。","id":"exchange-003"},{"speaker":"松澤委員","kind":"提案","question":"そういったものに代わる方法があるのか、教えてほしいのが１つ。そういった部分でご提案したいのが、私たち大人に、ご見解を説明するよう求めました。","respondent":"川口交通安全担当課長","answer":"委員ご指摘のとおり、確かに区内小学校は人工芝化によりまして、なかなか校庭での実施は困難になっているというのは把握しています。例えば親子の自転車教室ですとか、そのような形も実施をしていますので、警察と連携をして実施してまいりたいというふうに考えております。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問・要望","question":"そして新たな地区の追加を要望しまして、令和３年度は、地区の事業を５年延ばしていただいたことには感謝申し上げます。こういった木密の火災現場、これに対してどのように放水活動が行われ、どのようなご苦労があったのか、教えられる範囲でお願いいたします。","respondent":"五十嵐災害対策担当課長","answer":"消防活動困難、人命危険の特徴を有しており、活動隊員にとっては緊張とストレスにさいなまれる現場と聞いております。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"そこで、対象地区を除く地区、要は、木密の対象地区において、危険と思われる木密地域、これは消防と連携して行政が把握しているのか。品川区は、この木密の基準を見て地域を絞っていくと思いますけれども、そこら辺を説明するよう求めました。","respondent":"森木密整備推進課長","answer":"不燃化１０年プロジェクトの対象地域につきましては、総合危険度と、それから不燃領域率などを勘案しまして、集中的に強力に進めているところです。今後もそれぞれの地域におきまして不燃化を進めるべく考えていきたいというふうに思っております。","id":"exchange-006"},{"speaker":"松澤委員","kind":"確認","question":"今のお話ですと、東京都がチェックをして、品川区の木密整備推進課でそれを確認するというお話でした。啓発してやっていく、さらなる地域の拡大、そういったお考えがあれば説明を求めました。","respondent":"森木密整備推進課長","answer":"で、荏原地域を包含するかなり大きな地域の中では、建築課の旧耐震の木造建築物に対して耐震除却助成も実施しています。この対象エリア外につきましては、不燃化の必要性と併せまして、様々な方法で啓発と周知等を行っていきたいというふうに考えております。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問・要望","question":"品川区の地震想定では、どれくらいの火災について想定しているのか、教えてください。ほかの地域と比べると、その数字をどのように感じているのか、説明を求めました。","respondent":"山本防災課長","answer":"首都直下地震が発生した場合の火災による住家の倒壊被害は約２万戸、それから死者数を５２０名と想定しています。この数字を近隣区と比較しますと、比較的被害規模が大きい傾向にあるというふうに感じてあります。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"Ｄ級ポンプが１８２台ということで、この数はほかの地区に比べても地域防災力に大変力を入れていただいていると思います。区民消火隊などでも高齢化でできないなどの声も上がっていますが、それに対して行政としてどういうような対応をしているのか、説明を求めました。","respondent":"山本防災課長","answer":"隊員の減少、高齢化などにつきましては、区としても大きな課題として認識はしていますが、まだ具体的な解決策をお示しすることができてございません。今後、区民消火隊の負担軽減につながるような対策も含めまして検討していきたいというふうに考えてあります。","id":"exchange-009"},{"speaker":"つる委員","kind":"確認","question":"それぞれいたものですから、消防の方から帰れるかどうかのご説明があるから、ちょっとお耳を貸してください。そういう課題意識を持ったものですから、今後どのようにしていくか、その辺りを説明するよう求めました。","respondent":"五十嵐災害対策担当課長","answer":"火災り災者支援の現場指揮官についてのお話ですが、区内で発生した住宅火災の支援として、３班編成で現場対応しております。今後、ポイントを列挙する分かりやすい手引書に再整備するとともに、ＯＪＴなどで対応方法の再確認などをすることが必要と考えております。","id":"exchange-010"},{"speaker":"つる委員","kind":"確認","question":"職員の方に逐一確認をさせていただきながら、どうしましょうかね」と言ったら、予備のものをどこかからとってきます」と言うのです。防犯カメラの面での整備で、またクッション材でもそういうフィジカルな事故を防ぐ、そういった対応をこれからも積極的にお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問","question":"最初に、３１５ページの違法駐車防止対策についてお伺いいたします。指定４路線以外でも、どういうふうに取り組んでおられるのか、お聞きしたいと思います。","respondent":"川口交通安全担当課長","answer":"先ほども委員からの説明がございましたように、その中でも、この辺のところの数の減少があったです。指定４路線以外ですが、そちらに対してもそれぞれ交通安全運動の機会を通じて、放置駐車の防止のキャンペーン等を実施しています。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そこによく、これ、車両の運転者のマナー違反は当然なのですけれども、誘導ブロックのところに駐車をしている。これも啓発しなければいけないと思っているのですけれども、どういうふうにお考えになるか、お聞きしたいと思います。","respondent":"川口交通安全担当課長","answer":"いわゆる視覚障害者の方をはじめ、そういうような点字ブロックの設置だとかを推進している地区でもあります。今度の１５日には、駐車の取締り等の指導の、取締りの啓発等のキャンペーンを行う予定です。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３１９ページ、立会川緑道整備についてお伺いいたします。３工区も、地域の意見、いろいろ要望があるかと思うのですけれども、今までの計画と、何か改善点があったら教えてほしいと求めました。","respondent":"溝口道路課長","answer":"工事に合わせて、引き続き必要なところについては、そのような対策をとっていきたいというふうに考えているところです。道路の巡回等を行いながら、どいていただくように、注意喚起も引き続き行っていきたいというふうに考えているところです。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"この３工区は、地域にどういうふうに注意喚起しているのかどうか、教えてほしいと求めました。","respondent":"溝口道路課長","answer":"通行にちょっと支障があるかもしれませんが、通行止め等を行いながら安全に工事を進めていきたいというふうに考えているところです。それはそれに対して注意喚起を促す、または看板を設置する、そういったところで対応していきたいというふうに考えているところです。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続きまして、３２５ページ、下水道管改修事業についてお伺いいたします。これは東京都の取組みで、品川区ではこの事業を受託して対策を進めていると聞いておりますけれども、この工事の内容についてお伺いいたします。","respondent":"栗原河川下水道課長","answer":"道路を掘削して下水道管の太さを太くするために管の交換を行い、また、老朽化対策の工事を進めているものです。併せまして、各ご家庭の排水設備と下水道管をつなぐ取付管やマンホールの蓋などの交換を行っているものです。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問","question":"上水管なのですけれども、東京都には２万７,０００kmあって、水道管の耐震化率がまだ４０％でとどまっているということです。引き続き計画的に進めていただければと思うのですけれども、その事業の計画、そして目標時期についてお伺いいたします。","respondent":"栗原河川下水道課長","answer":"このエリアの再構築を東京都が定めた整備目標です令和１１年度の完了を目指しまして、東京都と連携して、順次工事を進めております。第２期再構築エリアとなっておりまして、第１期再構築エリアの整備が完了した後に整備を進める予定と東京都下水道局から聞いているところです。","id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最後に、３４５ページ、歴史的・魅力的建築物調査活用事業についてお伺いいたします。あるいは延期にするのか、今後どういう状況なのか、教えてほしいと求めました。","respondent":"長尾建築課長","answer":"令和２年度の状況よりも新型コロナウイルス感染症の拡大状況が続いている、ツアーにつきましては、本年度につきましては中止を考えております。実施したツアーの様子をコンテンツとした動画配信を、今、企画しています。","id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問","question":"動画でこれから配信をしていくということで、この配信が、今いろいろやられておられると思うのですけれども、いつ頃に広報しながわとか、掲載の時期を含めて、視聴できるようになるのか、お聞きしたいと思います。","respondent":"長尾建築課長","answer":"動画配信につきましては、これまで行っていなかった活動になりまして、新たなチャレンジをしているところです。動画配信の予定時期としましては、年度末近くになると考えております。","id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"確認","question":"そうすると、今まで３回やって、公開建築物が３０弱ぐらいあるのですか。それをピックアップしながらやっていくということかどうかを確認したいと思います。","respondent":"長尾建築課長","answer":"これまで公開に協力いただいた建物につきましては、委員おっしゃったように３０ほどあります。もう少し多くなりますので、そういったところを建物の所有者や管理者のご協力をまた改めて確認しながら進めていきたいと考えております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は６月の一般質問で、議事録には、６６５戸の都営住宅を再開発で地域からなくさないようにと求めました。２つ目、区は東京都に対し、都営住宅の移転を要望しているのかいないのか、以上２点、伺います。","respondent":"中道まちづくり立体化担当課長","answer":"地域といたしましては、そういったことを踏まえまして、まちづくり検討、こちらは都営住宅も含めて検討が進められているです。そうしたことも踏まえまして、まずは地域と東京都がしっかりと調整すべきと考えています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこの良好な住環境という中に都営住宅の確保というのはちゃんと入っているのですかということも含めて、こういうものを要望しているのかいないのかを私は伺ったので、ちゃんとお答えほしいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"都営住宅につきましては、まずは東京都と地域の方が意見交換をして、しっかりと調整すべきと考えています。区としましては、地域の方々と東京都が良好な関係が築けるよう、情報共有などについて側面的な支援をしていきたいと考えています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、議事録とかを読むと、品川区も東京都に要望していきますみたいなことを言っているのです。その要望の中身について私は伺っているので、要望しているのかしていないのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"区としましては、東京都に対しまして、良好な住環境が保てるよう、お話をしているものです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"それぞれの面積について伺いたいのですが、旧劇団四季、旧ひろまち保育園の区有地の面積。そのうち新庁舎建設候補地の面積、これは８,３００m2だと認識しているのですが、その３つのところを伺います。","respondent":"多並都市開発課長","answer":"都市計画決定を進めている段階で、鑑定評価を必ず行い、適切な再編という形で進めるものです。したがいまして、現時点での面積は確定していないところです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"土地区画整理事業が、もう説明会でも説明されているし、今、意見書を募っているわけですよね。確定していないかもしれないけれども、おおよそどれくらいというのでも説明を求めました。","respondent":"多並都市開発課長","answer":"換地といいまして、その後に事業計画に基づいて適正な評価のもとに仮換地という手続になりまして、その後に確定するものです。したがいまして、現時点で何m2かというご質問については、お答えする数値がないというのが答えです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいと思うのですけれども、駅前一等地をそのまま生かして、区有地や新庁舎の建設地に充てるという検討は、一度でもされたのでしょうか。いかがか尋ねました。","respondent":"多並都市開発課長","answer":"今後の土地利用についての考え方を示させていただいて、この中で今、ご検討いただいているかと思います。検討したことがあるかというご質問ですけれども、これにつきましては、様々ないろいろな角度から以前から検討してきて。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとはっきりお答えいただきたいのですけれども、検討したのかどうか。その中で最適なものが今載っていますと、私は最適ではないのではないかと思うのですけれども、もう一度、そこら辺をはっきり、答えるよう求めました。","respondent":"多並都市開発課長","answer":"行った場合ということで、今回は、大井町の広町地区の土地利用により合った形で検討していくということで現在に至っているところです。しながわ中央公園との連携を図った防災性など、庁舎敷地も含めた土地利用ということで、最適な方法と考えているところです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"やっぱり庁舎は区民の財産なわけですから、なぜそういうことを密室で、この案しかないと出すのですか。伺いますけれども、新ルートという事業がいかにずさんで欠陥があるものであるかを自ら証明するものだと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"固定化回避検討会についてのご質問ですが、本格運用開始決定以前から、国の責任において決定し進められていくべきものというスタンスです。継続し、固定化することがないように検討していっていただきたいというところを強く要望し、検討が進められているものです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"これは前代未聞の欠陥計画、住民にとっていかに悪い影響がある計画であるかを国自らが認めたものにほかならないのではないですか。いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"繰り返しになりますが、管制技術ですとか、新たな飛行方式等々を踏まえて、継続し検討していくと。その結果、これは区としてはしっかり求めて、それを行うのは国の責任においてしっかり行っていくべきだというふうな理解です。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"国も欠陥計画だということを事実上認めているわけですから、区は、この新ルートを海上ルートに戻すことを品川区から国に求めるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"３４１ページ、公衆便所について、まずお伺いしますが、この数を教えてください。１回区切りとして、１回検証しないといけないと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"高梨公園課長、溝口道路課長、長尾建築課長、竹田住宅課長、森木密整備推進課長、川口交通安全担当課長、栗原河川下水道課長、鈴木都市計画課長","answer":"統一的な名称については、今後、検討していきたいと考えているところです。公園・児童遊園内の管理樹木数ということでお答えしますと… 私からは、区内の交差点等にあります品川区が管理しておりますカーブミラーの設置本数についてお答えします。今年度の４月１日現在ですが、区内… 品川シェルターについてのお問合せですが、令和２年度の実績としましては０件という結果になっております。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"そこを確認してくださいということと、四つ角というのでしょうか、どちらかが優先的な道路になってしまっているではないですか。止まってミラーを見るという形にして安全対策を高度にしていっていただきたいと思うのですが、いかがか尋ねました。","respondent":"長尾建築課長、森木密整備推進課長、高梨公園課長、稲田土木管理課長、溝口道路課長","answer":"一方で、耐震化支援事業の中で、木造住宅の建て替えに関わるような除却助成などは、令和２年度につきましても１６０件の申請をいただいております。… 不燃化１０年プロジェクトの助成につきましては、しっかりと不燃化を進めていかなければいけないということで、行政からも助成をしています。… 一部古いものについては、そういったものが見られたために、現在は修繕等で外から見られないような衝立の設置等を対応しています。… 区は、そういう支障があれば、そういう根は区のほうで切って対応しています。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"道路管理者なのですけれども、やっぱり区民、特に小さいお子さんの生命を守るという意味では、もうそろそろ両面止めると、これでやっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"これまで生活者ネットワークは、公園新設のための計画を作成すべきと求めてきました。今回の事例を踏まえて、改めて計画策定を求めますが、見解を伺います。","respondent":"多並都市開発課長","answer":"この町はどうしたらいいかと考えていただいて、調査をしながら組合の中で検討していただいた現時点の考え方で整備まで進んでいるという考えです。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"区の指導、助言後に改善がされたかを区はどのように確認しているのか、伺います。区として、参加者の名前がある議事録を求めたのでしょうか、伺います。","respondent":"多並都市開発課長、高梨公園課長","answer":"この地区はこれから区と都が共同で説明会をやりますけれども、恐らく事業者説明会といいまして、準備組合が開催する説明会だと思います。参加する方の１００％の合意で提案していただいているというところで… 私からは、区全域の公園の整備の計画についてお答えをします。その素案の中に、木密地域への防災広場の設置であるとか、公園を持たない町会内へ優先的に公園を整備していく等の都市公園の整備方針という形で。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"認可しない選択をするのは可能であり、すべきと考えますが、改めて区の見解を伺います。準備組合に対して助言、指導して促すことが区の役割だと考えますが、見解を伺います。","respondent":"多並都市開発課長","answer":"説明会の個人情報の、ご意見だとか、いろいろな配慮すべき事項があるという判断で行っているものと考えているものです。その中で合意形成をしていただいているところでありますので、区としましては、適切な方法で進めていただいているというふうに認識しています。","id":"exchange-036"},{"speaker":"田中委員","kind":"確認","question":"起こらないように、区として準備組合への対策やルールを定める必要があると考えますが、見解を伺います。参加を募る支援をすること、そのときには準備組合は任意団体であることを知らせるべきと考えますが、見解を伺います。","respondent":"多並都市開発課長","answer":"それが１人の方ではなかなかできないことが、２人ではできる、皆さんで検討していただいたものであります。今ご質問いただいた全体的な考え方としては、適切な進め方でやっているということで今後も進めていくべきだというふうに考えているところです。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"まちづくりとしての大前提なので、ぜひ区として、準備組合にきちんと規定を、ルールをつくってほしいと求めました。要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"木村委員","kind":"質問","question":"４億６,９７５万円余からの質問ですけれども、巨額の予算を組んで行っているこの事業ですけれども、一向に減らない路上の放置自転車の事業です。ここ数年、放置自転車の増減がどのように推移をしているのか尋ねました。","respondent":"川口交通安全担当課長","answer":"例えば武蔵小山でありますとか、大井町等の駅については、比較的まだ多いという状況があります。区といたしましては、それぞれの放置自転車対策を引き続き重点に沿って実施していきたいというふうに考えているところです。","id":"exchange-039"},{"speaker":"木村委員","kind":"質問・要望","question":"努力はしてほしいと求めましたけれども、先が見えない目標ですから、行政側としてどのようにお願いをするのでしょうか。どのような規則をつくればやっていただけるのか、説明を求めました。","respondent":"川口交通安全担当課長","answer":"１０月に実施をする駅前放置自転車クリーンキャンペーンにおきまして、なかなか街頭でのキャンペーンは実施できないのですけれども、放置自転車防止の周知等を図ってまいりたいというふうに考えております。","id":"exchange-040"},{"speaker":"木村委員","kind":"質問・要望","question":"次に、３２１ページにあります無電柱化推進事業についてお伺いいたします。そこで、今後も引き続き無電柱化を推進していく必要があると思いますけれども、区の今後の取組みについてお伺いいたします。","respondent":"溝口道路課長","answer":"さらに今年度につきましては、より早期に事業の着手が見込める２路線の設計も併せて進めているところです。今後も引き続き、この計画に基づきまして、無電柱化を推進していきたい、そのように考えているものです。","id":"exchange-041"},{"speaker":"木村委員","kind":"質問・要望","question":"そこで、事業を始めるに当たり、この課題についてどのように対応していくおつもりなのでしょうか。区のお考えを説明するよう求めました。","respondent":"溝口道路課長","answer":"計画に基づいてしっかり事業を進めていきたいところですが、コストの２割削減、そういったところの検討が進められているところです。事業実施に当たりましては、または、無電柱化の着実な実現に向けて今後も引き続き取り組んでいきたいというふうに考えているところです。","id":"exchange-042"},{"speaker":"木村委員","kind":"質問・要望","question":"次の質問に移りますけれども、決算書３２３ページ、水辺利活用事業の舟運通勤等社会実験実施についてお伺いいたします。お聞きいたしますけれども、舟運通勤社会実験の内容を説明するよう求めました。","respondent":"栗原河川下水道課長","answer":"令和２年度につきましては、オリンピック・パラリンピックの期間中に実施する予定で舟運事業者等と調整を進めてまいりましたが、延期いたしました。新たな実施日程につきましては、現時点で未定ですが、実施に向けて引き続き舟運事業者や東京都と調整を続けてまいります。","id":"exchange-043"},{"speaker":"木村委員","kind":"質問・要望","question":"社会実験の結果をどのように航路の実現につなげていくのでしょうか。最後に、答えるよう求めました。","respondent":"栗原河川下水道課長","answer":"社会実験では、利用者へのアンケートを実施する予定でございまして、その結果などを踏まえまして、東京都や舟運事業者の皆様とともに、採算性や運航方法といった航路の実現に必要な検討を進めてまいりたいと考えているところです。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"本日は、３１５ページ、交通安全啓発費について、３３７ページ、公園・児童遊園整備費について伺います。お願いします。","respondent":"川口交通安全担当課長","answer":"安全対策についても説明がございましたので、例えば自転車通行帯等の通行もできますので、その辺のところの把握はしていたところです。物件事故、人の死傷を伴わない事故で軽微なものが１件あったというふうに把握しております。","id":"exchange-045"},{"speaker":"松本委員","kind":"確認","question":"確認ですけれども、事故では、今の物損というか、物件の事故が１件で、人損は特にないという理解でよろしいでしょうか。もう１回お願いします。","respondent":"川口交通安全担当課長","answer":"委員ご指摘のとおり、物件事故のみの１件です。","id":"exchange-046"},{"speaker":"松本委員","kind":"質問・要望","question":"普通の車と違って車検があるわけではないので、なかなかその辺りがちゃんと入っていない人たちがいるというふうな問題もあると思います。まず１つは、できればＴｗｉｔｔｅｒとかＬＩＮＥの区のアカウントでの広報をお願いしたいと思いますが、いかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"電動キックボードの必要な免許やルールの周知につきましては、今、委員ご指摘のとおり、今、うちの担当でも、ＳＮＳによる各種交通安全に関する情報発信をやっているところですので、そちらのほうは実施を前向きに検討したいというふうに思っております。","id":"exchange-047"},{"speaker":"松本委員","kind":"質問","question":"もう１点、「SHIBUYA SLOW STREAM」というようなイベントで、安全講習とか試乗会を行っているというところです。試乗会、安全講習会も企画してはいかがかと思いますが、いかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"その辺の民間事業者との連携ですけれども、こちらにつきましては、今後の区内における電動キックボードの走行状況、あと普及状況、こちらのところを見ながら注視をしてまいりたいというふうに考えております。","id":"exchange-048"},{"speaker":"松本委員","kind":"質問","question":"次に、公園・児童遊園整備費について伺います。ここのところをもう一度、今の計画、あるいは規模とかをお願いできればと思います。","respondent":"高梨公園課長","answer":"下水道工事が終わった後に、その部分を公園として拡張する予定で、現在考えているところです。当然その作業の中では、利用者であったり、周辺の方々にご意見を伺う機会をつくりながら準備を進めてまいりたいというふうに考えております。","id":"exchange-049"},{"speaker":"松本委員","kind":"質問","question":"そこで、よく公園の整備、最近は公民連携というふうな話が出ているかと思います。全体的なお話でお伺いしたいのですけれども、民間にそういった公園の管理をお願いしている事例は、区内ではどの程度あるのか尋ねました。","respondent":"高梨公園課長","answer":"現在、他自治体等でも行われている民間活力を利用したところは、品川区におきましても前向きに検討していきたいというふうに考えているところです。一括管理公園ということで、１つの会社に公園の常駐管理という形で、管理人が常駐する形で管理をしているという公園があります。","id":"exchange-050"},{"speaker":"松本委員","kind":"質問","question":"これ、よくＰＦＩとかも、実は市民の方たちの意見を伺いながらやるという手法もかなり進んでいるというふうに聞いています。もう２０１８年には取り上げていたかと思うのですけれども、こちらで検討してはいかがかと思いますが、最後にいかがか尋ねました。","respondent":"高梨公園課長","answer":"その点も含めまして、前向きに検討していきたいと考えています。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問・要望","question":"総括質疑の確認なのですけれども、本年２月の国会の予算委員会で、地元の要望として取り上げていただいたことをご紹介させていただきました。区内１４か所３６棟の都営住宅への緊急避難が可能となるよう、これも求めたところ、このようなご答弁がありました。","respondent":"鈴木都市計画課長、五十嵐災害対策担当課長、山本防災課長","answer":"区としては、さらに一歩を踏み込んだ国の対応という受け止めです。まだ具体的な第１回目の日時については連絡は来てございませんが、今年度、恐らく… ホテルの宿泊助成事業として、現場検証が始まるまでの夜間の緊急避難場所の確保をどのように支援したらよいかということについて再整理いたしました。当面… それから、そのうち東品川一丁目アパート７号棟につきましては、５月１２日付でこちらを津波避難施設として指定しています。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問・要望","question":"国道を渡った学校、病院側の地域とともに一体的に考えて歩道橋の整備をすべきではないというご要望も地域の皆さんから伺っているところですが。そうしないと、そこについては周知をお願いしたいと思うのですが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長、山本防災課長、竹田住宅課長","answer":"今、歩道橋をバリアフリー化してほしいということ、国道をまたいで移動のしやすいまちづくりを進めていただきたいということを伺ってあります。研究… 津波避難施設の重要性であったりとか、また、区の風水害対策なども併せて周知していきたいというふうに考えてあります。 戸建てにお住まいの方が３万６,１９０戸になりまして、全体の約８３％の方がマンション等の共同住宅に居住されている状況です。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問・要望","question":"昨年、こうした管理組合を支援をしてほしいというところで、令和２年にマンション管理適正化法が改正されて。区民の約８３％の世帯の方がお住まいだという、ぜひお願いをしたいと思うのですが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"国よりまだ具体的なものが示されておりませんので、示され次第、委託先の具体的な選定を進めてまいります。国で検討されていますインセンティブとしましては、税制優遇措置、それから損害保険料の引き下げ等と聞いております。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"意見","question":"自治体としてのマンション管理適正化推進計画と指針については、これは区のほうで任意なのだけれども、つくっていくという方向なのか。つくってほしいのですけれども、そこについてもう１回ご答弁をお願いしたいと思いますとの意見を述べました。","respondent":"竹田住宅課長","answer":"マンション管理適正化推進計画および管理計画認定制度の策定が必要と考えておりますので、策定していく方向で検討しております。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問","question":"本当にこれは難しいお役目だなと、改めて今、認識をしています。認定制度をしっかりつくっていただいて、マンション管理組合への支援のさらなる強化をお願いしたいと思いまして、本日の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"芹澤委員","kind":"質問","question":"３３１ページ、あとは３４３ページ、水とみどりの基本計画・行動計画改定経費についてお伺いします。改めて区の見解として、マンションの防災は戸建てとどういったところが違って課題になるのかをまず説明を求めました。","respondent":"山本防災課長","answer":"大きく３点あると考えてございまして、まず１点目が、家具転倒リスクが戸建てより大きくなるのではないかというふうに考えているところです。高層階にお住まいの方の移動負担、その辺りが１つ課題というか、対策をしなくてはならない部分だというふうに考えてあります。","id":"exchange-057"},{"speaker":"芹澤委員","kind":"質問","question":"はコミュニティの１つとして防災訓練の経費もかかってくると思うのですが、そういったところの補助をご検討されてはいかがかと思います。その条件の１つに、町会加入というのも１つの条件として補助をご検討されてはと思いますが、いかがか尋ねました。","respondent":"山本防災課長","answer":"他の自治体でも既に取組みを行っているところでございまして、区としてもその対応等を今検討しています。いかに地域の防災力の向上につなげていくか、地域との連携を図っていくか、そういったところの視点を大事にしていきたいというふうに考えてあります。","id":"exchange-058"},{"speaker":"芹澤委員","kind":"質問・要望","question":"そのマンションの１つのコミュニティで終わらせずに、町会とか、さらに地域のつながりを広げてほしいと求めました。認識の確認で、マンションも使えるのかどうかをお聞かせいただきたいのと、まず説明を求めました。","respondent":"竹田住宅課長","answer":"家具転倒防止器具の件ですが、対象としましては、全ての住宅を対象としておりまして、賃貸も含んでいるものです。","id":"exchange-059"},{"speaker":"芹澤委員","kind":"意見","question":"計画書をもらって、管理会社に連絡をして取付け作業というような形になると思って、そこそこハードルがあるのかなと思うのです。は突っ張り棒であったりとかというものもあると思うのですが、まず、それが項目として入っているのかを説明するよう求めました。","respondent":"竹田住宅課長","answer":"突っ張り棒等の簡易なものについては、ご本人が行うことが多いものですから、こちらの制度につきましては、専門業者に依頼して工事費がかかるものについて、取付け費用を助成しています。","id":"exchange-060"},{"speaker":"芹澤委員","kind":"質問・要望","question":"そもそも上限が４,０００円と、項目に入っていないのであれば、ぜひご検討ほしいと求めました。物を運んでくるときには、最初から転倒防止を取り入れられるような制度にしたらどうかなと思うのですけれども、ご見解を説明するよう求めました。","respondent":"竹田住宅課長","answer":"私どものＰＲがまだまだ不足していたところがあったかもしれません。転入の方を含めて、多くの方々にご利用いただけるように、ＰＲ、周知に努めていきたいと考えております。","id":"exchange-061"},{"speaker":"芹澤委員","kind":"提案","question":"認定をしていって、補助を継続して、そのマンション同士の取組みを横で共有できるような仕組みをつくってみてはどうかということを１つご提案します。平成２５年発行で、そろそろ１０年が見えてくる中で、それも併せて説明を求めました。","respondent":"山本防災課長","answer":"１つ有効な施策だというふうには考えてありますので、先ほどの資機材の助成制度と併せて今後検討していきたいというふうに思ってあります。改訂の予定はございませんが、その辺りを反映できるよう、今後検討していきたいというふうに考えてあります。","id":"exchange-062"},{"speaker":"芹澤委員","kind":"質問","question":"防災協定のことでお伺いしていきます。事前に資料を伺って、１７０近くもう既にあるのかなと思っていて、非常に心強いなと思っています。","respondent":"山本防災課長","answer":"協定内容を見直す体制、仕組みですが、こちらにつきましては、今、区としてそういった体制とか検証方法は確立されてございません。今後、より実効性のある協定が結べるように、そういった部分もしっかり整えていきたいというふうに考えてあります。","id":"exchange-063"},{"speaker":"芹澤委員","kind":"質問・要望","question":"今、１７０できているというのは非常に心強いのですが、やはりやってみて改善できるというものもたくさんあると思うのです。ここに改善点があるねとかというのを、ぜひ見つけ出してほしいと求めましたが、そちらのご見解を説明するよう求めました。","respondent":"山本防災課長","answer":"まずは平時における訓練を重ねていくというところ、そして災害時に協力して実際の対応を行っていくというところが重要だというふうに考えてあります。","id":"exchange-064"},{"speaker":"芹澤委員","kind":"意見","question":"できれば５年、例えば１０年のうちに改善をしていきましょうねとかということも事前にお伝えできればいいなと思いますので、ご検討ください。これはなぜ１０年と言っているかというと、多分１０年経つと、あとはその担当者もほぼ代わってしまうと思うのですとの意見を述べました。","respondent":"山本防災課長","answer":"協定内容等の定期的な見直しです。１０年というご提案がございましたが、そういった部分でアドバイスを生かしながら体制等もつくっていきたいというふうに考えてあります。","id":"exchange-065"},{"speaker":"芹澤委員","kind":"質問","question":"続いて、防災の情報発信についてお伺いします。避難所での防災発信について伺いますが、避難所は着のみ着のまま来る方もたくさんいらっしゃると思います。","respondent":"平原防災体制整備担当課長","answer":"委員ご指摘のとおり、スマートフォンやタブレットがない方々につきまして、災害時の情報収集手段としてラジオは非常に有効なものと考えています。このため、災害時には、各避難所に少なくとも１台はラジオを設置しています。","id":"exchange-066"},{"speaker":"芹澤委員","kind":"質問","question":"災害時に避難所等で手話通訳、手話も言語の保障をできるような環境をつくってみてはいかがかと思うのですが、いかがでしょうか。併せてご見解を説明するよう求めました。","respondent":"平原防災体制整備担当課長","answer":"災害時には、円滑な対応のため、防災タブレットに翻訳アプリをインストールすることについて検討してまいります。現在、どのような資機材が必要かを引き続き検討させていただきまして、準備できるものから速やかに整備してまいりたいというふうに考えてあります。","id":"exchange-067"},{"speaker":"芹澤委員","kind":"質問・要望","question":"一定の時間は、やはりパネル等でできないものもあると思いますので、ぜひ前向きにご検討ください。一般質問で、大規模災害のときに区が主体的に情報発信できるような協定の見直しを求めさせていただいたと思いますが、また内容を説明するよう求めました。","respondent":"平原防災体制整備担当課長","answer":"それぞれ緊急放送に関する災害時協力協定を広報広聴課の管理のもと、締結していますが、その中で緊急時の割り込み放送について規定をしております。現在でもこの協定文の中で実施できることから、災害時には、この協定を基に緊急放送を実施することとしています。","id":"exchange-068"},{"speaker":"芹澤委員","kind":"提案","question":"避難所でケーブルテレビ品川が見られる環境をというふうに思っていまして、なかなか台数が限られているのだと思っています。提案なのですけれども、例えば区の公式ＹｏｕＴｕｂｅチャンネルのライブ配信とかを利用して、いかがか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"若い世代を中心といたしまして、ＹｏｕＴｕｂｅなどのインターネット環境での映像により情報を得ている層が増加しているというふうに聞いております。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、３２６ページの都市計画費に関わって、リニア中央新幹線について伺いたいと思います。様々な影響を与えることも外環道で明らかになったわけですから、区としても求めるべきではないかと思いますが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"区といたしましては、説明会で説明していました調査掘進を今後３００ｍ行っていくわけですが、今、ＪＲ東海が安全検証を様々行ってあります。地域ごとの説明ですが、合同で説明会を開くのか、ＪＲ東海と様々協議してまいりたいと考えています。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、調査掘進の結果の説明会は、必ず地域ごとにやるようにということで区のほうからも強力に求めてほしいと求めました。そういうところでは、ぜひ調査掘進の結果の説明会は地域ごとにやるようにということで区から求めていただきたいと思うのですが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"地域ごとの説明会ですが、その結果を説明するというところで、ＪＲ東海と協議してまいります。家屋調査はいつまでにですが、この前の説明会では、令和３年度中に品川区内全て、家屋調査を行いたいというふうに聞いてあります。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"７,０００軒も対象になるにもかかわらず、ごく一部しか参加されていないわけですから、これは本当に地域ごとに丁寧にやってほしいと求めました。それから、もう１つお聞きしたいのが、先日、地震もありましたけれども、南海トラフ巨大地震の影響のことを伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"やはり東海道新幹線であったり、東名高速道路など、地上部にもインフラ整備は様々あります。やはり地震があった後に、どういうふうな安全対策をするかといった複合的な考えで進めていくことが重要と考えています。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"トンネルになるわけですから、活断層が幾つあるかも分からないということは、私はあり得ないと思うのです。品川区はとにかくど真ん中を通って始発になるわけですから、ぜひ品川区としても、安全というふうなところでも検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"こんの委員","kind":"提案","question":"利便性向上という観点から、これまで何回かお聞きしてきましたが、その後の進捗状況などを確認していきたいというふうに思います。いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"１つは、エレベーターの設置場所がないというところが１つ課題としてあると、これは非常に大きな課題としてあるという回答です。これが１つ継続して行っているところですが、この辺も先ほどご説明いただいたように、池上通り側はバリアフリー化が図られている。","id":"exchange-074"},{"speaker":"こんの委員","kind":"質問・要望","question":"商業施設の建て替えというタイミングも伺えるという、こうした観点もご説明がありましたので、このようにお願いしたいと思います。これも２０１９年の決算特別委員会でご答弁いただいたときは、２０１９年から２年が経っておりますけれども、現状をまずお聞きかせいただくよう求めました。","respondent":"鈴木都市計画課長","answer":"１日を通してではないのですが、時間帯によっては、ＪＲとしても課題として認識していただいているというようなところです。ＪＲからの回答としましては、課題としては認識しているものの、支援を活用いただいて設置しているというところで。","id":"exchange-075"},{"speaker":"こんの委員","kind":"質問・要望","question":"歩行者の信号機が青であることを視覚障害者に知らせるため、いわゆる音響式信号機ですけれども、これは現在区内に何基設置されていますでしょうか。この音響式信号機は、押しボタンを押したときだけ音が鳴るタイプと２種類あると思いますけれども、その設置割合はどれぐらいか尋ねました。","respondent":"川口交通安全担当課長","answer":"区内におきます音響式信号機の設置状況ですけれども、本年の９月現在で、区内７９か所となっております。現在、押すタイプまたは鳴動の時間関係ですけれども、そちらにつきましては警察のほうからの情報提供がないものですから、把握をしておりません。","id":"exchange-076"},{"speaker":"こんの委員","kind":"質問","question":"現在、音を止めている時間帯は何時から何時までなのでしょうか。併せて、それは主にどのような場所に設置されている信号機にそうした苦情などが上がってきているのか、その辺も少し説明を求めました。","respondent":"川口交通安全担当課長","answer":"地域の設置場所におけます、そういう利用される方々の交通量を踏まえて、そのような時間等にしています。夜間帯は開設とかをしていない時間帯にもかかわらずというところがありまして、その辺のバランスで、そのような話が出るです。","id":"exchange-077"},{"speaker":"こんの委員","kind":"質問・要望","question":"も鳴らしている時間外で信号の状況が分からずに渡ってしまって交通死亡事故が発生しているというケースも聞いております。こういう声があるわけで、そうした声については具体的な対策をとってほしいと求めましたが、いかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"先般、そのような時間帯は、基本的な朝の８時から午後８時という部分を超えても鳴動はしているというところを確認しています。そのような導入が今後も図られるように、区としても情勢を注視してまいりたいというふうに考えております。","id":"exchange-078"},{"speaker":"こんの委員","kind":"質問・要望","question":"警視庁では、今年度、約２,０００基の信号機を設置する方針を決めたというところも出ておりました。警察と協議をしていただくなどして進めていただきたい、このように思いますが、いかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"実際に具体的なところですと、都内では、新宿区の高田馬場辺りで既に試験的な運用が始まっているというのは聞いているところです。今後の設置状況につきましては、引き続きどのような場所で設置・運用ができるのかということは注視してまいりたいというふうに考えております。","id":"exchange-079"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひそうしたシステムが開発されていることを障害者団体の方々のお声を聞きながら進めてほしいと求めましたので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"これはＪＲ、それから東急、品川区といろいろ関わってくるかというふうに思いますので、この回遊性についてのお考えをお聞きします。私はその動きが理解されていないのではないかと、メッセージ性がやっぱり弱いのではないかと思いますが、いかがか尋ねました。","respondent":"川口交通安全担当課長、稲田土木管理課長、多並都市開発課長","answer":"１つ目の車椅子の関係の事故防止ですけれども、こちらにつきましては、前回の建設委員会でも委員からお話しいただきました。… 違法駐輪との関係等々、まだまだ分析が必要でございまして、その辺は引き続き考えていきたいというふうに思っております。今、お話ししている最中ということで、実現に向けて区としてもしっかりサポートしていきたいと思っているところです。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"具体的なところがあるかと思いますので、そこも含めて、回遊性については今後検討してほしいと求めました。ただ、準備組合ができてというその仕組みをちゃんと説明してほしいと求めましたが、再度お願いいたします。","respondent":"多並都市開発課長","answer":"委員のご指摘のとおり、やはりまちづくりをしっかり進められるように、地域の方と一緒に進めていく。そのためには、今のお話のような、分かりやすい仕組みというか、お伝えしながら進めていきたいと思っているところです。","id":"exchange-082"},{"speaker":"大沢委員","kind":"質問","question":"河川ですから、都の委託事業ということで伺っておりますけれども、やはり人件費等々も計上されてくるということ。となると、この１億円弱のお金は、当然、何かに使うわけですけれども、どのような使われ方をしているのか、説明を求めました。","respondent":"栗原河川下水道課長","answer":"区内の下水道事業の整備を促進する観点から、昭和６２年度より事業の一部を東京都から受託して整備を進めているものです。東京都から工事費に合わせまして、事務費をプラスして、受託費として請求して、我々のところの歳入として入ってきているというものです。","id":"exchange-083"},{"speaker":"大沢委員","kind":"質問・要望","question":"歳入として入ってきているということは分かっておりまして、決算ですから出と入はこれに出ている。その中で１億円弱のこのお金の使途、どのようなものに使われているのか、その説明を今求めているわけでして、そこら辺のところの説明をお願いします。","respondent":"黒田財政課長","answer":"受託収入等で歳入がある場合につきましては、一般財源として使用する場合につきましては、人件費等に充当しています。","id":"exchange-084"},{"speaker":"大沢委員","kind":"質問","question":"この人件費等々においても、人件費というのは、この委託事業であると、都から人件費もさらに経費として入ってくるのではないのですか。この中でほかに充当するのではなくて、その相差の部分プラス人件費としてさらに委託費として入ってきているような流れというのはないのか尋ねました。","respondent":"黒田財政課長","answer":"いわゆる事業に関わる歳入ですので、事業にかかる事務費、かかる経費と人件費に充当しているものです。","id":"exchange-085"},{"speaker":"大沢委員","kind":"質問","question":"武蔵小山もいよいよ（マンションが）２棟できてということで、駅前ロータリーのところに噴水があったりとか、いろいろな。本年の６月に、この２つのまず先行して行われたまちづくりをどのように捉えられているのか、説明を求めました。","respondent":"多並都市開発課長","answer":"平成１７年から地元の方でご検討いただき、令和３年６月、今年の６月に建物が竣工したところです。両事業を実施することで、また荏原地区の中心核としてふさわしいまちづくりということで進められたということで成果として考えているところです。","id":"exchange-086"},{"speaker":"大沢委員","kind":"質問","question":"今度においては、一般質問にも、また区長にご答弁いただいたように、武蔵小山の第１地区、第２地区についての計画が、今、動こうとしているわけです。この皆さんが不安に思われている事実、区はどのように把握していらっしゃるのか、どのように考えているのか、説明を求めました。","respondent":"多並都市開発課長","answer":"今後のまちづくりについて検討していただき、今後の都市計画についての案ということで、組合の中の皆さんでご検討いただいて議決いただいて。","id":"exchange-087"},{"speaker":"大沢委員","kind":"意見","question":"先ほど来もちょっとお話をいただきましたけれども、今後どのようにされていくのか、改めてお答えくださいとの意見を述べました。","respondent":"多並都市開発課長","answer":"それは段階的に決めていくことですよと、いろいろ準備組合の方もご説明いただいているのですけれども、分かりづらいところがあると思います。気軽に、そういう形で、より皆さんに納得いただけるような事業ということで今後も進めていきたいと思っているところです。","id":"exchange-088"},{"speaker":"大沢委員","kind":"質問・要望","question":"あくまでも住民の方、ここのところをどのようにお考えになりますでしょうか。、答えるよう求めました。","respondent":"多並都市開発課長","answer":"その事業を検討していく段階で、それがちゃんと検討の段階で、サポートしながら進めていく。そういうことで、区としてもサポートしていかなければいけないと思いますので、そのように進めていきたいと思っているところです。","id":"exchange-089"},{"speaker":"大沢委員","kind":"質問・要望","question":"最後のお願いですけれども、選挙みたいになってしまった。あるいは住民の皆さん、事業協力者あるいはコンサルタントの間にしっかりと入っていただいて、点と点を結んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"おくの委員","kind":"質問","question":"この９割を超える賛成とは、負担を具体的に説明を受けた上で明らかにされたのでしょうか、伺います。その点、伺います。","respondent":"多並都市開発課長","answer":"資料だけではなくて説明もされているのですけれども、スケジュールもその中で準備組合のほうからかなり詳しくご説明いただいているところです。","id":"exchange-091"},{"speaker":"おくの委員","kind":"質問","question":"結局は狭くなるのだと思うのですけれども、部屋がどのくらい狭くなるかとか、それから修繕積立金などが実際に示されるのは一体いつなのでしょうか。区の都市計画審議会にかかる前なのか後なのか、この点を伺います。","respondent":"多並都市開発課長","answer":"市街地再開発事業の進めていく流れについて改めてご説明いたしますけれども、まずは、それを考えたところで都市計画の手続をしていきます。ただし、そういう進め方をするということは丁寧に説明しているということを確認しています。","id":"exchange-092"},{"speaker":"おくの委員","kind":"質問","question":"どこが必要な説明がなされていると言えるのか、伺います。私は言えないと思うのですけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"そういう説明をするというお話でしたけれども、皆さんで検討していただき決定していくことということで、その中で決めることです。具体的な建物についての検討をしていく、一遍にやるものではなくて、段階的に進めていくステップという考え方と捉えていただければと思います。","id":"exchange-093"},{"speaker":"おくの委員","kind":"質問・要望","question":"結局、住民の参加と合意がないのだと思います。中止を強く求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"たけうち委員","kind":"質問","question":"今年度中ですか、現状、どのようなスケジュールになるのかということを教えてください。で震度４に引き下げられましたけれども、ああいう形で流すのかどうか、説明を求めました。","respondent":"鈴木都市計画課長、竹田住宅課長、平原防災体制整備担当課長","answer":"試行運行開始を目指して検討を進めているところですが、試行運行をしていただく事業者を、６月にはプロポーザルで決定しています。場合によっては… 不適正管理空き家についてお答えします。この２つが大部分を占めておりまして、それ以外にも、小動物が住みついてしまうというようなケースもあります。品川区に設置の計測震度計で震度４以上を計測した際には防災行政無線を鳴らすということになってあります。","id":"exchange-095"},{"speaker":"たけうち委員","kind":"質問・要望","question":"地域からの要望も多かった場所ですので、ここができなくなると、そこはしっかり何とか交渉していただいてやってほしいと求めました。状況を確認したり、また不法侵入があるかないかの確認、仕組みとして行っていくということの考え方について説明を求めました。","respondent":"鈴木都市計画課長、竹田住宅課長","answer":"その中で収支率５０％という目標を定めて実施していきたいですが、所管としては認識していますが、しっかり見定めていきたいです。所有者の方に、東京都の空き家ワンストップ相談窓口に選定されている５社のうち、見守りサービスをやっている専門業者２社をご紹介しています。","id":"exchange-096"},{"speaker":"湯澤委員","kind":"質問・要望","question":"私からは、３３５ページ、公園・児童遊園費、それから３４１ページ、公衆便所費、３４８ページ、防災費全般についてお伺いします。うちの近くの公園にもユニバーサルデザインの遊具を入れてほしいという要望を受けたこともありますので、それだけ公園のあり方について。","respondent":"高梨公園課長","answer":"最近では、今、子どもたちのアイデア等を活かした公園づくりということでワークショップを行ったもの。それと、地域の悲願といったところもお聞きいたしておりましたので、地域の方が集まってワークショップを開催したという２件を実施したところです。","id":"exchange-097"},{"speaker":"湯澤委員","kind":"質問","question":"これは事前に課長から理由はお伺いしておりましたが、どういう経緯で設置するというふうに意見が変わったのかをお知らせほしいと求めました。書面開催によって意見交換会が不十分であったことが理由の１つであるのならば、今後このようなワークショップを開催する際、ご意見をお伺いします。","respondent":"高梨公園課長","answer":"コロナ禍での開催ということで、リモートでの実施等を検討したのですけれども、難しいということで書面開催になったところです。周辺の方々への不安を払拭するという形で取組みをさせていただきたいということで、トイレを設置するという結論に至ったところです。","id":"exchange-098"},{"speaker":"湯澤委員","kind":"質問・要望","question":"例えばこのトイレの設置につきましても、もう少しスムーズに決定するのかなというふうにも思いますので、そのような取組みをお願いしたいと思います。汲み取りまでのおおよその日数、それから、臭いや衛生面の取組み、劣化の心配について、３点お知らせほしいと求めました。","respondent":"高梨公園課長、山本防災課長","answer":"区内の公園・児童遊園には、特に防災広場を中心として３７の公園・児童遊園に、１７３基のマンホールトイレを設置しています。便槽型といいまして… し尿の収集運搬についてですが、発災後およそ３日以降、順次、収集運搬をするというところで想定をしています。","id":"exchange-099"},{"speaker":"湯澤委員","kind":"質問","question":"区への苦情などは入っているのでしょうか。緊急事態宣言が発令されている期間は禁止すべきかと思いますが、区のご見解を示すよう求めました。","respondent":"平原防災体制整備担当課長、高梨公園課長","answer":"現在、清掃等で対応するというような状況になっておりまして、必ずしも防災活動広場のトイレのところまで対応できているものではございません。今後につきましては… 特別の巡回パトロールを行いまして、お声かけにより飲酒はお控えいただくということでパトロールを行ってきたところです。夜間の巡視等も含めて、しっかりと見回りながら声かけをしていきたいと、このように考えているところです。","id":"exchange-100"},{"speaker":"湯澤委員","kind":"質問・要望","question":"一人ひとりが我が事のように水害対策を考えて、行政だけに頼るのではなく、自分がリスクに向き合うことが大切だと考えています。そういった住民に対して、命を守るためにどういったお願いをしているのか、教えてほしいと求めました。","respondent":"山本防災課長","answer":"それから、周知に関してですが、風水害時、平時における区民への周知、啓発とかは非常に重要だというふうに考えてあります。その辺りについて、引き続き力を入れて啓発等をしていきたいというふうに考えてあります。","id":"exchange-101"},{"speaker":"湯澤委員","kind":"質問・要望","question":"最後、り災証明についてお尋ねいたします。ほとんどが通るのか、どのぐらい遡れるのかをお知らせほしいと求めました。","respondent":"平原防災体制整備担当課長","answer":"大変申し訳ございません。災害から日が経っていても証明することはできるというふうに考えてありますので、そういった分かるようなものがあればというふうに思ってあります。","id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問","question":"この調査等の、現地調査というのでしょうか、それについて、どのような状況なのでしょうか。説明の文書にありましたけれども、人道橋の位置がほぼ絞られてきたのではないかと思いますが、その件についてお願いします。","respondent":"溝口道路課長","answer":"勝島人道橋につきましては、道路課のほうで設計を進めておりますので、私のほうからお答えをします。東大井区民集会所付近を候補地の１つといたしまして、そういったものを今後行いながら、詳細な設計に入っていく。","id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"質問","question":"その残り２つの基幹事業についての進捗というか、検討状況をお尋ねします。それともう１つは、どのようにお考えか、お願いします。","respondent":"鈴木都市計画課長、溝口道路課長","answer":"１つ候補として検討しているところが、関係機関とも協議をしながら、いろいろ検討を進めているというような状況です。 今現在、検討が進められています水とみどりの基本計画の関係です。当然そういった上位計画、または都市再生整備計画、そういった計画に基づきながら事業を実施していくものだというふうに考えているところです。","id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"質問","question":"補助事業として国費の補助が上限４割ということなのですが、まだ計画が立っていないところで答えにくいのかもしれませんが、どういうことが考えられるか尋ねました。","respondent":"鈴木都市計画課長","answer":"国費４割を入れながらというところで検討を進めてまいりましたが、様々検討している中で、検討しているところでございまして。できるだけ区費を抑えて整備を進めていく中では、こうした検討もしています。","id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"令和２年度に検討をしていただいたのですが、令和３年度は予算化されていませんが、今後のまちづくりの検討はどのような形になるのでしょうか。老朽化しているところなどの補修といいますか、補強といいますか、それらはどのような状況か尋ねました。","respondent":"鈴木都市計画課長、栗原河川下水道課長","answer":"これまで委託費をつけまして様々検討を進めている中で、３回ほどの実施を予定しておりますが、そのようなワークショップを実施をしながら。 昨年実施いたしました溢水防止板設置の際に、詳細な調査を予定しておりまして、調査項目等を検討しています。実施に向けて、引き続き取組みを進めてまいります。","id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"意見","question":"八潮のほうは、ガイドライン策定、よろしくお願いします。立会川のことは、安心という成果がありましたので、今度は安全に向けて、さらに今の点検状況、護岸のチェックをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"補助２６号線と踏切について、３３３ページの大井町駅周辺地区再開発事業に関わって、東大井五丁目のＣ地区について質問します。周辺住民の意見を聞いているのかどうか、伺います。","respondent":"鈴木都市計画課長","answer":"２６号線開通、陸橋が整備された後、住吉踏切は除却されるというふうには東京都からは聞いているです。利用者の安全性を第一に考えて、東京都が踏切を除却するという判断をしたと、区は認識しています。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問","question":"周辺住民の意見を聞いているのかどうかということでお伺いしたので、お答えほしいと求めました。","respondent":"鈴木都市計画課長","answer":"踏切除却について、意見を聞いた上で検討したかということは聞いておりません。そういう地域の声を聞いた上で検討しているというふうには聞いてございませんので、安全性を第一に考えたというふうな受け止めです。","id":"exchange-109"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用者が便利なように踏切を残してほしいと求めましたが、残すことはできないのか、伺います。なぜこの区間に歩道を設置しない構造になったのか、伺います。","respondent":"鈴木都市計画課長","answer":"区としては、やはり区民の安全性を考えれば、踏切の除却は一定理解するところです。それから、新幹線の橋脚がありまして、どうしてもその橋脚間の幅の関係で車道しか設けられないというところで東京都から聞いているところです。","id":"exchange-110"},{"speaker":"のだて委員","kind":"質問","question":"広町地区が周辺のまちづくりを牽引するとのことですが、牽引する対象にＣ地区は入っているのか、伺います。まちづくり方針でＣ地区が位置づけられている活力創造ゾーンとは何か、伺います。","respondent":"多並都市開発課長","answer":"これにつきましては、いわゆる再開発等を進めるだけではなくて、いろいろな手法を含めて検討していきたいということで勉強されております。","id":"exchange-111"},{"speaker":"のだて委員","kind":"質問・要望","question":"この牽引する対象にＣ地区も入っているということですが、進めてほしくないという方々がいるもとで進めるべきではないと思います。Ｃ地区には波及させないように、計画を進めないようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"地域の中では、今のままでは、やはり安全性、火災への危険性を感じている方、いろいろな方がいらっしゃいます。それをどのような形で進めていくべきかということで、皆さんで考えていただいて、その方向性を決めていくということが一番重要なことかと思います。","id":"exchange-112"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたことをちゃんと解決しながら、超高層再開発にならないように、区として支援をしていっていただきたいというふうに思います。やはり住民合意のないままに計画が進められるということがないようにしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"若林委員","kind":"質問・要望","question":"この理由をお聞かせいただきたいのが１つです。お金のこととか、いわゆる浚渫そのもののことなのか、ここら辺の意味をお知らせほしいと求めました。","respondent":"栗原河川下水道課長","answer":"実施した箇所につきましては、区間といたしましては、目黒川の山本橋から御成橋の区画を実施したものです。船団、船を使っての大規模な浚渫につきましては東京都が実施いたしまして、護岸のフーチング部分につきましては区が実施するということで。","id":"exchange-114"},{"speaker":"若林委員","kind":"質問","question":"続けて、水質改善のほうを伺いたいと思います。それに基づいて、様々な手法があると思いますけれども、そういったものを今後取り入れていこうとしているのかについてお聞きしたいと思います。","respondent":"栗原河川下水道課長","answer":"現在、河川につきましては、大雨が降った後には一時的に臭気や濁りが発生することは認識しています。区といたしましては、先ほどお話ししました継続的に川の浚渫を実施するとともに、目黒川のさらなる水質改善に取り組んでまいりたいと思います。","id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほどの３つの要素の汚れの原因等とともに、ヘドロなのですか、今後に向けてのご答弁をほしいと求めました。令和２年度は社会実験等々、あの黒い塊が、あれは最終的にどうなるのか尋ねました。","respondent":"栗原河川下水道課長","answer":"しっかりとその状況、その推移は把握をした上で、水質改善に向けて有効的な検討を引き続き進めていければというふうに思っているところです。","id":"exchange-116"},{"speaker":"若林委員","kind":"質問・要望","question":"それはそのとおりだというふうに理解いたします。ぜひ河川下水道課としても取り組んでいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"大倉委員","kind":"質問","question":"以前の質問だと、２,０００台ぐらいまで下がってきているのではないかというようなお話だったことを前提にして伺っていきたいのですが、不動前は。その方は目黒区との境だったのですが、もしかしたら、そういうような近隣区の行政無線が混線して聞き取れないようなことが実際にあるのか尋ねました。","respondent":"川口交通安全担当課長、平原防災体制整備担当課長","answer":"こちらにつきましては７８.９％です。その推移的なところにつきましては、微増という形には、徐々にこれからなっていくのかというふうなところです。例えば午後５時の試験放送などについては、時間もかぶるということもございまして、それぞれ聞きづらいというようなお話が出ることはあります。","id":"exchange-118"},{"speaker":"大倉委員","kind":"質問・要望","question":"平成１５年からですからもう大分経っているという中で、あともう１点、どのような契約になっているのでしょうかということを教えてください。おおむね６か月ぐらいで取りに来て、６か月はどういう根拠なのでしょうか、説明を求めました。","respondent":"川口交通安全担当課長、平原防災体制整備担当課長","answer":"先ほどご説明させていただきましたように、もともと区内１か所しか保管所がなかったところに、不動前が設置されたという経緯もございましたので。条例の施行規則等においても、それぞれの規定を設けているところです。あるいは音声のスピード、そういったところを工夫させていただきまして、なるべく聞こえやすいような形で放送させていただいているところです。","id":"exchange-119"},{"speaker":"大倉委員","kind":"質問・要望","question":"大体１か月、３０日ということで記載されていて、放置自転車の保管所としてだけ使うというのは非常にもったいない立地だなと思っています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"この品川区においても、さっきの報告で設置をされたということですが、何か所設置して、何人分用意されたのですか、教えてください。地震発生時から設置して開設するまで、何時間ぐらいかかったのか、説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"ただいまご質問のございました１０月７日の地震における品川区の対応ですが、実際には一時滞在施設の開設は行いませんでした。ただ、先ほどのお話のとおり、最終的には滞留者も順次減っていきましたので、開設せずに済んだということになったところです。","id":"exchange-121"},{"speaker":"須貝委員","kind":"質問","question":"使う使わないは別なのですが、こういうときに、大体何人分ぐらいを用意されるのですか。実際に人は使わなかったのですが、どれぐらい時間がかかったのですか、説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"例えば先日のような地震、想定している全ての一時滞在施設というよりは、直ちに対応できる区有施設を中心に考えたところです。そういった意味で対応も早かったといったところです。","id":"exchange-122"},{"speaker":"須貝委員","kind":"質問","question":"港区、足立区では、準備するまでに大体５時間かかったそうです。もう一度だけ、どれぐらいの人数を想定してつくられたか、説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"今回、１０月７日の地震に対しましては、３か所を考えたところでございまして、合計の受入れ想定人数といたしましては２５２名の施設を用意させていただいたところです。","id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"住んでいるのでしょうか。もしそういうことがなければ、いざというときには全然対応できないということではないか尋ねました。","respondent":"山本防災課長","answer":"区では、業務継続計画を策定しておりまして、その中で時間別の参集職員の数等を算出しています。それから６ｋｍ圏内の職員という形で参集することになってございまして、おおよそ五、六百名の職員が来ることを想定しています。","id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"３０年以内に大地震が起きると言っているのですから、２００人待機できる場所を、そういう時期に来ているのではないかというふうに思うのです。でも、その間に、いろいろ被災した方は待っていられるのか尋ねました。","respondent":"山本防災課長","answer":"震災発生時の初動というのはとても重要だというふうに考えてあります。職員待機寮を設置しておりまして、毎月訓練等も行いながら、様々な初動対応をできるような体制をとっているところです。","id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"そうしたらどうするのですか。いざというときの臨戦体制に備えて、そういう待機施設を用意しておくというのが当たり前のことではないか尋ねました。","respondent":"山本防災課長","answer":"初動の対応ですけれども、職員向けの初動対応マニュアル等を作成しておりまして、区のあらかじめ指定された参集場所に参集するように示しています。","id":"exchange-126"},{"speaker":"須貝委員","kind":"質問・要望","question":"マグニチュード８クラスの大地震が起きたときに、人命救助が緊急に求められた場合ですが、現場で救助作業に参加できるのですか。命令系統も途絶えてしまうと思うのですけれども、その前にこういうことができるのですか、説明を求めました。","respondent":"山本防災課長","answer":"緊急の救助活動ですが、基本的には消防等が行う役割だというふうには考えてありますが、区の職員が参集場所に参集する途中でそういった場面を見ましたら、救助を行うことは当然だというふうに考えてあります。","id":"exchange-127"},{"speaker":"須貝委員","kind":"質問","question":"でも、このコロナ禍では実際はできないではないですか。私は圧倒的に足りないと思うのですが、ご見解を説明するよう求めました。","respondent":"平原防災体制整備担当課長、山本防災課長","answer":"私からは、備蓄倉庫のことにつきましてお話しします。委員ご指摘のとおりでございまして、各学校の備蓄倉庫以外に、区内２５か所に分散して備蓄倉庫を用意させていただいているところです。 確かにコロナ対応ということで４割減になってしまいますけれども、在宅避難等を推奨しておりますので、そういった部分で対応していきたいというふうに考えてあります。","id":"exchange-128"},{"speaker":"中塚委員","kind":"質問","question":"次に、３５１ページの防災対策に関わって、ホテルを借り上げた避難所について、それぞれ伺いたいと思います。そして、この排水システムは、雨量が何mm対応なのか、それぞれお伺いいたします。","respondent":"鈴木都市計画課長","answer":"まず初めの９月１８日、委員のほうでもご説明いただきましたが、排水ポンプ等が稼働する前であったためです。それから３点目、排水のポンプがついているわけですが、基本的には１時間６０mmの雨量に対応できる設備となっているです。","id":"exchange-129"},{"speaker":"中塚委員","kind":"質問・要望","question":"車は、３０cm水がたまるとエンジンが止まるというふうに伺っております。この６０mm対応ではなく、素早く車両の進入を止めるための対策の強化を東京都に求めてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"想定する６０mm対応を超える、例えば短時間で本当にゲリラ豪雨的に雨が降った場合の対応は、その後。局所的に６０mmを超える豪雨が降りそうだというときの対応等も含めて、その場に合わせて対応していただけるのだというふうに思っているところです。","id":"exchange-130"},{"speaker":"中塚委員","kind":"提案","question":"その６０mm対応を超える豪雨の際に、事故が発生しないように強く東京都に求めてほしいと求めました。従来の計画を変更して、ホテルを借り上げ、避難所として活用してほしいと求めましたが、いかがか尋ねました。","respondent":"山本防災課長","answer":"区といたしましては、区民避難所等を開設いたしますので、こちらに避難していただくというのが基本だというふうに考えてあります。ご提案いただいているホテルの利用につきましては、あくまでも避難所での受入れができない場合の補完的な利用を区としては想定しています。","id":"exchange-131"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり避難所の受入れができないときの補完的なものだということですが、この計画をなぜ変更することができないのか、改めて伺いたいと思います。学校から借り上げたホテルに移動して避難所とすることにしていただきたいのですけれども、なぜこれができないのか、伺います。","respondent":"山本防災課長","answer":"できない理由ですが、考え方として、ホテル旅館組合と災害時協力協定を結んですが、協定の趣旨からすると、区で対応が難しい場合に事業者の力を借りる、そういったことかと考えていますので、区で対応できる場合は、当然区で責任を持って避難所を開く、そういう考え方です。","id":"exchange-132"},{"speaker":"中塚委員","kind":"質問・要望","question":"毛布１枚のみの粗末な寝具、高齢者の配慮なし、多くの災害を経験するたびに災害関連死の多くが避難所生活によるものだということも判明しております。パーテーションなどの備蓄も１,２００人分用意しておりますけれども、協定の変更も含めて、ご答弁ほしいと求めました。","respondent":"山本防災課長","answer":"感染症対策等も実施していますので、区民の皆様には安心して避難所のほうに避難いただければというふうに考えてあります。協定の見直しについても、今のところ考えてございません。","id":"exchange-133"},{"speaker":"中塚委員","kind":"質問・要望","question":"協定の変更は考えていないとご説明がありましたが、ぜひ変更を検討していただきたいと求めたいと思います。熱海市では、ホテル避難所の経費が４億７,３００万円ということで、国、県、市が共同して設置、運営をしたと伺っております。","respondent":"山本防災課長","answer":"国と都で経費を負担される場合は、災害救助法の適用になった場合、その場合、国と都のほうで基本的に負担をするということになってあります。住家の滅失世帯が都内で２,５００世帯以上、かつ区で７５世帯以上等、こちらを満たせば補助等が得られるという形になってあります。","id":"exchange-134"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれが経費を分担するということになるのか、その条件に品川区は合うのか合わないのか、ご説明ほしいと求めました。","respondent":"山本防災課長","answer":"住家の滅失世帯が都内で２,５００世帯以上あった場合で、区内で７５世帯以上の滅失、国の補助等が受けられるというものになってあります。","id":"exchange-135"},{"speaker":"中塚委員","kind":"質問・要望","question":"被害の状況によって災害救助法が適用されるかどうかが決まるということで、品川区の３者が、改めて確認させてほしいと求めました。ぜひ品川区でも実施をしてほしいと求めましたが、改めていかがか尋ねました。","respondent":"山本防災課長","answer":"災害救助法の救助項目で１つ、ホテルなどを借り上げて実施することが可能ということは書いておりますので、こちらの要件を満たせば可能かというふうに考えてあります。","id":"exchange-136"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひこの経験を品川区でも活かしてほしいと求めました。従来の考え方を変更して、ホテルの活用を重ねて検討していただきますよう要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-137"},{"speaker":"せお委員","kind":"質問","question":"私からは、３１５ページ、交通安全啓発費、３１７ページ、道路点検システム費についてお聞きします。そして、このシステムによって、どのような効果というか、利点があるのかも併せて説明を求めました。","respondent":"溝口道路課長","answer":"１つの効果としては、取り組む前の平成２８年の区民からの要望が、今現在では半減しているという１つの効果が出てきているところです。そういった中で、区民からの苦情が減ってきたというのが１つの大きな効果だと考えているところです。","id":"exchange-138"},{"speaker":"せお委員","kind":"質問・要望","question":"こちらに加えて、区は、スマホアプリを使って道路の損傷や不具合を簡易に投稿することができる道路通報システムの試行を始めました。そこで、まだ始めて４か月ほどしか経っていませんが、このアプリの利用状況をお聞かせいただきたいのと、今後の方向性を説明するよう求めました。","respondent":"溝口道路課長","answer":"９月までの間に、新規の登録者数としては９６名の方に登録をいただいておりまして、通報件数としては４０件いただいているところです。４か月間使ってみて、特に不具合等があるわけではありませんし、ほかのものの通報にも転用できればというふうに考えているところです。","id":"exchange-139"},{"speaker":"せお委員","kind":"質問","question":"例えば、商店街だったり、あと町会・自治会などで、代表の方がアプリを取り込んで利用していただくといったお知らせをするのはいかがでしょうか。そういった積極的な今後の取組みについても見解をお願いします。","respondent":"溝口道路課長","answer":"これまでも６月１日から試行するに当たって、または、８月１日には広報しながわによる周知をこれまで行ってきたところであります。このアプリを知ってもらうことから始まると思いますので、委員ご提案の件も含めて、さらに周知を図っていきたいというふうに考えているところです。","id":"exchange-140","title":"町会・自治会支援"},{"speaker":"せお委員","kind":"質問・要望","question":"さらに今年の予算特別委員会で、公園の遊具を少し取り替える程度だと、利用者などにはご意見を伺っていないとお聞きしました。公園においては、損傷や不具合などとともに、それぞれの公園に対するご意見も伺えるようなアプリを取り入れていただきたいと思っています。","respondent":"高梨公園課長","answer":"道路課とも一緒になって、今、検討しています。２６８の公園・児童遊園等がありますけれども、本システムが拡大適用できるかどうかについて前向きに検討していきたいというふうに考えております。","id":"exchange-141"},{"speaker":"せお委員","kind":"質問・要望","question":"これはまだ検討もされていないわけですから、要望だけお伝えしますが、設備からの検索機能も欲しいです。なので、先ほどお話ししたような公園に関するアプリが実現すれば、このような機能も取り入れていただきたいと今は要望で終わらせます。","respondent":"川口交通安全担当課長","answer":"令和２年度中に、それぞれ区では警察などと連携をいたしまして、自転車シミュレーター等を活用した交通安全教育等も実施しております。一部の学校では、なかなか交通安全教室ができないということで、その回数が減っていたというところが課題なのかなという認識です。","id":"exchange-142"},{"speaker":"せお委員","kind":"質問","question":"自転車教室を実施して、交通安全講話や筆記テスト等を終了した３年生以上を対象に、自転車運転免許証を交付しています。今ご紹介したような様々な取組みや、民間活用も含めて、今後の自転車の交通安全対策について見解をお願いします。","respondent":"川口交通安全担当課長","answer":"自転車の交通安全教室を実施する際には、これは反射材を兼ねたシールを配布させていただいて、安全意識の啓発に努めているところです。ご家庭等でも、交通ルール、マナーを考える場をしっかりと設けていただきたいということを区として訴えていきたいというふうに考えております。","id":"exchange-143"},{"speaker":"塚本委員","kind":"質問・要望","question":"３２５ページの治水対策推進助成事業とか、３５５ページの集中豪雨等対策費、防災対策としての流域治水ということに関してお伺いしたいと思います。そこから１回外に出て、こういう道路になっておりますけれども、自転車はどのような通行になるのかということをお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"補助２６号線ですが、まず初めに、側道工事ですが、東京都に確認しましたところ、１つは住吉踏切のところの歩道橋になります。そこが供用開始されてありますが、１０月２２日に供用開始される車道部分につきましては、法的に自転車の走行はできないというふうに聞いてあります。","id":"exchange-144"},{"speaker":"塚本委員","kind":"質問・要望","question":"午前１１時にいきなり今まで通れなかったところがいろいろ通れるようになるというところで、いきなり事故とかが起こらないかという心配もあります。警察官の方が出張られるのか、警備の方々が出張られるのか、何かそういう対応はとられるというふうに聞いていますか尋ねました。","respondent":"鈴木都市計画課長","answer":"午前１１時になりましたら、まず一般車両を入れずに、一通り警察が誘導して渡り切った後に供用が開始されるというところまでは聞いてあります。","id":"exchange-145"},{"speaker":"塚本委員","kind":"質問・要望","question":"水害の危険性が高まっておりますけれども、水害というのはあらかじめ予測ができるというところで、適宜適切な対応が求められていると思います。国のほうで決まったわけですけれども、区として、この行動計画等、今後どのような取組みがなされるというふうに想定されているか、説明を求めました。","respondent":"栗原河川下水道課長","answer":"立会川につきましては、東京都都市整備局が事務局となりまして、城南地区河川外３河川流域治水協議会が今年の８月に設置されたところです。先ほどご説明のあった、国の中でも計画が策定されたところですが、連携して流域治水を計画的に推進することとしております。","id":"exchange-146"},{"speaker":"塚本委員","kind":"質問・要望","question":"この流域治水の行動計画ですか、そういったところについて少しお伺いしたいのですが、現段階で教えていただけることをご答弁ほしいと求めました。","respondent":"山本防災課長","answer":"区でも想定し得る最大雨量でのハザードマップ等の作成をしていますので、引き続き、区民の皆様に周知等を図っていきたいというふうに考えてあります。","id":"exchange-147"},{"speaker":"塚本委員","kind":"質問・要望","question":"今後の流域治水に関わる情報の提供というのですか、また、そういった情報発信ということを今後ぜひ進めていただきたいというふうにも思っております。そういった新たな取組みといったことにつきましても、何か今の段階でお聞かせいただけることがあれば、最後にご答弁をお願いいたします。","respondent":"山本防災課長","answer":"情報発信につきましては、区民の方の適切な避難行動につながるよう、新しい技術等を活用しながら、区といたしましても、迅速かつ適切な情報提供を行っていきたいというふうに考えてあります。","id":"exchange-148"},{"speaker":"石田（秀）委員","kind":"提案","question":"これは確認なのですけれども、これで提案をしたいのは、水上のアクティビティスペースをやったらどうかという提案です。こういうものをやっぱり水辺に整備していってもらうということが非常にいいと思うので、ここら辺の水辺関連のことを答弁ほしいと求めました。","respondent":"栗原河川下水道課長、高梨公園課長","answer":"１点目、桟橋の整備を今年度実施する予定で、現場の調査や水域の占用手続等を行っているところです。引き続き、水辺のにぎわいに何ができるか、我々としてもしっかり検討してまいりたいと思います。その管理運営につきましては、区と地域の方々と話し合う必要があるのかなというふうに思っているところです。","id":"exchange-149"},{"speaker":"石田（秀）委員","kind":"質問","question":"それからもう１個は、公園で、さっき四季の花という話をしたのだけれども、紅葉をどう考えているのかなと。何か特徴ある、ぜひそういうものも取り組んでもらいたいと考えていますので、そこをあえて説明を求めました。","respondent":"栗原河川下水道課長、高梨公園課長","answer":"高い柵が設置されているような箇所も多く存在しておりますので、親水性の向上に向けた検討は進めていきたいというふうに思っているところです。景観につきましても、陸側からの水辺景観だけではなくて… 約５万m2の広大な公園ということで、東京都と、しっかり一度お話をする場を設けたいなというふうに考えているところです。","id":"exchange-150"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それはもちろん競馬場も午後９時までという約束は地域の方とやっているけれども、やっぱりそれは午後１０時ぐらいまでやるべき話だと思っています。もう１つの話は、そういうことも含めて建て替え計画を出してくるべきと考えていますので、最後にそこだけ伺いたいと思います。","respondent":"高梨公園課長","answer":"その場所について、同じ場所で改築すれば、どういったところが一番有効にリニューアルができるのかといったことも含めて検討しています。","id":"exchange-151"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701177?Template=document&Id=1508#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":120356,"voices":354}},{"id":"r03-20211012-4","meetingId":"r03-c-settlement","date":"2021年10月12日","dateIso":"2021-10-12","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を146件整理しています。","topics":[{"id":"topic-01","title":"◯渡部委員長 ただいまより、決算特別委員会を開きます。 それでは、令和２年度品川区一般会計歳入歳出決算","agenda":"◯渡部委員長 ただいまより、決算特別委員会を開きます。 それでは、令和２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは３６７ページ、オリンピック・パラリンピック教育推進事業、時間があれば、成果報告書４６ページの学校ＩＣＴ活用経費についてお伺いします。１点目、オリンピック・パラリンピック教育推進事業の中で、オリ・パラ教育について、何点かお伺いしたいと思います。","respondent":"工藤指導課長","answer":"体験や講演などをオンラインによって実施することで、ねらいとした学びは一定程度達成できているものです。例えば、自らの生活を見直してしっかり生活したいなどの気づきになったというところが、前と後での特に現れた効果だと認識しています。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問・要望","question":"特に、ぜひ続けていただきたいという思いで質問していきますが、国や都の補助金もたくさんあって進めてきたところがあると思うのです。先にその２点お願いします。","respondent":"工藤指導課長","answer":"パラスポーツの体験やアスリートとの交流を継続し、オリンピック・パラリンピック教育のレガシーとして取り組んでまいりたいと考えています。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"提案","question":"私個人としては、いつもボッチャを推していまして、以前も区民大会や区の公式スポーツにボッチャをというご提案もさせていただきました。パラスポーツで学ぶではなくて、交流をするというのが１つ大きな事業になるのかなと思いますので、そちらもあわせてご見解を説明するよう求めました。","respondent":"工藤指導課長","answer":"あるいは車いすバスケットボールのパラアスリートとの交流などを実施しており、体験が児童・生徒の貴重な学びの場になるものと考えておりますので、しっかりと検討して継続していきたいと考えております。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"次の質問、５つの資質の中の国際的な視野についてもお伺いします。国際交流というところで、英語教育についてお伺いします。","respondent":"工藤指導課長","answer":"小学校から英語学習を行います意義につきましては、現在小学校１年生から繰り返し英語の音と文字に慣れ親しむとともに、低学年の１年生から行うことが必要であると考えています。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"提案","question":"国際的な視野、国際交流というところでいうと、英語で会話するということを主にした授業の取組を継続的に取り組んでいただきたいなと思っています。オークランド、ぜひ子どもたちとＺｏｏｍを通じて英会話の交流というのをご提案させてほしいと求めましたが、ご見解を説明するよう求めました。","respondent":"工藤指導課長","answer":"８年生全員が、オンラインレッスンの授業では外国人講師とマン・ツー・マンで英会話を行ったりといった機会を大切にしています。調整しなければいけないことが多少あり、今後、研究が必要であると考えています。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"意見","question":"オークランドに関しては４時間程度プラスになるということで、こちらが１０時だとあちらが１４時など、ちょうどいい時間になるのかなと思います。そして、英語でのコミュニケーション能力を鍛えるというところで、ぜひご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"つる委員","kind":"提案","question":"３７９ページ、今年度から小山三丁目が後地小学校の通学区域になっていますけれども、その辺の対応を伺っていきたいと思います。「わたしたちの権利」日本語版教材の活用を提案というか、求めたいと思いますが、区の教育委員会の見解をお知らせくださいとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"本区としましては、人権教育は大変大事だと考えております。それぞれの情報提供をいただいておりますので、ぜひ内容をしっかり確認して、教員研修等での活用等を研究してまいりたいと思います。","id":"exchange-007"},{"speaker":"つる委員","kind":"提案","question":"昭和６３年の第２回定例会で、会派の先輩議員が当時、食育という視点も含めて、陶磁器を提案しています。８０％以上がしっかりリサイクルをされると伺っておりますが、そうした中で、破損による取替えが年間約２,０００万円弱との意見を述べました。","respondent":"勝亦学務課長","answer":"こちらについては、丈夫で劣化しないという、メリットが非常にあるものではありますけれども、裏を返しましたら、リサイクルや廃棄が難しい。そういった部分につきましては、今後、研究を重ねてまいりたいと考えております。","id":"exchange-008"},{"speaker":"つる委員","kind":"提案","question":"私もいろいろ確認をさせていただいて、いろいろな工夫をして、いろいろなトレーを提案しているというのも理解しています。別の機会で伺いたいなと思いますので、その辺りも頭に入れておいていただきたいなと思いますとの意見を述べました。","respondent":"吉田品川図書館長","answer":"とある小学校では、寄贈された関連書籍４６冊につきまして、学校図書館のコーナー内に設置しているところです。複数の学校で、教科学習においてＳＤＧｓの関連図書を活用しまして、また、選書の際に考慮している様子が報告されているところです。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"時間があればご答弁ほしいと求めましたが、２学期が始まって、それが相当数出たとあります。最後、時間の限りでご答弁ほしいと求めました。","respondent":"吉田品川図書館長","answer":"図書館員につきましては、平日の昼間、図書館にいる子どもを見かけましたら優しく声をかけるなど、居場所としての図書館として、様子を見守ることとしています。","id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３６５ページ、市民科・各教科充実経費、３６７ページ、体力向上推進事業、同じく３６７ページ、グローバル人材育成塾についてお伺いいたします。具体的に、この片づけの授業をされているのかどうか、確認させてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"基本的に、児童・生徒はたくさんの荷物、教材を持って生活しておりますので、４５分や５０分、その授業の中で１つ１つ片づけを指導します。家庭科等や技術等でも、片づけを指導しています。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"片づけの授業はされておられるということで確認をさせていただきました。お願いします。","respondent":"矢部教育総合支援センター長","answer":"市民科の中でも単元がありまして、そこでも指導しますので、これは全校で取り組むことになっています。この道具を見て、そのときに片づけるという視点はとても大切だと感じておりますので、生活指導主任会等でも周知していきたいと思います。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続きまして、３６７ページ、体力向上推進事業についてお伺いいたします。この結果を踏まえて、今どのように捉えているのか、お尋ねしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"正確な数値を全体的に比較できないのですが、一昨年までは伸びているということを踏まえた上で、今後のことについて捉えも含めてお話しします。そのような背景があるのではないかと考えております。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、同じく３６７ページ、グローバル人材育成塾についてお伺いいたします。述べさせてもらったのですけれども、本当に具体的でいいのですが、取組内容を教えてほしいと求めました。","respondent":"工藤指導課長","answer":"直近で、今年度も令和３年度から令和４年度までのところで、９月から開始しておりますが、現在２６１名が学んです。外国人講師との英会話レッスンを通しながら、実践的な英会話能力を身につけるというところで取り組んでいる取組です。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問","question":"学校公開ということで、それぞれ学校単位でやることだと思うのですが、具体的な内容がもう少し分かれば教えてほしいと求めました。","respondent":"工藤指導課長","answer":"本年１１月６日土曜日に予定しております「SHINAGAWA GLOBAL DAY」のお尋ねです。土曜日の午前中に授業公開を行いますけれども、様々講師をお呼びするような授業を、土曜日は講師の手配の関係などで実施できなかった部分があります。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"確認","question":"それを確認させてください。これは、それぞれ学校ごとに、英語教育や市民科、オリ・パラ教育をやるということでよろしいのか尋ねました。","respondent":"工藤指導課長","answer":"区教育委員会のホームページには、現在その取組に当たるもので公開できるものは既に公開しております。子どもたちの様子を参観いただければと取り組むものですので、各学校の時間割については、各校ホームページで確認いただければと考えています。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"第５波で１度は中止になってしまった移動教室や修学旅行ですが、改めて実施できるように各学校を支援していただきたいのですが、いかがでしょうか。現時点での実施状況の概要とあわせて伺いたいと思います。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"緊急事態宣言等が小刻みに度重なって出たことがございまして、そのたびに何度か日程変更を繰り返す等、対応を検討してまいりました。６年生、８年生ともに、代替の事業を実施できるように検討しています。 さらに、秋にも６校予定しております。３月にも６校予定してございまして、宿の方との連携をしたり、何とか実施したいという状況です。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"簡易検査キットの配布など、ぜひ移動教室と修学旅行の実施の上で、考えうる限りの支援を行うようお願いしたいと思います。ＰＣＲ検査なのですが、まず、今年度の学校の児童・生徒の感染者数、教職員の感染者数は何人なのか伺います。","respondent":"勝亦学務課長、工藤指導課長","answer":"今年度の児童・生徒の陽性の判明者数につきましては、昨日までの累計で３４７名となっています。 令和３年度４月以降、教職員の感染者数につきましては、昨日現在で３８名です。","id":"exchange-018"},{"speaker":"安藤委員","kind":"確認","question":"衛生費のほうでガイドラインについて伺ったのですが、同じ部活等の全員に、８月２７日付の文部科学省ガイドラインの区の対応について伺ったのです。区教育委員会に確認したいのですが、基本的にクラス全体を広く検査するという対応をとるということでいいのか、確認したいと思います。","respondent":"勝亦学務課長","answer":"そういったものを１つ１つ確認いたしまして、濃厚接触の疑われる者に対して、必要な検査を行っているという状況です。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのですが、先ほど、今年度の学校の子どもの感染者は３４７名ということでした。人数を伺いたいと思います。","respondent":"勝亦学務課長、工藤指導課長","answer":"ＰＣＲ検査についてです。必要な方に必要な検査を保健所と相談しながら実施していますけれども、今年度につきましては、１,８９４人に実施しております。 教職員の今年度の検査数につきましては、１７２件です。品川区に限らず、居住地域の保健所等の指示によって受けているものがありますから、そういったものも含まれているとご理解いただければと思います。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"来年４月から学校が法律どおり３５人の学級編制を実施すると決めた場合、それに対応する教室は既に確保されているのでしょうか、伺います。受入可能な環境をつくるため、区教育委員会としてはどのような措置、対応を行ったのでしょうか、伺いたいと思います。","respondent":"勝亦学務課長、有馬庶務課長","answer":"ただいま、学校選択制の希望受付を行ってございまして、各学校への入学予定者がこれから定まっていくような状況です。そういった中で、３５人編制の義務標準法が改正されておりますので、経過措置を含めて… 具体的な教室の確保ですけれども、芳水小学校、第二延山小学校とも、多目的室を普通教室に変える、第二延山小学校は、やむを得ず、今回は和室を普通教室化するというところで教室を確保して、来年に備えるという対応をしています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"まさに子どもの権利条約の精神にのっとった対応が、私は必要だと思うのです。伺いたいのですが、その意見を踏まえて決めるべきだと思うのですけれども、そこについてはいかがか尋ねました。","respondent":"勝亦学務課長","answer":"法律的に、学級編制につきましては、区が責任を持って行うことになっております。そういった中で、各学校の状況、学校の意見を聞きながら、編制してまいりたいと考えております。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"その学校の意見を聞きながらというのは当然だと思うのです。私が伺ったのは、子どもや保護者の意見も踏まえた上で判断すべきなのではないですかと伺ったので、もう一度しっかりとお答えほしいと求めました。","respondent":"勝亦学務課長","answer":"そういった考え方もあろうかと思いますけれども、お子様の様子や保護者の声、お子様の声を聞いてあります。その中で最善の教育ができるように学校も判断をして、意見をいただいて、区のほうで判断しています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は子どもの権利条約の精神に反するというか、子どもの声を聞くということを直接やらないといけないし、かなり学校の傲慢ではないかと思います。教育環境に関することですので、しっかりと子ども、保護者の意見を聞いてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"くにば委員","kind":"質問","question":"現在、品川区で配付されているタブレットのチャット機能の利用について、制限をしているのか、それとも授業中に利用しているのか、もう１点伺います。メリット、デメリットの認識、また、今後の利用についての協議や検討状況をお伺いします。","respondent":"勝亦学務課長","answer":"このような問題を抑止できるというメリットはあると考えていますが、社会に出てから、現実との違いの部分があろうかと考えています。今後も、こういったいじめにつながるようなアプリケーションやサイトへのアクセスはしないようにしていきたいと考えております。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問","question":"品川区では、現在、配付している端末のＩＤやパスワードの運用について、どのようにされておりますでしょうか。例えば、このようにＩＤやパスワードが統一されていたり、誰でも簡単に類推できるような状況になっていないでしょうか、お聞きします。","respondent":"勝亦学務課長","answer":"配付の時点では、必ず他人に類推されないようなご自身のパスワードに変更して、他人に教えないということを指導の中で徹底しております。そういった意味では、類推されてパスワードが漏れてしまうというおそれは少ないと考えております。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問","question":"誰でも、何回でも、正解にたどり着くまでひたすらパスワードが入力できてしまうようなシステムの脆弱性等が今回のシステムにもないのかどうか。そのセキュリティ面についてお伺いします。","respondent":"勝亦学務課長","answer":"パスワードのハッキングに関してです。５回以上間違えますとロックがかかるような仕様になってありますので、ハッキング等のおそれは少ないと考えております。","id":"exchange-027"},{"speaker":"くにば委員","kind":"確認","question":"今、お伺いした形で、基本的には高いセキュリティ意識を持って、今後も運用に取り組んでほしいと求めました。翌平成２０年には、当時確認できた学校非公式サイトは、全国で３万８,２６０件。","respondent":"矢部教育総合支援センター長","answer":"生活指導上で困ったことがあったら、教員が察知したりということになります。今後も、情報共有も含め、生活指導主任会のほうで対策も一緒に考えてまいりたいと思っています。","id":"exchange-028"},{"speaker":"くにば委員","kind":"質問","question":"それに関して実害はないとお伺いしました。もしくは品川区の教育委員会として、ネットパトロールをどのように実施されているのか、その辺についてお伺いします。","respondent":"矢部教育総合支援センター長","answer":"ＨＥＡＲＴＳも含め、いろいろな情報共有の中で、１か月に１回の生活指導主任会で共有して確認しております。","id":"exchange-029"},{"speaker":"くにば委員","kind":"質問","question":"しながわ電子図書館、現在の利用登録者数や登録者の年齢層、年齢別の利用頻度などを伺いたいと思っていたのですけれども、そこら辺は割愛いたします。そういった切り口でのジャンル分けのコーナーを設けて、もう少し興味を引くような分かりやすい掲示方法をお考えになられてみてはいかがか尋ねました。","respondent":"吉田品川図書館長","answer":"６月から電子図書館を始めまして、まだ１,０００冊ほどしか蔵書がないところでございまして、分類もなかなか細かくは分けられないところです。そのような形の中で、今後、蔵書を増やしていく中で、見せ方の辺りにつきましては、考えてまいりたいと思います。","id":"exchange-030"},{"speaker":"くにば委員","kind":"質問・要望","question":"時間がないので最後に伺いたいのが、現在、しながわ電子図書館に導入する選書の方法。推進をしていただきたいのですけれども、その選書について、最後にお伺いします。","respondent":"吉田品川図書館長","answer":"電子図書館で導入できる電子図書につきましては、なかなか一般に販売されているものよりも種類が少ないなど、条件がいろいろあります。その中で、図書館として、図書館の職員が、これはまずは十分なものではないかというところから導入しています。","id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"国は、就学状況が確認できない状況があることや、今年の２月に夜間中学の設置促進を各都道府県と各指定都市の教育委員会に依頼の通知をしています。これまで区教育委員会は、夜間中学のニーズ把握を行っているのか尋ねました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"先ほどの夜間中学校について、現在、ニーズの把握までは特別行っておりません。協議会のほうも、今のところは行ってございません。 既卒者などの場合で、現在、不登校施策として区として行っているマイスクールの取組や不登校施策というのは非常に充実しています。そういった直接的な声を、現状、聞いているところではないです。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"そして、図書館で全校の校則が確認できるよう求めますが、見解を伺います。成功事例として、議論の様子などを区教育委員会としてホームページ等で広報するなどの取組を求めますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"は地域の意見を吸い上げて、独自の校則ができていると認識していますので、それは１校の中で進めればよいのかと考えております。現状のお子さんたちのフォローに努めてまいりたいと考えております。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"以前行われていた５年生のプログラムの再開と、中学校での実施を新たに求めたいと考えますが、見解を伺います。必ず最低でも１度は受講すること、何回でも受けられるよう拡充を求めますが、見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"様々、これからも保護者や生徒たちの様子を見ながら、こういった身を守る活動については進めてまいりたいと考えています。体罰の防止については、何度も校内で研修していますので、その中からエキスを取って指導しているものと認識しています。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"必要なのは５年生のほうだったというご意見を伺っています。そして、あわせて、その相談を受け入れる体制も整えてほしいと求めますが、見解を伺います。","respondent":"工藤指導課長、勝亦学務課長","answer":"それは、正しく児童・生徒理解に努めることと、どのような児童・生徒指導が正しいのかというのを含めながら研修を行っているものです。そういった意味では、体罰防止研修は、引き続きしっかりと行っていきたいと考えているところです。香りに関係します化学物質過敏症の関係ですけれども、給食のかっぽう着等の対応につきましては、お声があれば個別に対応しております。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"市民科授業地区公開講座について伺います。全学校の公開講座予定日を一覧にしたものを区教育委員会ホームページで掲載していただきますよう求めますが、見解を伺います。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"文部科学省の啓発のポスターに関しまして、適宜掲示するなど、活用をお願いしますということですので、そういった旨で学校のほうに送付しています。掲出に関しましては、各学校での判断になろうかと考えております。 今年度につきましては、できる限りの方法でやるということを学校から聞いております。ホームページにつきましては、各学校から情報をもらっていただきたいと思います。","id":"exchange-036"},{"speaker":"木村委員","kind":"質問・要望","question":"この運動を始めて、以前と現在では、子どもたちの登下校に対し、何が大きく変わったのでしょうか。あればお聞かせいただきたい。","respondent":"有馬庶務課長","answer":"８３運動ですけれども、これにつきましては、かつて小学校ＰＴＡ連合会が、子どもの安全をテーマに取り組んだということで始まってあります。そのような活動は、多少、広く周知されている部分はあるのではないかと考えているところです。","id":"exchange-037"},{"speaker":"木村委員","kind":"意見","question":"もしそうであれば、これは大変すごいことだなと思います。本区の考案した８３運動、今以上に全国に広がることを願いますけれども、今後の展開というものは、どのようになるものと想像されますかとの意見を述べました。","respondent":"有馬庶務課長","answer":"この８３運動は、品川区で生まれたと認識しております。さらには、それもしっかり相談に乗っていきながら、側面支援を続けていきたいと考えているところです。","id":"exchange-038"},{"speaker":"木村委員","kind":"質問","question":"日暮れが早くなるためということを伺っておりますけれども、そう考えますと、夏は午後６時過ぎから７時近くまで明るいという状況であります。この８３運動を８４運動や８５運動などということは考えられないのかどうか、説明を求めました。","respondent":"有馬庶務課長","answer":"朝８時は上級生もそんなに変わらないと思いますけれども、そんな意味で低学年が下校する時間の午後３時というのが、その当時にあったと思います。","id":"exchange-039"},{"speaker":"木村委員","kind":"質問","question":"次に、３６３ページの中ほどにあります、人権問題から質問をいたします。現在、学校現場ではどのような取組を行いながら人権教育を進めているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"毎年１２月の人権週間にあわせまして、人権啓発課と連携いたしまして、品川区立学校人権標語・ポスター展を行っております。全校の児童・生徒が作品づくりを通して人権意識を高めるだけでなく、展示公開することで区民等への啓発にもつなげてあります。","id":"exchange-040"},{"speaker":"木村委員","kind":"質問","question":"本区が掲げる、いじめ根絶宣言の実現に向けて、どのような取組を行っているのでしょうか。説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"全ての学校の７年生全員を対象に、毎年６月と１０月に実施する中で、周りにあわせられない子は誰なのかなどを調査しております。いじめ防止推進デー等で推進しています。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問・要望","question":"本日は３７９ページ、学校維持管理費、そして、３６３ページ、生徒指導対策等経費、これは校則についてお伺いしたいと思います。改めて教室等、学校内への防犯カメラの設置について検討していただきたいと要望いたしますが、見解を伺います。","respondent":"有馬庶務課長","answer":"学校のほうには、大体５台から１０台程度、学校によって差はありますけれども、基本的には防犯という対応で、これまではカメラを設置してきたです。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問・要望","question":"ニュースに、「校則で『三つ編み禁止』とまどう黒人ハーフ中学生特有の髪質に配慮求めるも『本数制限』が条件に」という記事が掲載されました。こうした校則は、マイノリティの問題もあるので、改めたほうがいいのではないかと思いますが、ご見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"じっくりしっかり学校が聞き取って、保護者とも相談して対応するべきと、その事実だけを伺うとそう感じました。情報共有しているところですので、少なくとも安全と健康につきましては、大事に対応していきたいと考えています。","id":"exchange-043"},{"speaker":"松本委員","kind":"質問・要望","question":"ただ、まず１つは、そのように書かれていることで、制約を受けると思ってしまうお子さんやご家庭があるということ。学校側が、それだったらいいですよという対応をしてくれるようにしていただきたいということを要望したいのですが、ここについてご見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"繰り返しになりますけれども、安全と健康に関わることについては、しっかり学校が向き合って、相談して、対応していきたいと考えています。","id":"exchange-044"},{"speaker":"松澤委員","kind":"確認","question":"現状１０校に１１人の配置、１５校全部の配置を目指しているということでしたが、現状を教えてほしいのが１つ。区でそれぞれ３分の１、この事業について品川区で活用があったのか、２点確認したいと求めました。","respondent":"矢部教育総合支援センター長","answer":"昨年度につきましては、委員がおっしゃったとおりですが、現在は１校増えまして、１１校で１２人です。補助の点ですが、モデル実施という名称は異なるかもしれませんが、国や東京都の補助を受けて部活動指導員を活用、配置しております。","id":"exchange-045"},{"speaker":"松澤委員","kind":"確認","question":"１校増えて１２人、確認できました。そういった課題が見える中、部活動の委託についても区の考え方を説明するよう求めました。","respondent":"矢部教育総合支援センター長","answer":"これから広げていく面でも、１つのハードルになっているのかなと考えております。委託につきましては、先ほど委員がおっしゃった費用の問題や移動距離の問題も十分吟味して研究していかなければいけないと考えております。","id":"exchange-046"},{"speaker":"松澤委員","kind":"質問","question":"どのようになって、どうつなげているのか、教えてください。そのような考えはどうでしょうか、ご見解を説明するよう求めました。","respondent":"矢部教育総合支援センター長","answer":"試合ができないというお子さんたちのために、地域の中学校同士が連携して、一緒に同じところで部活を行うというシステムがあります。先ほどの小中連携部活動など、そういったところで参加されているのかなと認識しています。","id":"exchange-047"},{"speaker":"松澤委員","kind":"質問・要望","question":"そういった中での小中連携部活動は、ぜひ率先して広げていってほしいなと考えています。一人ひとり、子どもたちが部活動をやりたいというものが少しでもできるような環境の配備を引き続き求めていきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"９校において小中連携部活動をやっております。失礼いたしました。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"提案","question":"何年かにわたってこれは要望させていただいて、自治会長からのそもそものご提案だったのですけれども、要望してまいりました。昨日の土木費で確認させていただきまして、４月１５日に大規模水害時の緊急避難に関する覚書を締結して、津波避難ビルに指定をしたとの意見を述べました。","respondent":"小林学校施設担当課長","answer":"了解が取れたところで、その後、設計、発注のために、メーカーと形状や納期についての打合せを行い、協議を進めたところです。工事完了につきましては、今年の１１月末までには設置ができる予定で現在進めております。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"提案","question":"１１月、ずっと何年もこのことを提案されて、実現を待っていた自治会長と一緒に完成を待ちたいと思います。いわゆる一般的に言われるＣＥＦＲというのですか、どの程度まで向上されているのか、客観的な数字があれば説明を求めました。","respondent":"工藤指導課長","answer":"全区立学校でＣＡＮ－ＤＯリストを設定して、それに基づき指導しておりますので、そういう意味では１００％実施しています。国の目標は５０％と言われているところですが、令和２年度、昨年度の品川区の９年生は８３.６％という数値を示しています。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問","question":"質問したかったのは、ＣＥＦＲ・Ｂ２レベルという、英検準１級以上のスコアを取得している英語教師の割合というのも調査の結果が載っておりました。英検準１級以上のスコアを獲得しているのが、全国的には３８.１％ということなのですけれども、この割合というのは何％なのか尋ねました。","respondent":"工藤指導課長","answer":"令和２年度、国が実施しました英語教育実施状況調査のところで、本区が回答した内容ですが、昨年度５９名在籍の英語教員のうち、ＣＥＦＲ・Ｂ２レベル以上という者は３９名、割合にして６６％いるということが分かったところです。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問・要望","question":"４技能というところで、この４技能がこれから大学受験等で非常に取り上げられて、テクニカルなものが求められる。今のところ６６％ということですので、そういったものを教員に対して行うというのは、このお考えはいかがか尋ねました。","respondent":"工藤指導課長","answer":"特に４月当初に初任で着任される教員と、あと、それぞれの個々の教員の資質・能力向上を含めての研修会を実施しています。先ほどの英語の各生徒の技能をはかるＧＴＥＣ調査というのを行いますが、やはり教員研修を実施して、それぞれの資質を高めているところです。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問・要望","question":"平成３０年１２月、「学校給食の牛乳にプラスチックストローを使用しないことを求める請願」というものを、全会一致で採択させていただきました。実は自治体でこれを全体で取り組むということを始めた自治体があるのですけれども、その辺について、学務課は状況というのはご存じか尋ねました。","respondent":"勝亦学務課長","answer":"給食でのプラスチックストローの取組というお話です。学務課で把握しておりますのは、実績としては、３分の２程度の学校がストローを使わない状態で牛乳を飲んでいると聞いてあります。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問","question":"年間約７トンのプラスチックごみの削減になって、約１,５００万本のストローが削減されると。学務課にもう一回伺いますけれども、品川区では、年間で何本のプラスチックストローをごみとして処理をしているのか分かれば説明を求めました。","respondent":"勝亦学務課長","answer":"ストローの本数です。今、品川の児童・生徒が約２万２,０００人、給食は大体年間１９０食ということで計算いたしますと、年間４２０万本余になるかと思います。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここについてぜひ最後にご答弁いただきたいのは、品川区でも、やはり環境教育というのをやっているのです。これについてしっかりと他自治体のことも見ていただきたいと思うのですが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"他自治体の事例も含めて、今後も、ストローの削減等につながる取組を研究してまいりたいと思います。","id":"exchange-055"},{"speaker":"おくの委員","kind":"質問・要望","question":"共産党は、この規定に基づいて、かねてから給食費の無償化を求めてきました。今回は、学用品、教材費、修学旅行費などの無償化を求めますけれども、この点、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"おっしゃるとおり、憲法２６条には、義務教育はこれを無償とするという記載があります。そういった中で、必要なもの、法に定めのある教科書ですとか給食の食材費、そういったものを無償化しています。","id":"exchange-056"},{"speaker":"おくの委員","kind":"質問","question":"同じ授業で使われる以上、同じように無償、無料であるべきなのではないでしょうか。この点、お伺いいたします。","respondent":"勝亦学務課長","answer":"最高裁の判例の中で、この定めについては、その他一切の費用を無償にすべく定めたものではないという判断が示されております。こちら、様々な意見があるとは承知していますけれども、この考え方に立つものです。","id":"exchange-057"},{"speaker":"おくの委員","kind":"質問","question":"つまり、できるということではないのでしょうか。その点、お伺いいたします。","respondent":"勝亦学務課長","answer":"無償化にできないことはないのではないかというお尋ねですけれども、こちら、自治体によっては、そういったものを無償化にしている自治体もありますので、無償化ができないということでないのは、おっしゃるとおりです。","id":"exchange-058"},{"speaker":"おくの委員","kind":"質問","question":"品川区で無償となっていない、有償であるままだというのは、やはりどういう根拠なのでしょうか。その点をお伺いいたします。","respondent":"勝亦学務課長","answer":"繰り返しになりますけれども、基本的には、法の定めにあります授業料の不徴収、それから、教科書の無償給与、給食の食材費以外の負担という法の定めに従って考えているものです。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問","question":"品川区がなぜ今有償のままかということをお伺いしているのですけれども、かつ、その費用を国において負担すべきことを宣言したものだと。このことをしっかりと受け止めるならば、それが判例にもしっかりと書いてあるわけですから、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"区としましては、国の取っている法律、施策にのっとった形で対応していると考えております。そのよしあしはあるかと思うのですけども、多くの自治体が、人口の流入ですとか定着化に努めるような中で、施策の中で実施していると聞いてあります。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問","question":"先ほどの私が申し上げました憲法２６条の趣旨からすると、無償化の範囲を広く取ることこそが２６条の趣旨にもかないます。品川区でも、このような趣旨を酌み取って無償化を行うべきだと思うのですけれども、もう一度お伺いいたしますが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"品川区におきましては、法の定めに従って執行していきたいと考えております。経済的に困窮のある方には、就学援助等々で対応していきたいと考えております。","id":"exchange-061"},{"speaker":"せお委員","kind":"質問","question":"令和２年度に比べて令和３年度は現時点で増えていますでしょうか。そして、マイスクールへのニーズの高まりがあり、五反田の指導員は増員してくださったようですが、令和２年度が終わってみての課題は何か尋ねました。","respondent":"矢部教育総合支援センター長","answer":"大体秋ぐらいから増えてきて、申請される状態が多いということを鑑みますと、昨年度並みには申請数がいくのではないかと考えています。今、オンラインで学習ができたりしておりますので、そのような様々なメディアも通しながら検討していく予定です。","id":"exchange-062"},{"speaker":"せお委員","kind":"質問","question":"こちらに参加されている保護者の方にもお話を伺いましたが、ホームスクーリングの現状を知ってもらいたいとおっしゃっていました。１、２年生へはどのような対応というか、支援をしているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"学年が上がってしまいますと、なかなか難しいというところもありますので、そのような背景も考えられます。本当に細かい一人ひとりの対応を保護者と連携をしながら進めていて、丁寧に１、２年生が楽しく学校に通えるような支援をしています。","id":"exchange-063"},{"speaker":"せお委員","kind":"質問・要望","question":"それに関連して、マイスクール五反田、浜川のような場所をどこかの学校内に設置してみるというのはいかがでしょうか。３点目、アンケート結果の３位でのオンラインに関連して、不登校のお子さんのタブレットの使用状況はいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"１人２人という人数が少なければ、校長が対応しているケースもありましたし、数時間ですけれども代わる代わる対応しているというのも聞いてあります。一人で進められないというお子さんも実際にいることは確かですので、それぞれに対応して、支援しています。","id":"exchange-064"},{"speaker":"せお委員","kind":"意見","question":"そして、子どもと一番長く接している保護者の職業は、１位、専業主婦・主夫、２位、パート・アルバイト・非常勤職員、３位、自営業となっています。所管が違う部分もあるかと思いますので、教育委員会としては、どのような保護者支援を現在は行っているのか説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"学校と家庭の連携事業というのがございまして、各支援員が対象のお子さんのところまで迎えに行ったり、相談相手となったりして話をしています。ですから、仕事をして外に出ていってしまう保護者については、そういう支援をしております。","id":"exchange-065"},{"speaker":"せお委員","kind":"質問・要望","question":"最後に要望だけお伝えすると、アンケートには、学校の環境があわなくて行かなくなったみたいな結果もあるのです。交流の今後についても説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"２点目、交流活動については大変大事だと認識しております。先日、特別支援学級のスポーツ大会ですとか学習発表会も、各学校からですけれども、オンラインで進めております。","id":"exchange-066"},{"speaker":"せお委員","kind":"質問・要望","question":"頻繁な授業を含めた交流を前提として、そちらも考えていただいて、支援学級のほうも新設していただきたいと要望します。それをすまいるスクールとも共有してほしいのですが、すまいるスクールと教育委員会との連携はどのように行っていますか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"特別支援の校内委員会、そちらのほうで共有して、管理職はもちろん認知して対応しているつもりです。すまいるスクールについては、今後とも連携して、特に特別に配慮を要するお子さんについては連携してまいりたいと思います。","id":"exchange-067"},{"speaker":"せお委員","kind":"質問・要望","question":"時間がないので、要望だけ。そのようなお子さんが入学される際には、成長の機会を奪うようなことがないよう、対応をお願いしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"西村委員","kind":"質問","question":"３７５ページ、３８３ページ、順不同で伺ってまいります。現在の取組と考えを説明するよう求めました。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"こちら、５年生、それから７年生につきまして、定期検診を実施しています。それから思春期の方に多いという特性がございまして、中学の女子については、０.６％と少し高い状況の結果が出てあります。 大きな行事を中心に全体的に指導ということはありますが、学校によっては、養護教諭から姿勢の指導をしている事例もあります。今後とも、大事なことだと思いますので、推進してまいりたいと考えています。","id":"exchange-069"},{"speaker":"西村委員","kind":"質問・要望","question":"この給食の時間を活用しまして、学校の食育を通した箸の指導を行えないでしょうか。もしくは行っていただいている取組がございましたら説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"箸の指導は市民科に位置づいてございまして、指導内容に入ってあります。もちろん箸の指導を普通の授業の時間だけではなく、箸が出たときの給食時、そのときにタイミングを計って、その都度指導して、定着に努めております。","id":"exchange-070"},{"speaker":"西村委員","kind":"質問","question":"家庭でも、なかなか教えていない。現在の取組とお考えを説明するよう求めました。","respondent":"矢部教育総合支援センター長","answer":"丁寧にならない場合もありますけれども、お子さんの様子を特に気にされている方については、そのような丁寧な対応で担任もお答えをしています。このようなツールも利用して、学校と家庭が連携できるように、進めているところです。","id":"exchange-071"},{"speaker":"西村委員","kind":"質問","question":"連絡帳をタブレットでやり取りをしている学校もあると伺っておりまして、働きながらとか、ぜひとも取組をお願いしたいと思います。その中には民間スクールのものもありますが、配布する際の基準について伺います。","respondent":"有馬庶務課長","answer":"学校からのそういった民間の案内のチラシの件ですけれども、大きく２つのルートがあるのではないかと考えております。最近はコロナ対策をどのように取っているか、最後には事業報告をもらうなど、そういったものを確認しながら後援をしているという状況があります。","id":"exchange-072"},{"speaker":"西村委員","kind":"質問・要望","question":"こちらは要望とします。次に、タブレットの導入状況について伺ってまいります。","respondent":"工藤指導課長","answer":"私ども教育委員会から各学校教員に向けて、令和３年５月には改訂版の学びのイノベーションという活用の手引の第２版を全教員に配布したところです。活用事例をまねることで取り組めるように、タブレットを活用しながら教育活動の質を高めていくよう、学校に対して指導しています。","id":"exchange-073"},{"speaker":"西村委員","kind":"質問","question":"オンライン配信の進捗について伺いたいのですが、濃厚接触者などをあわせると、１クラス１名は休んでいる時期もあったと学校現場より伺っております。第６波を見越しまして、また、コロナ禍において実際にオンライン配信を実施した学校がどれくらいあるのか説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"例えば土曜日の１時間だけ学校に子どもたちを登校させて、練習して進めておりますので、大丈夫だと思います。ただ、機器のことですので、通信環境等、トラブルは少し考えて、不安には思っております。","id":"exchange-074"},{"speaker":"西村委員","kind":"質問","question":"オンライン配信を望む家庭と望まない家庭もあると担当課より伺っておりまして、難しい部分だと思うのですが、よろしくお願いをしたいと思います。マイクロソフトのＦｏｒｍｓを利用した大変分かりやすいものですが、１年通して実施していただいた所感を伺います。","respondent":"勝亦学務課長","answer":"今、配備したｉＰａｄですとか、ご家庭のパソコンですとかスマホから欠席連絡ができるようになります。こちらにつきましては、今、全校で取り組んでおりまして、１１月には全ての学校で、いわゆるオンラインでの欠席連絡ができるようになる状況です。","id":"exchange-075"},{"speaker":"西村委員","kind":"質問","question":"なぜかとお伺いしますと、ファーストアクションが便利になり、効率的になったのかと考えています。一言お願いをいたします。","respondent":"勝亦学務課長","answer":"なかなかその対応も難しいということで、それから学校の対応ができるということで、メリットを感じてあります。丁寧な対応が必要な部分につきましては、お子様の状況ですとかご家庭の状況にも目を向けていくという形で対応を取ってあります。","id":"exchange-076"},{"speaker":"こんの委員","kind":"質問・要望","question":"３６３ページ、３８１ページ、学校生活における感染拡大防止対策経費からお尋ねいたします。こうした児童・生徒の日々の健康観察をしているということをお聞きしているわけですが、現状を教えていただきたいのと、参考までに説明を求めました。","respondent":"勝亦学務課長","answer":"は、咳とか喉の痛みがないか、そういったことをご報告いただく紙になってあります。こちらの方式につきまして、具体的には、教育委員会のほうにはお声等は届いていない状況です。","id":"exchange-077"},{"speaker":"こんの委員","kind":"確認","question":"プールの授業での体温の確認や、あるいはインフルエンザの季節のときの健康チェック、こうしたことまで活用しようということで進んでいるようです。こうした自治体も出ている中で、デジタルを使うという情報のやり取り、こうしたことについては教育委員会としてはどのようにお考えか尋ねました。","respondent":"勝亦学務課長","answer":"コロナに限らず、体温ですとかお子様の体調の情報を負担なく効率的に集めて、状況を確認していくというのは非常に効果的なことだと考えております。そういった意味では、様々な機器、方法を今後研究して、効率化等を考えていきたいと思います。","id":"exchange-078"},{"speaker":"こんの委員","kind":"質問・要望","question":"あらゆる媒体で、どういった形が効率よく情報をもらい、ぜひ研究をしてみてほしいと求めました。このアイコンを児童・生徒はどのように利用されているのか、実態が分かれば、そこら辺も説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"当初、デスクトップにアイコンをつけたときは、ざっと入ってきたのですけれども、今はもうほとんどございませんので、今、全部で１０件以下です。様々なツールが子どもたちのところにあるということが大事かと思って、今は捉えております。","id":"exchange-079"},{"speaker":"こんの委員","kind":"質問","question":"現まもるっちのシステムを令和５年度に新しいシステムに移行する予定となっていて、令和３年、その中でというそのときの話もありました。こうしたことについてまもるっちを活用するということに対しては、教育委員会としてはどのようにお考えなのか、ご所見を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"まもるっちの大きな機能は、やはりブザーの機能で危険を周りに知らせるということが第一義かと認識しております。まもるっちに限定しますと、今お話しのとおり、所管が違いますので、必要な意見を求められれば、私どもも積極的に関わってまいりたいと思っています。","id":"exchange-080"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で、次の質問に移ります。部活によっても違うと思いますけれども、その辺、分かれば説明を求めました。","respondent":"矢部教育総合支援センター長、勝亦学務課長","answer":"近隣区だけの移動になっておりますので、自費ではありますけれども、大きな額は動かなかったのかと認識しております。その前の自由に部活の遠征等ができたときにつきましては、やはり個人負担で負うことになっていたと認識しております。 関東大会以上の大会に出場する場合につきましては、支援を一部行っているようです。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"そこで、品川区はどのような計画を提出したのか、伺います。現状でも１０人以上を担当する教員がいるそうですが、既に１０人以上を担当している教員はいるのか、人数を伺います。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"これまで１０人に１人という割合でございましたけれども、１２人に１人に勘案して、教員の異動時期等を含めて勘案して提出したところです。いわゆる基準に従って、計画を提出したところです。 ご質問のもう一つ、１０人以上を１人の担任が持っている数です。現状は５校５名です。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問","question":"１２人に１人の計画で提出したということですけれども、そうすると、何人教員が減ることになるのでしょうか。それで、子ども１人当たりの指導時数というのは減るのかどうか、ここのところも伺いたいと思います。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"実際に１２人に１人で何人が減るのかというところはありますけれども、いわゆる児童、在籍する学級の子どもの数によってももちろん変わる。手元にその数値があるわけでございませんけれども、それで勘案しつつ… 特別支援教室のお子さんの授業の時間が減ってしまうのかというご質問かと思います。必要があって特別支援教室に適切だということで通っていますので、お子さん中心に、いる教員が指導するということになります。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"減る可能性で提出をしているということですけれども、東京都は、小・中あわせてですけれども、３４０人減らすという計画を求めているのです。教員を減らすのではなくて、増やすことこそ必要だと思いますが、いかがか尋ねました。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"やはり特別支援教育を充実していくためにも、そういった専門的な知見を持った教員が指導に当たるというのは非常に重要であると考えているところです。例えば特別支援教論の免許を持っている方であるとか、専門的な知見を高めて… 昨年度も、拠点校というのがありまして、そこから巡回していくのですけれども、３校行っていたところを全部２校にしましたので、比較的連携が取りやすく、巡回の教員も回りやすくなっていると我々は解釈しております。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ特別支援教室、ここもそういった支援がきちんとできるようにしていただきたいと思うのですが、特別支援教室に通う子どもの人数を伺います。そのうち３年以上指導を受けている子どもは何人いるのか、伺います。","respondent":"矢部教育総合支援センター長","answer":"現状、特別支援教室の利用者数は、小学校と義務教育学校前期課程のお子さんが６３０名です。中学校、義務教育学校後期課程のほうは、全体の２割くらいです。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"やはり教員の方たちも、６年通ってやっと落ち着いた子もいるということですとか、１年だけでは何もできなくなってしまうという声も寄せられています。期間を定めるべきではないと思いますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"１年間のスパンで一回見ていこうということで、指導の支援の仕方がよかったとかということを振り返るという一つの目安として示されたと考えています。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"必要であれば延ばせるということですが、そうすると、今までどおり６年通うことも可能なのか、伺います。","respondent":"矢部教育総合支援センター長","answer":"原則１年と言われていますので、そちらは教員も意識しなくてはいけないと考えております。先については、我々もこれからの取組ですので、注視してまいりたいと考えています。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"教育が狭まっていくということになりますので、教員も増やして、時数も増やしていくということでやっていってほしいと求めました。図書館のほうは時間がなくなってしまったので、充実を求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"西本委員","kind":"確認","question":"そこのところも、温かく見守るというのとまた違う心配事があるものですから、それの研修はどうなっているのでしょうかということ。その家庭環境に対してどう指導していくのですかという質問だったのです。","respondent":"有馬庶務課長、勝亦学務課長、工藤指導課長","answer":"旗振りですけれども、おっしゃるとおり、シルバー人材センターに委託をしておりまして、支給物品としては、旗とたすきを支給しております。業務につく方も… 今後ですけれども、現状、検査で出ていないことですから、一定の効果は認められたのかと考えています。現時点では、ある程度終了も視野に入れて… その中でいえば、昨年度の実績でも、オンラインであっても顔が見えたということでの効果というのも得られたところがあります。","id":"exchange-089"},{"speaker":"西本委員","kind":"確認","question":"そういう意味での教育格差が出てくるのではないのですかということを言っているので、そのお考えをお聞きします。それが一つの出欠確認でも分かるのです。","respondent":"工藤指導課長","answer":"低学年児童が１人で使えるという操作を目指して学校でも指導を丁寧に行ってありますし、そういった差が出ないようにしっかり行っているところです。そういった意味では、これからも様々な活用を図ってまいりたいと考えています。","id":"exchange-090"},{"speaker":"吉田委員","kind":"質問","question":"それについて２点伺います。それについて伺います。","respondent":"勝亦学務課長","answer":"そういったものを見まして、必要な状況が発生いたしましたら、必要な検査は行っていく必要があると考えています。こちらは食中毒の検査に使ってありますので、有償無償問わず、ご提供というのは考えてございません。","id":"exchange-091"},{"speaker":"吉田委員","kind":"質問・要望","question":"では、社会情勢などが必要と思われる状況になったらとおっしゃいましたけれども、それは例えばどのような状況のことを示しておられるのか伺います。それを提供していただきたいと思うのですが、ぜひこれは検討していただきたいのですが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"例えば、そういった放射性物質が出るような事象がまた発生したようなときは、必要に応じて実施する必要があるのかと考えています。食材の提供ですけれども、基本的にご提供することを想定して準備しているものでございませんので、提供については差し控えたいと考えております。","id":"exchange-092"},{"speaker":"吉田委員","kind":"質問","question":"社会情勢なのですけれども、生活者ネットワークとしては、例えば、汚染水を海洋で放出してしまうという事態もそれに当たるのではないかと思います。それは風評被害を払拭するためにも、きちんと検査をしていくべきだと考えますが、見解を伺います。","respondent":"勝亦学務課長","answer":"そういったものがかかっているので、まずは、流通しているものは安全という前提の認識があります。ＡＬＰＳ処理水につきましても、基本的には、環境影響のない水ということで認識しています。","id":"exchange-093"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、３７５ページ、学校ＩＣＴ活用経費、３６５ページのルネサンス推進事業費の中から、市民科授業、プログラミング教育についてお伺いします。ＩＣＴ指導員はどのようなサポートをしていったのか、あわせて示すよう求めました。","respondent":"矢部教育総合支援センター長、勝亦学務課長","answer":"３密を避けることや咳エチケット、手洗いの徹底というところを中心に進めて、感染防止対策に努めてきたものです。そのようなことでここまで乗り切ってまいりました。 ＩＣＴサポートの部分について、私からお答えいたします。児童・生徒への機器の操作支援、教員への支援、技術的な支援。","id":"exchange-094"},{"speaker":"湯澤委員","kind":"質問","question":"現在はいかがでしょうか。防止対策とともにお知らせほしいと求めました。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"オンライン授業についても同様で、すぐに対応できるように準備している状況です。そういった危険はありますので、そういったことには、実施していく中で注意や配慮していくということが必要かと考えています。 教育委員会としましては、９月２２日付でコロナ不安でお休みしているお子さんの数を取りまして、１１０人という数字が出ました。本当にコロナで不安の、心のケースもありますので、正確な数値は今持ってございません。","id":"exchange-095"},{"speaker":"湯澤委員","kind":"質問・要望","question":"２０２４年度の教科書の改訂にあわせて、それにあわせて、教育用のＡＲやＶＲ市場も活発になってきております。ＶＲやＡＲを積極的に活用し、子どもたちが早い段階で楽しみながら新技術による学習ツールに触れることを要望しますが、ご見解を示すよう求めました。","respondent":"工藤指導課長","answer":"委員ご指摘いただいているバーチャルリアリティを活用した教材などというのが、現状、開発が進んできているというのは認識しています。今後、ＶＲやＡＲの活用につきましては、そういったソフトの開発などを注視しながら、研究を重ねていきたいと考えています。","id":"exchange-096"},{"speaker":"湯澤委員","kind":"意見","question":"次に、市民科の授業についてお尋ねいたします。そういったところもあわせてお知らせほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"委員ご指摘の平成１８年度から実施している、本区独自の教科です。市民科の目標は２点ございまして、１点は、倫理感や道徳感を持ち、自分自身について考え、常に自己変革を図っていく資質と能力を育てること。","id":"exchange-097"},{"speaker":"湯澤委員","kind":"提案","question":"そこで、市民科においてＳＤＧｓの実践として具体的にどういったことを行っているのか。一般質問でも提案をさせていただきましたが、必修科目になったプログラミング授業、ご見解をお知らせくださいとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"ブザーが鳴るというような、実際にエレベーターでも使われているような事例を取り上げて学習を進めています。プログラミング自体の勉強というよりは、繰り返し試行錯誤して論理的思考を育てるというのを目標に進めております。","id":"exchange-098"},{"speaker":"湯澤委員","kind":"質問・要望","question":"そういったことが身につくと思いますので、ＳＤＧｓ教育は様々な学習の中に取り入れていただきながらやっていただきたいというふうに要望いたします。親向けのテキストや、子どもと共同で行いながら体験できるプログラムや授業風景の配信を、コロナ禍にかかわらず定期的に行ってはいかがか尋ねました。","respondent":"工藤指導課長","answer":"海外旅行を一緒に体験するようなことを、保護者もあわせて児童と一緒にやるということを学校で企画しているということのお話も聞いたりしています。授業風景の公開なども、各校、ホームページなどを活用して進めていければと考えているところです。","id":"exchange-099"},{"speaker":"たけうち委員","kind":"質問・要望","question":"３６３ページの生徒指導対策等経費、３７９ページの通学安全確認業務等委託について伺います。ヤングケアラーについて２定で質問させていただきましたが、区では既にいろいろこういったケースも対応してきたと伺っております。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"学校におきましては、そのまま子ども家庭支援センターに連絡することもあるかもしれませんが、私たち教育総合支援センターとしては。１つの事例は、送り迎えをしていたお子さんについて… 午後も時間的には一、二時間をやっているのかと思うのですが、１日５時間以内で各学校にお願いをしています。","id":"exchange-100"},{"speaker":"たけうち委員","kind":"質問","question":"それは先生とか、そういったところに共有されるということでよろしいのかどうか、その辺を教えてください。うまく回せていけないのかと思うのですけれども、どうか尋ねました。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"今年度もできる範囲でやっていくというふうに認識しておりますが、今のところは昨年どおりと認識しております。もちろん今の例もそうですけれども、特に安全や健康に関わることは、すぐに管理職も含めて、連絡はその日にしています。 旗振りもそうですし、巡回となると、周りも歩いたりするということで、余計に大変かなと考えています。例えば３０分、具体的な指示を出しているものではありませんが、ぜひ休憩も取れるような形で検討させていただきたいと考えています。","id":"exchange-101"},{"speaker":"たけうち委員","kind":"質問・要望","question":"逆に危ないのではないかと本当に思ってしまいますので、そこはぜひお願いしたいと思いますので、よろしくお願いします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはりマイク等の使用で早急な改善をしていただきたいと思うのですけれども、現在どのような検討がされているのか伺います。伺います。","respondent":"有馬庶務課長","answer":"条件も少し変わってくるところはあると思いますので、その辺は教育委員会として何かできるかというところの検討は行っているという状況です。","id":"exchange-103"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"資料の配布、そして、持ち帰り、可能にしていただきたいと改めて強く求めたいと思います。限界があると思うのですけれども、改善が必要だと思いますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"そこを変えるというのは、我々としてはこれは国がやることだと考えていますので、できる限り国の方針に基づいて進めてまいりたいと思います。暴力、安全なども全て包括してと理解しておりますので、そういった一つ一つをやっていくことが性教育につながっていくと理解しています。","id":"exchange-104"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうした包括的性教育は、本当に将来にわたって豊かで楽しい性認識をつくり出し、人とのコミュニケーション、そして、先ほどからも議論になっています性暴力の抑止、こういったものにも大きく力を発揮するものだと思いますので、抜本的な改善をぜひ国や都にも求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問","question":"３年の動きと、今後の見通しについてお尋ねします。これによって、現行の９年生への影響、そして、９年生へはどのような指導をされるのか尋ねました。","respondent":"勝亦学務課長、矢部教育総合支援センター長、有馬庶務課長、工藤指導課長","answer":"全ての学校におきまして、朝礼等については、少なくとも１回はオンラインで実施をしています。保護者面談におきまして… それがどうだったかというところが、この特別支援教育室システムの一番大事なところ、委員のおっしゃるとおりだと考えております。","id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"老朽化も進んでいますので、いわゆる改築に乗せていって、検討をぜひ、地域の方々も求めており、期待も高いのでよろしくお願いします。ですから、特に２学期は私立高校への進路指導とかを決めていく時期でありますので、その点について男子への影響をお尋ねします。","respondent":"工藤指導課長","answer":"高等学校入試の制度の変更によって、これまで行っていた緩和実施校が４２校ございましたので、それらの結果からすると。各学校については、これまでも行っておりますけれども、より丁寧に指導を行うよう指導を徹底してまいります。","id":"exchange-107"},{"speaker":"渡辺委員","kind":"質問","question":"３７５ページ、学校ＩＣＴ活用経費で、本日も様々出ていますが、ネットリテラシーの点から伺おうと思います。直近のスマホ保持率というのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"中学生につきましても、かなりの割合で所有しているということは認識しております。時間、これは学校でも市民科で取り上げてありますので、その推進を進めていきたいと考えています。","id":"exchange-108"},{"speaker":"渡辺委員","kind":"質問","question":"これは正解がある話ではないような気がしながら伺うのですが、どれからというところが、ここは曖昧で仕方ないと思っています。そんなことから、スマホやＳＮＳの安全教室のような趣旨のもの、この必要性を伺いたいと思います。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"情報モラルにつきまして、今の事例もありましたとおり、様々な場所でそれぞれの機関でいろいろな取組が行われているのは認識しています。いじめに関しまして、ＳＮＳの活用については、必ず内容として出てきますので… これも２時間が正しいかどうかというのはその都度議論が必要だというところ、教員がこういった指導に関わりながら行うところだと認識しています。","id":"exchange-109"},{"speaker":"渡辺委員","kind":"質問・要望","question":"防犯効果の評価の高いまもるっち政策しかり、教育の品川の児童・生徒を守る施策として、ぜひとも検討ほしいと求めました。ご答弁をお願いします。","respondent":"矢部教育総合支援センター長","answer":"以前、地域の皆さんで協力していただいて携帯電話しながわアクションというのをやっていただきまして、すばらしいリーフレットも出ております。","id":"exchange-110"},{"speaker":"大倉委員","kind":"質問・要望","question":"費用の面でどうなっているのでしょうかということと、１名ずつの配置にならない、課題等も教えてほしいと求めました。もう１点聞いてしまいますが、部活動指導員が導入がされて数年経って、評価というところでは今どのようにされているか説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"なかなかいじめや、子どもたちとの関係性、そういったものを大事に対応する指導員にやっていただきたいというのが学校の願いですので。２方向で、ぜひよい人材がいらっしゃいましたら、活用していきたいです。","id":"exchange-111"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ１名分ずつ確保していただきたいというところと、ぜひお願いしたいと思いますので、その点を教えてください。天気に左右されないというメリットもあるのかと思いますので、その辺はどうでしょうかということで、ご答弁ほしいと求めました。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"１５校、中学校がありますので、そちらで公平に配置したいということが大きくあります。ただ、いい人材をぜひ部活動の維持のために確保したいという思いは私もありますので、今後も柔軟に検討していきたいと考えています。 委員から提案のあった部分につきましても、費用と効果等を検討させていただいて、有効策かどうかということもあわせて検討していきたいと考えています。","id":"exchange-112"},{"speaker":"須貝委員","kind":"質問","question":"私、まず、３６０ページ、教育指導費全般についてお聞きしたいと思います。要は、教師の負担軽減につなげるというシステムができたようですが、もし知っていれば、説明を求めました。","respondent":"工藤指導課長","answer":"委員ご指摘のデジタル採点システムについて、ご紹介の県が所管する県立高校に導入するというのは、報道によって私も認識しています。そういった意味では、区内では採点業務については、スクールサポートスタッフに依頼をして行っているという事例はあります。","id":"exchange-113"},{"speaker":"須貝委員","kind":"質問","question":"同じ人間ですから、性別関係なく学力レベルで合否を決めるべきで、男女で関係なく実力で平等に選ばれるべきだと私は思います。そして、このことを中学３年の受験生や保護者に毎年きちんと伝えていたのかどうかも説明を求めました。","respondent":"工藤指導課長","answer":"本制度につきまして、委員ご指摘のように、男女別の定員制が令和４年２月実施から緩和されるところです。実施要綱等が定まった段階で、保護者に対しては進路説明会などを開き、丁寧に説明をするところです。","id":"exchange-114"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり品川区としたら、せっかく教育改革をやっているなら、できれば、Ａ・Ｂの方が来てほしい。その点についてご見解を説明するよう求めました。","respondent":"工藤指導課長","answer":"入学者選抜検討委員会という会が、こういった要望等については、そういったところで改善要求はしています。配置のあった教員については、品川区の教育の充実に向けて、研修も含めながら指導を充実させていくということに励んでいるところです。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問・要望","question":"我々は今改革しているのだから、いい教員が欲しいですという意気込みで私はやってほしいと求めました。そこはしっかりやってほしいのですが、もう一回ご見解を説明するよう求めました。","respondent":"工藤指導課長","answer":"現状は６校と１校、品川区を希望するということで、これは都に強く要望して認められているところです。異動２年目であって、義務教育学校公募などで戻ってくるということも想定しながら、私どもは品川区の教育の充実に励んでいるところです。","id":"exchange-116"},{"speaker":"須貝委員","kind":"質問","question":"その中で座っているのですか。説明を求めました。","respondent":"工藤指導課長","answer":"つまり、その子が課題としていることを定着させる。そういった意味では、より基礎・基本の定着を図れるように、今回配布しているタブレットも有効に活用を始めているところです。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問・要望","question":"教育ユーチューバー、葉一さんの授業動画、これを活用できないのでしょうか。１人でも取り残さない教育、そちらのタブレットのあれですが、そこには説明も何もないではないか尋ねました。","respondent":"工藤指導課長","answer":"ご指摘のユーチューバーの動画等があるというのは認識していますが、そういったコンテンツがあるということも認識しています。ただ、現在そういったユーチューブの動画を公教育で活用することは考えてございません。","id":"exchange-118"},{"speaker":"中塚委員","kind":"質問","question":"３６３ページの生徒指導対策費に関連して、中学校の校則について、髪型と下着チェックを伺いたいと思います。こんな連帯責任の校則は理不尽だと思いますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"小学生であれば１年生から、中学生であれば９年生まで、校則の中にそれが盛り込まれていると考えられると思います。これまでの経緯でできてきたものだということは繰り返し述べてまいりましたので、そのような背景から、なかなか判断できないものと考えております。","id":"exchange-119"},{"speaker":"中塚委員","kind":"質問","question":"休み時間も常に結ぶように指導されると伺いました。つまり、常に結ぶという指導は、私は合理的ではないと思いますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"ただ、そんなの分かっているというやり取りであれば、最初から決まっているほうが子どもたちにとっては負担なく授業に進めるのかと考えています。","id":"exchange-120"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜ常に結ぶことを求めるのか。場面場面で状況を変えることができることを認めてほしいし、そうあってほしいと思いますが、改めていかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"授業も同じです。その中で、このような望ましい服装ですとか髪型について、学校が決めていると認識しています。","id":"exchange-121"},{"speaker":"中塚委員","kind":"質問・要望","question":"中学生の下着をワイシャツの上から目視で校則にあっているかどうかを確認していることを聞くと、やめてほしい、嫌だと話しておりました。質問の趣旨を伝えて了承も得た上でもう少し聞いたのですけども、なぜやめてほしいのか、見せるためにつけていないと話しておりました。","respondent":"矢部教育総合支援センター長","answer":"ただ、目視とかチェックという言葉が、少し私どもと認識が違うのかと感じています。そういったことを我々は見ているという意味の内容です。","id":"exchange-122"},{"speaker":"中塚委員","kind":"質問・要望","question":"私がチェックと言ったのは、見て確認して、校則と異なれば指導しているということですから、これはチェックそのものです。都教委と同じく、下着の色の指定やそれに関する指導は行わないと各中学校に通知すべきだと思いますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"校則は、委員もご存じのとおり、学校で定めるものですので、現時点では、学校に、ならぬということは伝えるつもりはございません。ただ、これまでどおり、校則の見直しのことは働きかけていきますし、その方法についても生活指導主任会等で周知してまいりたいと考えています。","id":"exchange-123"},{"speaker":"中塚委員","kind":"意見","question":"この考えは区教委と同じなのか。先ほどからの説明だと、違うということになりますが、何がどう違うのか、ご説明くださいとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"これまでもお伝えしたとおり、国の生徒指導提要の内容に当たっているものについては、本区としても同じです。これはあくまで都立校の進めることだということで、表現とか細かい内容について、我々が意見するところではないと考えています。","id":"exchange-124"},{"speaker":"中塚委員","kind":"質問","question":"つまり、そう考えているということです。教育委員会は、同じなのか、違うのか、改めて伺います。","respondent":"矢部教育総合支援センター長","answer":"ここは例示ですし、主に高校生が多い都立ですので、小・中学生を所管している我々としては、全く同じ意見はございません。","id":"exchange-125"},{"speaker":"中塚委員","kind":"質問","question":"中学生は違うと。下着のチェックにおいて、高校生と中学生で何が違うのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"発達段階は大きなことだと考えています。本区でいえば９年生でどういう姿を見せたいかというのは、一つそこが区切りだと考えておりますので、私たちは考えに変更はございません。","id":"exchange-126"},{"speaker":"中塚委員","kind":"質問・要望","question":"通知も手元にあって、私が質問をしているわけですから、区教委は自ら考えを示すべきだと思います。そして、それが指導でどう変わってくるのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"中学生の７年と、チェックという認識がやはり私たちと違っていまして、目立った髪型とか服装になれば声をかけていくという認識の中で指導しています。","id":"exchange-127"},{"speaker":"中塚委員","kind":"質問・要望","question":"ですから、校則で下着の指定をやめれば、確認そのものがなくなってくると私は思いますが、いかがでしょうか。理不尽な校則の見直しを強く進めてほしいと求めましたが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"私の手元にある学校だよりには、校則を見直しますと、はっきり学校だよりの前面に書いてあるところがあります。校則ですけれども、別なことも含めて、いろいろなことで協議したり意見を聞いてつくり上げるということはとても大事だと感じています。","id":"exchange-128"},{"speaker":"鈴木（博）委員","kind":"質問","question":"がん教育についてお尋ねいたします。ＨＰＶワクチンの正しい勉強、学習課題そのものだと理解いたしますが、教育委員会の現在の見解をお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"学校における学習指導の内容につきましては、学習指導要領に基づいて行われてあります。薬物乱用などの行為が健康を損なう原因であるということなどは扱いますが、ＨＰＶワクチン接種については、指導事項としては位置づいておりません。","id":"exchange-129"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"リーフレットの充実のほか、学校における養護教諭などにより子どもに教える必要があるとし、学校との連携を強く求めたと報道されています。現在、感染症とがんについては、どのような授業が行われているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"中学校、義務教育学校の後期課程におきましては、令和２年度より全ての中学校でがんの専門医による指導を実施しております。今後も国の動向に注視しながら、保健所等とも連携して、正しい情報をつかんでまいりたいと思います。","id":"exchange-130"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２０２０年１２月に、ＨＰＶワクチンが男性にも適用が拡大されました。ぜひ教育委員会からも、男児への、男児の保護者へのＨＰＶワクチンの情報提供をお願いしたいと思いますが、教育委員会のお考えはいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"厚生労働省が配布しておりますＨＰＶワクチンのパンフレットは、女子用と認識しております。男子のほうは任意の接種であることからも、現在は男子への指導はしておりません。","id":"exchange-131"},{"speaker":"鈴木（博）委員","kind":"質問","question":"自宅待機となった子どもへの学校からの支援は、どのように行われているのでしょうか。小・中学生の新型コロナウイルス検査陽性者およびその家族に対する、在籍クラスの他の生徒、保護者へはどのような働きかけが行われたのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"１人１台端末も活用しながら、授業の様子を配信するなど、各校が工夫して個別に対応しているところです。日頃より陽性者の差別や偏見を行わないよう、児童・生徒には指導しておりますし、ガイドラインにも記載しています。","id":"exchange-132"},{"speaker":"鈴木（博）委員","kind":"質問","question":"保護者の積極的なワクチン接種が必要と思われますが、保護者への学校からのワクチンの情報提供はどのように行っているのでしょうか。ご説明をお願いいたします。","respondent":"有馬庶務課長、勝亦学務課長","answer":"その後、東京都が集計した９月２２日に、これは公立高校全体ということで出てきておりますが、２回目の接種が終わった者が８３％と出ております。品川区の場合は、９月１日の段階で約８割ですので… 医学的、専門的な内容も含むため、教育委員会から一律に接種の勧奨をすることは難しいと考えています。","id":"exchange-133"},{"speaker":"鈴木（博）委員","kind":"質問","question":"さらに、１８歳以下の自殺は、学校の長期休業明けの時期に増加する傾向があると言われております。繰り返しの質問になるかもしれませんが、教育委員会としてはどのようなことに力を入れて取り組まれているのか、ご説明をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"この夏休みには、全中学校と義務教育学校の後期課程におきまして、カウンセラーの面談日を１日設けまして、子どもたちの心のケアに努めました。さらにこの９月、全教員向けの講演会を行いまして、児童・生徒の対応について理解を深めることができました。","id":"exchange-134"},{"speaker":"鈴木（博）委員","kind":"意見","question":"そのための重要な取組が、学校におけるメディアリテラシー教育だと考えます。現在の品川区のメディアリテラシー教育の現状について、再度、現段階でのご説明をお願いいたしますとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"実感を持って指導を受けている、また、活用していると捉えております。著作権に配慮した表現方法のあり方などを事例に、情報発信者の意図を読み取り、自分の意見を発信できる力を育成しています。","id":"exchange-135"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"次に、国語の学習について最後に伺います。現在の理科とか社会の教科書が、ぜひ国語を意識した授業を行うように要望させていただきたいと思うのですが、一言お願いします。","respondent":"矢部教育総合支援センター長","answer":"各教科におきましても国語の指導は大変重要だと考えております。今後とも国語を意識して教科指導が充実するよう、推進してまいります。","id":"exchange-136"},{"speaker":"塚本委員","kind":"質問・要望","question":"３６７ページ、それから３６９ページ、介助員等委託についてお伺いしたいと思います。中学校２校ということになっておりますけれども、まず、大体どれぐらいの時期になるということがあれば教えてほしいと求めました。","respondent":"有馬庶務課長","answer":"それで、こちらのほうは、ある程度、１７ということで限定がされていますので、ＬＥＤ化は数年で全部終わるという見込みになっております。","id":"exchange-137"},{"speaker":"塚本委員","kind":"質問","question":"学校で野球とか、サッカーとか校庭開放で実施しているわけですけれども、この明るさに違いが少しあるというお声を時々伺います。午後６時ぐらいまでやると、夜間開放していない学校というのは、どういった理由に基づいて開放していないのかということをお伺いしたいと思います。","respondent":"有馬庶務課長","answer":"校庭の夜間照明ですけれども、一番最初に昭和５７年頃にモデル的につけたというのがあります。最終的に平成１７年に完成して、ある程度中学校区に１校ぐらい、学校によって差ができているです。","id":"exchange-138"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうしますと、今、夜間開放というか、照明があまりしっかり明るくついていないところというのは、学校等から要望なり、そういうことが出てくれば、地域も関係してくると思いますけれども、一定程度つけていこうということは、特段の障害はないという認識でよろしいのか尋ねました。","respondent":"有馬庶務課長","answer":"夜間照明は、恐らくその構想を立てて平成１７年度に終了しておりますので、一旦はこれで終了しているものだと捉えております。騒音、当時はそういうこともあってこの１７校を選定してきたのではないかと思いますけれども、そういったことは検討していくことになるかと思います。","id":"exchange-139"},{"speaker":"塚本委員","kind":"質問","question":"先ほど湯澤委員からも質疑が若干ありましたけれども、もう少し具体的に、詳細にお聞きしたいと思います。最初に、決算書では５６５万５,６７３円ということで決算されていますが、主にどういったことに支出されたのか、説明するよう求めました。","respondent":"矢部教育総合支援センター長","answer":"プログラミング教育は、まず、導入が昨年度ですので、その前から少しずつ触れるということで、ロボットを借りております。何度も試行錯誤する、そういう意味で、なかなか好評の事業です。","id":"exchange-140"},{"speaker":"塚本委員","kind":"質問・要望","question":"現状、どういったところというか、どういった単元でプログラミング学習というのが組み込まれているのか。できるだけ詳細に教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"５年生の算数では、一々描くよりは、何度も試行錯誤できて挑戦できるという学習になりやすいです。例えば、問題解決の連続なのですけども、そういった活動はこれまでも中学生では実施してまいりました。","id":"exchange-141"},{"speaker":"塚本委員","kind":"質問・要望","question":"教えていただきたいのは、そういうことがそもそも可能なのかというかということも含めて、習熟度というのをどうやって見ているのかというところを説明するよう求めました。","respondent":"矢部教育総合支援センター長","answer":"４分の１程度で、実施した中身を、論理的思考を見るようなテストになります。できた作品ですとか、そのときに動いた動作、機械の動作などを見て評価するということが行われております。","id":"exchange-142"},{"speaker":"塚本委員","kind":"質問・要望","question":"論理的思考というのをしっかり身につけていくということはとても重要な教育的要素と捉えておりまして、今後とも取組を進めてほしいと求めました。介助員の充足度といいますか、そういったところはどのような状況にあると捉えているか、説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"年に２回、特別支援教室とか特別支援学級がいいのではないかということも含めて、人が配置されたほうがいいのではないかという申請を受けます。我々のほうも予算を増額して対応していますが、見方によっては、もう１時間いてくれたらいいとかということはあるかと思っています。","id":"exchange-143"},{"speaker":"塚本委員","kind":"質問・要望","question":"つく・つかない、そういったところでの説明がなかなか我々も難しいところがあるのですけれども、単純にニーズ的に無理なのだと。そういったもの、つく・つかない等の説明についてしっかりと実施していただきたいという思いがありますけれども、ご答弁をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"規定はありますので、学校にもきちんと周知できるように、改めて説明してまいりたいと思います。","id":"exchange-144"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう一個は、よく分からないのですが、地域での教育というか、校外学習なのかよく分からないのですが、それについてお伺いしたいと思います。必ずこの部分については何か実施をしていただきたいと思っておりまして、計画とかがあればお聞かせいただきたいというのを最初の質問にしておきます。","respondent":"有馬庶務課長","answer":"８年生が行けない状況になって、８年生に対しては東京近郊でどこか自然体験みたいなものができるのではないかということで、依頼をしています。いずれにしても、何らかの形で行事は進めていきたいと考えております。","id":"exchange-145"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"積極的に子どもたちを参加させろというようなのを、ぜひここは教育委員会から言ってもらいたいと思って、こういう質問をしています。そこについての考え方を説明するよう求めました。","respondent":"中島教育長","answer":"そういったものに対し支援していきたいと思いますし、２学期からは今、そういったところでも具体的にお願いをしていきたいと考えています。ここでいただいたいろいろな意見も含めて、考えていきたいと思います。","id":"exchange-146"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701177?Template=document&Id=1510#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":118228,"voices":353}},{"id":"r03-20211015-4","meetingId":"r03-c-settlement","date":"2021年10月15日","dateIso":"2021-10-15","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を115件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"小芝副委員長","kind":"質問・要望","question":"途上国を含む全ての参加国と地域に、２０２０年以降の温室効果ガスの削減・抑制目標を定めることを求めました。目標達成のためには、自然再生可能エネルギーの導入をより一層促進していくべきと考えますが、まず、品川区の見解をお聞かせ願います。","respondent":"中村都市環境部長","answer":"あるいは太陽光パネルの設置、地下熱利用の可能性、こういったことも検討してまいりたいと思います。省エネ機器の設置補助といったものを通じまして、他の自治体とともに、連携しながら進めてまいりたいと考えております。","id":"exchange-001"},{"speaker":"小芝副委員長","kind":"質問・要望","question":"といいますのは、来年５月、戸越公園に環境学習交流施設エコルとごしが開設されます。そこでお聞きしますが、このエコルとごしを通じました区の環境政策への思いをお聞かせほしいと求めました。","respondent":"中村都市環境部長","answer":"施設を通じまして、今後も引き続き、自主的・主体的に環境保全活動を実施してもらうことを推進していくということを考えております。環境事業の拠点としての役割を果たして、環境事業の着実な推進を図ってまいりたいと考えております。","id":"exchange-002"},{"speaker":"小芝副委員長","kind":"質問","question":"一般廃棄物処理基本計画の中に書かれております、子どもたちを対象とした環境教育の項目が物足りないのではないのかといった指摘がありました。今現在におけます具体的な目標、指針などがあれば、お聞かせ願いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"毎年、小学生によるリサイクルポスター展、それから、スケルトンの清掃自動車による環境学習などを行ってきているところです。開設に向けて準備を進めているエコルとごしでは、環境課で推進する環境学習の連携も踏まえて、検討をしてまいります。","id":"exchange-003"},{"speaker":"小芝副委員長","kind":"質問・要望","question":"今年の３月に閣議決定され、６月に法案が可決成立をしました、プラスチックごみの分別収集と再商品化に向けた取組みを求めている内容でもあります。できれば環境基本計画に盛り込むべきと考えますが、見解を教えてほしいと求めました。","respondent":"中村都市環境部長、品川品川区清掃事務所長","answer":"世界的な課題であると、また近年、非常に関心の高まっている事柄であると認識をしております。環境基本計画の見直しの際に、東京都や他区の取組みを踏まえまして、しっかりと検討してまいります。 プラスチックの分別収集に関する課題です。回収車両および人員体制、委託先など、多岐にわたる調整が必要であると考えております。","id":"exchange-004"},{"speaker":"小芝副委員長","kind":"質問","question":"今後のプラスチックごみの収集促進に備え、清掃部門の雇用拡大といったものを検討するべきとも考えますが、見解を教えてもらいたいと思います。なかなか現実問題はかなり難しいところでもあるかと思いますが、積極的なご答弁をお願いいたします。","respondent":"品川品川区清掃事務所長","answer":"中間処理について、人員による容器包装と新たなプラスチックとの分別が必要になるのかとか、そういった部分を考えていく必要があると考えています。区としても、区職員で対応するのか、委託で対応するのかなど、今後、検討してまいります。","id":"exchange-005"},{"speaker":"小芝副委員長","kind":"質問・要望","question":"今後、品川区は率先して連携していくべきと私は考えますが、ぜひその見解をお聞かせ願いたいと思います。トップセールスを行っていく必要が出てくるときもあるかもしれませんが、その辺も含めて、ご見解をお聞かせ願いたいと思います。","respondent":"中村都市環境部長","answer":"地球温暖化といった環境課題への対応ですけれども、区民と事業者と区が一体となって取組みを行うということが、大変重要だと考えております。環境に対して積極的な姿勢で対応している事業者ですので、前向きに区として連携を進めてまいりたいと、このように考えます。","id":"exchange-006"},{"speaker":"小芝副委員長","kind":"質問・要望","question":"時代の転換点に立つ品川区の環境政策をより一層進めていただきたいという思いで、環境政策、環境に特化して質問をさせていただきました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"提案","question":"そして、それに流れた形での品川区でのスポーツコミッション設立の提案、この点で伺ってまいります。あるいは３競技応援等に関する認識度や意識の変遷をどのように把握されているか、説明を求めました。","respondent":"山崎文化スポーツ振興部長","answer":"区は、区応援競技３競技を中心とした競技啓発、区民の皆様が主役の機運醸成事業を実施してまいりました。行政、それから、まさにオール品川の体制を構築することができた結果であると認識するところです。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問","question":"これは何を伺いたいかというと、しな助に関わることなのですが、監査委員の各会計決算審査意見書がせんだって配付されました。今後の展開、活用の仕方を伺えればと思います。","respondent":"山崎文化スポーツ振興部長","answer":"聖火リレーなどで活躍をお願いする予定でしたが、残念ながら、そうした期間中の活動につきましてはほとんどできませんでした。東京２０２０大会を目的としたしな助の皆様につきましては、ワークショップの実施などを通じまして、促しなどをしっかり考えてあります。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問","question":"まだまだ検証途中かと思いますが、現時点での、検証を伺えればと思います。どのように生かしていくのか示すよう求めました。","respondent":"米田教育次長","answer":"今般のコロナ禍におきましても、体験や講演をオンラインで実施するなど、５つのねらいを達成できていると認識しています。今後は、各学校のこれまでの取組み実績を、オリンピック・パラリンピック教育のレガシーとして継続、発展できるように努めてまいります。","id":"exchange-010"},{"speaker":"渡辺委員","kind":"確認","question":"品川区もいち早く同様の理念で展開されたと思いますが、そこの確認と、主な施策があれば教えてください。気になった項目で伺ってまいります。","respondent":"山崎文化スポーツ振興部長","answer":"これはオリンピック・パラリンピックなどを契機にして行い始めたものですが、今後、新たな視点で取り組んでまいりたいと考えております。スポーツの力による交流やにぎわいの創出は、もちろん身近な商店街などと連携したスポーツ大会の実施でありますとか、シティマラソンなども。","id":"exchange-011"},{"speaker":"渡辺委員","kind":"提案","question":"品川らしさをふんだんに取り入れた事業実施を願い、伺ってまいります。まさに機運が高まっている中で、行政のリーダーシップを含めたスポーツコミッションへの見解を伺いたいと思いますとの意見を述べました。","respondent":"山崎文化スポーツ振興部長","answer":"それから、スポーツ協会に加盟している団体等の、区民の皆さんによる区民の自主的な活動というところに根づいてあります。区としてのハブになるつなぎ役といいますか、行政ならではのそうした特性を生かした支援などを研究してまいる必要があると、捉えているところです。","id":"exchange-012"},{"speaker":"渡辺委員","kind":"質問","question":"質疑のほうは、スポーツコミッションと関わりの深い項目を、個別で伺ってまいりたいと思います。今、少し触れていただいたのですが、抱負を伺いたいことが１つ。","respondent":"山崎文化スポーツ振興部長","answer":"食事、観光を楽しんでいただけるような流れといいますか、仕掛けをつくってまいりたいと考えているところです。恒久施設としての大井ホッケー競技場の流れがありますので、こうした動きにも積極的に関わり、交流などを図ってまいりたいと考えるところです。","id":"exchange-013"},{"speaker":"渡辺委員","kind":"質問","question":"続きまして、また、スポーツコミッションに本来関われたらいいなという点で、何点か伺います。７月に品川区手話言語条例も制定されて、あるいは展開の中で力を発揮されたいと思いますが、その辺の見解を示すよう求めました。","respondent":"山崎文化スポーツ振興部長","answer":"新たな様々なツールの１つとしての可能性など、今後、区としましても活用研究を行っていく必要があるかと思っているところです。こうした東京都の動向に注視しつつ、区としましても招致に協力してまいる考えです。","id":"exchange-014"},{"speaker":"渡辺委員","kind":"提案","question":"款別の質疑でも自民党より提案要望いたしました。その１つの例で言えば、やはり都立みなとが丘ふ頭公園は、ぜひ品川区が関わりを持って、区民利用の場に広げていただきたいと思っていますとの意見を述べました。","respondent":"山崎文化スポーツ振興部長","answer":"区としましては、初心者キャンプ教室、市町村交流を行っている山北町でのキャンプ場でのファミリーキャンプなどを行っているところです。現在、来年度に向けて改めて充実した事業の実施というところで、こうした分野にも努めてまいりたいと考えるところです。","id":"exchange-015"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"利用実績と、その実績に対して区の見解をお伺いします。第６波が起きた場合は、迅速に医療機関と連携し、今回のように病床の確保をしていただきたいと要望しますが、見解を伺います。","respondent":"福内健康推進部長","answer":"病床の利用状況につきましては、自宅療養中で往診医が入院が必要と判断した症例はなく、幸い実績はありませんでした。今後の病床につきましては、感染拡大により必要となった場合、区の要請に基づき、確実に１床を確保していただけることとなっております。","id":"exchange-016"},{"speaker":"新妻副委員長","kind":"質問","question":"第５波のピーク時における小・中・義務教育学校、改めてそれぞれの検査数と、そのうちの感染者数を伺います。２学期が始まって以降、それぞれの検査数と感染状況を伺います。","respondent":"福内健康推進部長","answer":"中学校では３５名検査し感染者数１名、区立保育園では６４４名検査し感染者数が１９名、私立保育園では１,０４３名検査し感染者数４７名でした。私立幼稚園では４１名検査し感染者数ゼロ、区立保育園では１６名検査し感染者数ゼロ、私立保育園では検査実績なしでございました。","id":"exchange-017"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"検査を縮小しないよう求めますが、品川区のＰＣＲ検査をどのような体制で行っていくのか、お考えを伺います。併せて見解を伺います。","respondent":"福内健康推進部長","answer":"これまで保育園等の検査につきましては、保健所が施設に出向いて検査を実施してまいりました。医療機関一覧につきましては、早急に区のホームページにリンクを貼ってまいります。","id":"exchange-018"},{"speaker":"新妻副委員長","kind":"質問","question":"そこで、コロナ禍の１年９か月、区立と民間の高齢者施設における面会はどのように工夫し行われていたのか、それぞれお知らせください。面会における基準となる考え方があるのか、伺います。","respondent":"伊崎福祉部長","answer":"基準ですが、区立、民間に関わらず、この通知を基準として対応してきているところです。現在では、感染予防対策を十分にした上での、直接の対面での面会も可能となっております。","id":"exchange-019"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"さらに、感染防止の様々な工夫と努力をされながら面会を実施している民間の施設については、区としても支援をしていただきたいと要望します。それぞれ見解を伺います。","respondent":"伊崎福祉部長","answer":"区立、面会に関する各施設からの相談にきめ細かく対応してきたとともに、ご利用者とご家族の気持ちに寄り添った対応をお願いしてまいりました。しかしながら、今後もサービスの継続を第一に、必要な支援を、きちんとお声を聞きながら行っていきたいと考えております。","id":"exchange-020"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"日本産婦人科学会、日本小児科学会などは再開を求めており、積極的勧奨の再開を妨げる要素はないとの結論が導かれました。会派から款別審査でも伺いましたが、接種券の申請数の変化と接種実績を示すよう求めました。","respondent":"福内健康推進部長","answer":"２０１３年４月に接種努力義務があるＡ類予防接種として開始した直後から、厚生科学審議会の検討部会等で、国民に適切な情報提供ができるまでの間。","id":"exchange-021"},{"speaker":"新妻副委員長","kind":"提案","question":"区内でも接種者が増えていることが確認できました。１つには、プル型ではなくプッシュ型の通知として周知をしてはと提案しますが、見解を伺いますとの意見を述べました。","respondent":"福内健康推進部長","answer":"国から「新型コロナウイルス感染症の発生に伴う定期の予防接種の実施に係る対応について」の通知で、定期接種ワクチンは。学校を通じた周知や、しながわ予防接種ナビ等、様々なツールを活用してお知らせしてまいります。","id":"exchange-022"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"子宮頸がんワクチンは、種類によって、子宮頸がんを６０％から７０％防ぐことができるとされています。品川区においても、１人でも多くの女性が子宮頸がんに罹患することを防ぐ事業を要望しますが、見解を伺います。","respondent":"福内健康推進部長","answer":"ＨＰＶワクチン接種は、子宮頸がん予防のために重要と認識をしております。接種を逃した方への費用助成につきましては、積極的勧奨が再開していない現時点で、区独自に実施することは難しいと考えております。","id":"exchange-023"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"確かにこの事業は、国の判断が待たれるところであります。場合によっては品川区から国へ、強力にキャッチアップを行うよう求めてほしいと要望しますが、改めて見解を伺います。","respondent":"福内健康推進部長","answer":"現在、国の審議会でも、接種機会を逃した者へのキャッチアップなども検討するとしており、国の動向を今後も注視してまいります。","id":"exchange-024"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ヤングケアラー支援を求めた本年の第２回定例会では、取り組むべき施策について区としても検討し、組織を連携しながら対応していくとしました。国の来年度概算要求で示された予算が決定した際には、ぜひ活用し、ヤングケアラー支援を推進してほしいと要望しますが、見解を伺います。","respondent":"伊崎福祉部長、米田教育次長、柏原子ども未来部長","answer":"専門の相談員がアセスメントを行い、支援プランを策定しておりますが、サービス利用の配慮を行うなど留意をしているところです。… ヤングケアラーの実態は、家族内のことでもあり、学校での児童・生徒の様子だけでは発見が難しいと捉えております。学校から家庭に連絡して状況を確認し… そうしたことから、区のほうでも関係部署の会議体等を設けることによって、対応の整備が必要だと捉えているところです。","id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"私は２０１８年より、また、各学校の自主性を尊重したいとの趣旨のご答弁でした。制服の選択は、一部の学校だけではなく、全ての区立中学校、義務教育学校で行っていただきたいと考えますが、今後の区のお考えを説明するよう求めました。","respondent":"米田教育次長","answer":"来年度はさらに４校が予定をしております。性的マイノリティ、また健康安全面への配慮については、教員対象の人権研修や生活指導主任会等でも取り上げ、全校において対応してまいります。","id":"exchange-026"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"私はこの話を伺い、学校の洋式化をこれだけ求めてきて、とても残念に思いました。洋式トイレの設置率について、令和２年度と３年度の状況を伺います。","respondent":"米田教育次長","answer":"洋式トイレの設置率についてですが、令和２年度は７７.２％、令和３年度の見込みは８０.５％です。来年度以降は、目標設置率９０％の達成のため、早期に整備できるよう努めてまいります。","id":"exchange-027"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"次に、保護者からお声があったすまいるスクールのトイレはどう対応されたのか、伺います。学校全体の洋式化率に限らず、優先的に洋式化を進めていただきたいと要望しますが、見解を伺います。","respondent":"柏原子ども未来部長","answer":"それから、今回このご意見をいただいた中で、６月には、全てのすまいるスクールについて調査を実施したところです。別のトイレに誘導するといったような対応をしていますけれども、これも現在、それに対して改善に向けた整備の検討を進めているところです。","id":"exchange-028"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"コロナ禍における女性の負担軽減に関する緊急要望を濱野区長へ提出し、また、積極的に継続的に実施する仕組みを整えることを要望しました。今後の支援の継続的な取組みについて、お考えを、示すよう求めました。","respondent":"米田教育次長","answer":"本年４月の開始から現在までで約１万７,０００個が利用され、多くの児童・生徒の手元に届けられたと捉えているところです。相談も含めた丁寧な対応を行ってまいりましたが、トイレへの設置についても、支援を行っていきたいと考えております。","id":"exchange-029"},{"speaker":"新妻副委員長","kind":"提案","question":"現在、来年度の予算編成時期でもありますので、ぜひ予算化をしての継続を要望いたします。提案をいたしましたことが早期に実現されることをお願い申し上げ、総括質疑を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"こんの委員","kind":"質問","question":"一方、品川区においてはどのような状況でしょうか。これまでの接種体制や運営などについて、どのような課題があったのか尋ねました。","respondent":"秋山保健整備担当部長","answer":"きめ細かな対応ができる反面、ワクチンを無駄にしないように６の倍数になるように接種予約を取ることが難しいなどの課題がございました。計画どおりに進めておりましたが、発送の前倒しを余儀なくされるなど、そのたびに全庁を挙げて対応してきたところです。","id":"exchange-031"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこで、３点お聞きいたします。３つ目には、実施体制など品川区の実施計画、それぞれ、答えるよう求めました。","respondent":"秋山保健整備担当部長","answer":"自治体説明会では、さらなる科学的知見や諸外国の対応状況を踏まえて判断するとされておりますが、２回目接種完了後。１２月には医療従事者を、区民の接種は、高齢者施設の方を１月下旬より開始できるよう準備を進めております。","id":"exchange-032"},{"speaker":"こんの委員","kind":"質問・要望","question":"予約システムについては、希望する診療所やクリニックに、ウェブによる予約受付ができるようサポートする体制についてのお考えはいかがでしょうか。これまで、今後の障害者における予約の在り方はどのようにお考えか尋ねました。","respondent":"秋山保健整備担当部長","answer":"聴覚障害者の方にはファックス対応を、その他お手伝いが必要な方には本庁舎３階や各地域センター等でサポートを実施してまいりました。引き続き３回目接種の際も実施ができるよう、１、２回目の経験を踏まえて調整を行ってまいります。","id":"exchange-033"},{"speaker":"こんの委員","kind":"質問・要望","question":"今後の追加接種について、万全の準備で進めていただきたいことをお願いしまして、次の質問に移ります。９月２２日、コロナ対策に関する１４回目の緊急要望とともに、高齢者などの支援を濱野区長に求めました。","respondent":"堀越企画部長","answer":"先ほどお話しした考え方に基づきまして、今年度は高齢者地域支援課においてスマホ教室を実施しております。デジタルデバイド対策についても１つのテーマとして扱いまして、取り組んでいきたいと考えているところです。","id":"exchange-034"},{"speaker":"こんの委員","kind":"質問","question":"そこで、何点かお聞きします。区内高齢者のスマホ保有状況と利用実態の現状、また、現在のスマホ教室の定員数や開催頻度などの事業実績と課題、それぞれ、答えるよう求めました。","respondent":"伊崎福祉部長","answer":"年間８コースの実施を予定しておりまして、７月と１０月に４コース実施をしておりますけれども、定員の４倍から８倍のお申込みをいただいております。年間１０回開催予定で、８月と９月に合計４回実施をしたところ、ほぼ定員を大きく超えるお申込みをいただきました。","id":"exchange-035"},{"speaker":"こんの委員","kind":"質問","question":"１対１できめ細かく丁寧に分かりやすくサポートする体制の整備、また、いつでも相談できる身近な相談窓口の設置なども必要だと思います。それぞれご見解を説明するよう求めました。","respondent":"伊崎福祉部長","answer":"デジタル活用の支援を行うことのできる協力者の養成や、どのような方法で支援を充実させていくか、検討をしてまいります。身近な相談窓口の設置につきましては、スマホ教室の拡充と併せて検討をしてまいります。","id":"exchange-036"},{"speaker":"こんの委員","kind":"提案","question":"そこで品川区は、現在スマホを保有していない、例えば高齢者などについて、何か具体策はお考えでしょうか。購入費、通信費などの助成をするなど、対策を提案しますとの意見を述べました。","respondent":"堀越企画部長","answer":"それから、そこで出てきたお困り事などの具体的な利用特性の情報なども集めながら、今後の方策について検討していきたいと考えています。高齢者のスマホ利用率は、東京都、国、通信事業者の取組みも見ながら、様々検討してまいりたいと考えているところです。","id":"exchange-037"},{"speaker":"こんの委員","kind":"質問・要望","question":"品川区におけるデジタルデバイド対策、実効性ある取組みになりますよう要望いたしまして、次の質問に移ります。現在、抗体低下による感染予防措置として三種混合ワクチンの追加接種が考えられており、医師会の先生方からもご要望の声が寄せられております。","respondent":"福内健康推進部長","answer":"区といたしましても、百日ぜきによる乳児の重症例を予防する観点から必要と認識をしております。接種回数や接種時期についても検討がなされていることから、国の動向を見守ってまいります。","id":"exchange-038"},{"speaker":"こんの委員","kind":"質問","question":"２０１９年の決算特別委員会で質問した際、屈折検査の導入に至らない理由として、日本人に推奨される基準値が検討中であるからとのことでした。現在、基準値の検討状況と併せて、いま一度お聞きしますが、家庭で行う一次検査についての制度や信憑性について、品川区のご見解を説明するよう求めました。","respondent":"福内健康推進部長","answer":"３歳児健康診査で実施している視力検査についてですが、片目ずつ隠して、３歳児でも測定の容易な絵が認識できる場で判定をするものです。家庭での実施が難しい場合や、検査時に保健センターで再検査をし、対応をしています。","id":"exchange-039"},{"speaker":"こんの委員","kind":"質問・要望","question":"ご紹介が遅れましたが、こちらは、この機器を使用して屈折検査を要望している医師会の先生から、今日はこの機器をお借りをしてきました。導入を求めます。","respondent":"福内健康推進部長","answer":"３歳児健康診査で視力の発達の遅れや目の疾患を早期に発見し治療につなげることは、重要と認識しております。今回、検査の推奨基準値が示されたことから、屈折検査の導入については、前向きに検討してまいります。","id":"exchange-040"},{"speaker":"こんの委員","kind":"質問","question":"５年越しの質問で、このことについて、今、前向きの答弁をいただきました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"鈴木（博）委員","kind":"意見","question":"退院後に何らかの症状が残った人が１６３名中７５名おり、味覚障害、呼吸苦と続いたと報告されております。現在問題になっている感染後の後遺症についての区の認識と、この後遺症に対して何らかの対応をお考えになっているのか、お示しくださいとの意見を述べました。","respondent":"福内健康推進部長","answer":"ホームページで東京都の相談窓口を紹介しているところです。日常生活にも支障を来すことが非常にあるということですので、感染予防の重要性と併せ、さらなる周知啓発に努めてまいります。","id":"exchange-042"},{"speaker":"鈴木（博）委員","kind":"質問","question":"区も、このような患者の存在を十分配慮し、支援することを希望して、次の質問に移ります。現在使用されている新型コロナウイルスワクチンとその特徴、今後導入されそうなワクチンについてご紹介いただくよう求めました。","respondent":"秋山保健整備担当部長","answer":"品川区では、全てのワクチン、３種類を使い、接種を進めてまいりました。今後導入を予定されているものですけれども、薬事承認はいまだ下りておりませんが、ノババックス社製のワクチンです。","id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"意見","question":"現在、新型コロナウイルスワクチンの３回目の追加接種の準備も始まっていると報道されています。３回目の追加接種の意義、これまでの教訓を活かした３回目接種の準備の現状についてご説明をお願いいたしますとの意見を述べました。","respondent":"秋山保健整備担当部長","answer":"追加接種をすることで２回接種後の時間経過により減少した抗体価を上げ、発症予防、重症化予防等の効果が継続することが期待されております。１２月から医療従事者、年明け１月下旬からは、各関係団体と協議を精力的に進めているところです。","id":"exchange-044"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、子どもへのワクチン接種についてお伺いします。子どもの新型コロナウイルス感染後の症状の特徴と、子どもへのコロナワクチンの接種の適否について、品川区のご見解はいかがか尋ねました。","respondent":"秋山保健整備担当部長","answer":"しかし、子どもの感染者では、重症化せず、軽症で治まったケースがほとんどと言われております。１２歳から１６歳の方のワクチン接種に当たっては、安全を考え、診療所などの個別接種会場での接種を進めてまいりました。","id":"exchange-045"},{"speaker":"鈴木（博）委員","kind":"質問","question":"教育費の款別審査で教育委員会にもお尋ねしましたが、保護者への積極的なワクチン勧奨がどうしても必要と考えます。保護者へのコロナワクチンの情報提供はどのように行われているのか尋ねました。","respondent":"秋山保健整備担当部長","answer":"１２歳から１６歳への小児への接種を行う際には、安全面の観点から、保護者の同伴が必要とのご案内を積極的に行ってまいりました。ホームページ、広報しながわ等で情報提供を進めてまいりますし、今後もそれらをさらに研究して周知を図ってまいります。","id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、新型コロナウイルス感染症の治療薬についてお伺いいたします。現在行われている新型コロナウイルス感染症の治療の概要について、簡単にご説明をお願いいたします。","respondent":"福内健康推進部長","answer":"新型コロナウイルス感染症の治療につきましては、発症からの時期や重症度により、異なる治療薬が使われております。抗ウイルス薬や、必要に応じ酸素投与、免疫抑制剤等の治療を組み合わせることになります。","id":"exchange-047"},{"speaker":"鈴木（博）委員","kind":"意見","question":"２０２１年９月２７日には、さらにソトロビマブという別の中和抗体薬も特例承認されました。この抗体カクテル療法について、簡単なご説明と、品川区の現在の対応について、ご説明をお願いいたしますとの意見を述べました。","respondent":"福内健康推進部長","answer":"抗体カクテル療法についてですが、この治療は、発症の早期、特に４日頃までの治療開始が効果的とされております。品川区保健所では、８月末から抗体カクテル療法の対象となる患者に積極的にこの治療をお勧めし、これまで２０人がこの治療を受けています。","id":"exchange-048"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今後の新型コロナウイルス感染症はどうなっていくのでしょうか。現在、５類感染症の説明と品川区の対応の違いについてご説明をお願いいたします。","respondent":"福内健康推進部長","answer":"全ての患者について疫学調査を実施し、健康診断の受診勧告や入院勧告、移送や就業制限等を行っております。５類感染症の疾患につきましては、患者の氏名等を把握して、積極的疫学調査を実施しております。","id":"exchange-049"},{"speaker":"鈴木（博）委員","kind":"確認","question":"この報道に疑問を持った日本人医師が、インドネシア小児科学会会長本人に直接電話をして事実を確認し、真実が明らかになりました。品川区としても逐一正しい情報を対置して打ち消すこと、区はどのようなお考えで、どのような対応をされているのか尋ねました。","respondent":"秋山保健整備担当部長","answer":"区といたしましても、区民の方々が誤った情報を基にして、ワクチン接種についての判断をしてしまうことは避けるべきと考えております。品川区ワクチン接種のホームページには、引き続き区民の皆様に正しい情報が届きますように周知を図ってまいります。","id":"exchange-050"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今年はどうなのでしょうか。今期のインフルエンザワクチン接種に対する区のご見解も併せてご説明をお願いいたします。","respondent":"福内健康推進部長","answer":"供給の時期も後ろ倒しになっているということは、区としても認識をしております。これまでどおりですけれども、また、現在行っていただいている感染予防行動を引き続き行っていただくことを広く周知してまいります。","id":"exchange-051"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"今回の質疑のまとめとして、感染症に負けない品川区をつくり上げるために、品川区に求めたいものを列記いたします。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"保健所機能の抜本強化と第６波を起こさせない対策、起こった場合の備えを求めて質問します。第５波の感染爆発時のピーク時の体制について、それぞれの人数と確保策、必要数を確保できたのかについて伺います。","respondent":"榎本総務部長","answer":"コロナ対応の第５波のときの人員体制についてお答えをいたします。それぞれ会計年度や人材派遣も含んでおりますけれども、まずはそれで対応したところです。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私が求めていた数字が出てこないのです。保健師です。","respondent":"榎本総務部長","answer":"最大の残業時間が、令和２年度は、保健師については、最大残業時間、年間１,１２５時間です。令和３年度の最大の残業時間が、年に換算し直して９６７時間です。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は事前にどういう質問をしたいかを言っていますので、しっかりと数字を出してほしいと求めました。なぜ１年６か月にわたり超過勤務が過労死ラインを超える働き方を続けたのか、なぜ改善できなかったのか、伺います。","respondent":"榎本総務部長","answer":"感染症の対応とともに、昨年度に比べて６名を増員し、年度途中についても６名増員を図っております。今後は事務の委託ができるかどうか、業務集中にどの程度対応できるのか、そういうものも洗い出して対応を考えていきたいと考えています。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"次に、保健所の具体的な実態を伺います。深夜０時を超える残業の日数や人数、１,２００人を超える自宅療養者への対応はどうだったのか、伺います。","respondent":"榎本総務部長、福内健康推進部長","answer":"きちんと取れるようにということはしておりますけれども、多分、実質上取れなかったのかということも考えられます。ただ、実態として、泊まり込むような職員はなかったという形です。 職員最大９８名で、この１,２００人を超える自宅療養者の方に対応しましたけれども、非常に緊張感を持ちながら仕事をしました。実施をしたということで、往診、入院の調整を行いました。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"共産党は以前より、品川区の保健師数は２３区最低であり、増員すべきと求めてきました。保健師の今年増やした定員数と、品川区全体の保健師の定員数、この定数は２３区で何番目か、お聞きします。","respondent":"榎本総務部長、福内健康推進部長","answer":"４６名ということで、人数だけでの比較でいくと、２３区中１３位です。ただ、人口１０万人当たりの保健師の割合という形でいくと、今現在、２２位です。 難病等の在宅療養支援、精神障害者の社会復帰等々に至るまで、幅広い支援を行っております。区民の生涯を通じた健康づくりの推進に大きな役割を果たしていると考えております。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その人数は何人必要なのか、そしてまた、増員計画を持つよう求めますが、いかがでしょうか。医師の増員も必要ではないかと思いますが、いかがか尋ねました。","respondent":"榎本総務部長","answer":"その１２名増員のうち、来年度、令和４年度で７名の採用を予定しているものです。機動的な対応という点では、人材派遣や、応援職員等各部からの応援を活用しつつ、体制強化について引き続き検討していくものです。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区の第５波の実態について伺います。区内のコロナ病床が何床あるのか、１日の感染者数、最大自宅療養者数、重症者数、死者数、救急搬送の実態をお聞きします。","respondent":"福内健康推進部長","answer":"第５波の状況ですが、区内の新型コロナ病床数が１９４床、１日の感染者数は、平均で１日１０４名で、最大が８月１２日の２２５名です。重症者数が８３人、死者数４０人、１日に５件から１５件でございました。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"第６波ではこういう措置はされないよう求めますが、いかがでしょうか。改めて、全ての患者が必要な医療を受けられる体制、早期診断と早期治療で、重症者、死亡者を出さない体制を求めますが、いかがか尋ねました。","respondent":"福内健康推進部長","answer":"次に、無症状の方の大規模な検査につきましては、現時点では実施の考えはありません。保育園、学校の職員につきましては、感染予防に資する時期に必要な検査をしており、定期的な検査の実施は現在のところ考えてございません。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本格掘削前の今こそ区として中止を求めていただきたいとの思いで質問します。区内４.６kmにわたるルートの丁目数と丁目の名前、神社仏閣名、事業の現状と今後のスケジュールを伺います。","respondent":"末元都市整備推進担当部長","answer":"需要予測に関しましては、平成２２年から開催されました国土交通省の交通政策審議会の中で検討されてあります。今後、調査掘進の確認結果を、計画路線周辺にお住まいの皆様にご説明した後、本格的な掘進は令和４年度以降と聞いてあります。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"昨年１０月、調布市外環道工事で起こった陥没事故は、本当に衝撃でした。そこから教訓として学び活かすものは何か、伺います。","respondent":"末元都市整備推進担当部長","answer":"陥没箇所周辺で行う地盤補修工事の施工方法などを検討しているとのことです。住民へ丁寧な説明による不安払拭に努め、安全にリニアの工事が行えるよう求めていくことが重要かと考えております。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めてきゅりあんの説明会の参加者が、区民で何人、対象世帯の何％だったのか、伺います。品川区としてＪＲ東海に対して直ちに地域ごとに教室型説明会を開くよう求めていただきたいが、いかがか尋ねました。","respondent":"末元都市整備推進担当部長","answer":"こちら、全部で４回ほど説明会を実施いたしまして、７００名の方が参加されております。区としましては、区民の理解や不安払拭に向けてどのような説明方法が適切か、今後もＪＲ東海と引き続き協議してまいります。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民は本当に不安ですから、しっかりと説明会を求めてほしいと求めました。リニア新幹線にどんな影響を与えることになるのか、南海トラフ地震に対しては検証がされているのか、伺います。","respondent":"末元都市整備推進担当部長","answer":"避難通路を通って移動し、約５kmごとに設置しております非常口立坑を通って、階段やエレベーター等を利用して地上部に避難すると聞いてあります。耐震性に関する各種指針に沿った設計がなされるものと、区としては認識しています。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このような状況はどうなのかということで聞いているのですから、そこに対してまともに答えてほしいと求めました。いかがか尋ねました。","respondent":"末元都市整備推進担当部長","answer":"ＪＲ東海では、そういった地震に関する様々な知見の収集に努めておると聞いております。耐震性に関する各種指針に沿った設計がなされるものと、区としては認識しています。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"未来への負の遺産としないためにも、今こそ中止の決断を国とＪＲに求めてほしいと求めました。以上で私の質問を終わり、安藤委員に引き継ぎます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"区民の心身への影響調査の実施を求めましたが、国の責任において判断すべき、独自に行う考えはないと拒否しました。伺います。","respondent":"中村都市環境部長","answer":"区民の皆さんが平穏な生活を送るということは大切なことだと考えますし、様々、国に一つひとつ届けてまいりました。地域の皆さんの声をこれからも国に届けるとともに、区として可能な限り環境影響の低減について国へ強く取組みを求めてまいります。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"共産党が品川の上を飛ばないことを求めていくべきと質問すると、区は、その実施を求めていくのが区の姿勢と繰り返しました。区は、なぜ品川区の上を飛び続けることをよしとするのか、伺います。","respondent":"中村都市環境部長","answer":"本格運用が実施されたことを受けまして、実施後に速やかに国に対して、経路の見直しの検討を求めてまいりました。現在、国でその検討が行われているという状況だと認識しております。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"当事者としての反省はないのでしょうか。伺いたいと思います。","respondent":"中村都市環境部長","answer":"地域の皆さんにこの内容について理解を深めてもらうことが第一と考えまして、区内各地域への丁寧な説明、情報提供を求めてまいりました。そして、区の求めに応じて国が今検討しています。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"渋谷区議会では、１３日に、運用停止を求める国への意見書を全会一致で採択しました。なぜそれだけのビル建設が可能となるのか、決定が必要で、いつ決定する予定なのかも伺います。","respondent":"末元都市整備推進担当部長","answer":"令和４年度以降に工事に着工し、令和７年度に完成する予定です。再開発等促進区を定める地区計画および土地区画整理事業であり、今年の１１月下旬に都市計画決定する予定で手続を進めております。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"土地再編についてさらに伺いたいのですが、区画整理後の換地後に区が手にする土地の位置は、この赤色のＬ字部分で間違いないでしょうか。この面積は何m2か尋ねました。","respondent":"末元都市整備推進担当部長","answer":"次に、駅前には多様なニーズに対応した商業や業務などの複合機能を配置するとともに、適正な土地利用計画に従い進めていく方針としています。適正な換地計画に基づきまして、りんかい線による土地の制約なども含めて、適正な土地評価の下に進めていく予定です。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"そして、駅前の一等地をＪＲに譲るにもかかわらず、新たに受け取る土地の面積すら区民に明らかにしないとはどういうことでしょうか。いつ決定する予定なのかも伺います。","respondent":"榎本総務部長","answer":"その素案の内容については、候補地は、今、図にあるように、Ｌ字型のところへ今の庁舎にくっつく形での土地を予定しております。建設スケジュールは、令和７年から令和９年の建設スケジュールで進めるものです。","id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"伺います。万全ではないとは、何が十分ではないということなのか、伺います。","respondent":"榎本総務部長","answer":"要は、震度が強くなるという想定が出ておりますので、万全ではないという形でお答えしたとおりです。空調設備、なかなかそこの部分も含めて、何年もつかという形を考えなければいけないと考えています。","id":"exchange-073"},{"speaker":"安藤委員","kind":"提案","question":"以下提案し、その実施を強く求めます。時間をかけて情報公開と住民参加で白紙から検討すること、以上を求めますが、いかがか尋ねました。","respondent":"榎本総務部長","answer":"庁舎の老朽化についての対策につきましては、平成２９年度から区議会行財政改革特別委員会で継続的に検討してきているものです。それで、その結果、今、この基本構想の段階にやっと来たですので、撤回するつもりはございません。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"十分に時間をかけて、どんな庁舎にするのか、区有地をどう活用するのか、徹底した情報公開と住民参加で一から検討すべきです。重ねて求めまして、私からの総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"くにば委員","kind":"質問","question":"１点目、若者世代のワクチン接種率向上の施策についてお伺いします。本区では、若者世代の接種率向上を目指し、どのような具体的施策、事業をお考えか尋ねました。","respondent":"秋山保健整備担当部長","answer":"１２歳から１６歳の接種希望者に対しては、１６歳から２９歳の接種希望者に対しては、それぞれ体制を整えてまいりました。あくまでも本人の意思に基づき受けていただくものであり、接種率を上げるためのインセンティブについては、慎重な判断が必要と考えております。","id":"exchange-076"},{"speaker":"くにば委員","kind":"質問","question":"本区においては、接種希望者のワクチン接種予約がようやく一段落したと思われますが、今後、予約不要での接種会場を設置してはいかがでしょうか。本区においても、夜間時間帯での接種会場は用意しておりますけれども、深夜・早朝を含めたより幅広い時間帯の接種会場を設置してはいかがか尋ねました。","respondent":"秋山保健整備担当部長","answer":"それから夜間時間帯等の会場ですけれども、現在、品川区でも夜間帯の接種予約を受け付けてあります。実施している自治体の状況を見ますと、午後１０時以降、こちらも慎重に検討する必要があるというふうに考えてあります。","id":"exchange-077"},{"speaker":"くにば委員","kind":"質問・要望","question":"なぜワクチン接種後も引き続き感染対策を続ける必要があるのか、ブレークスルー感染についての特集解説記事を掲載してはいかがでしょうか。以上２点、それぞれご所見を伺います。","respondent":"福内健康推進部長","answer":"これらについては、現在のホームページのみでなく、改めてその周知方法も含めて検討してまいります。ちょうど第５波がある程度収束をしておりますので、きちんと区民に伝わるよう、周知方法について検討してまいります。","id":"exchange-078"},{"speaker":"くにば委員","kind":"質問","question":"次に、コロナワクチン接種証明書を活用した施策についてお伺いします。併せて、同証明書活用についての国と都の最新の見解と動向を示すよう求めました。","respondent":"秋山保健整備担当部長","answer":"東京都内においても、プロ野球の試合において、ワクチン・検査パッケージの技術実証が行われると聞いております。区といたしましては、国や都のこうした実証実験ないしは技術実証の結果を注視してまいります。","id":"exchange-079"},{"speaker":"くにば委員","kind":"質問","question":"本区では、区内観光産業の再興、外国人観光客誘致について、ワクチン接種証明書の活用をどのように捉えておりますでしょうか。同様に、ワクチン接種証明書活用について、別の観点からもお伺いします。","respondent":"山崎文化スポーツ振興部長、久保田地域振興部長","answer":"観光の部分、特に外国人観光客の取組みなどにおきましては、この間のコロナ禍におきまして、なかなか実施できない事業も多々ございました。観光協会など関係団体と連携しながら、品川の魅力を広く伝え… 既に飲食店等や宿泊業を中心として、ワクチン接種を終えた方を対象とした割引サービスなどを実施しているということは私どもも認識しています。","id":"exchange-080"},{"speaker":"くにば委員","kind":"質問","question":"ポストコロナ社会で新たに生まれるニーズ、消費を先読みした施策をつくり上げてほしい、そのような思いから質問します。お尋ねします。","respondent":"山崎文化スポーツ振興部長、久保田地域振興部長","answer":"現地での日本博の出展でありますとか、台湾で発行される観光冊子への掲載など、直接赴いて諸活動をしてまいりました。魅力を、先ほどのワクチンパスポートなどの周辺の状況を見ながら… 新型コロナウイルス感染症対応特別助成、また販路拡大支援事業等、前向きな支援策を積極的に行ってまいりました。","id":"exchange-081"},{"speaker":"くにば委員","kind":"質問・要望","question":"次に、体験学習についてお伺いします。最近新たに始めた取組みや、力を入れている取組みなど、それぞれ説明を求めました。","respondent":"米田教育次長","answer":"ボランティア活動など、発達段階に応じて、子どもや生活に身近な体験活動を実施しています。ウマとの触れ合い体験や、ウサギの心音を聞いて命の学習を行うなど、動物との触れ合いを大切にしています。","id":"exchange-082"},{"speaker":"くにば委員","kind":"質問・要望","question":"本区の学校教育の現場で、これらの自然体験などの体験授業は、実際に年々減少しているのでしょうか。どのような事業が危険と判断して取りやめられていってしまっているのか尋ねました。","respondent":"米田教育次長","answer":"先ほども少しご案内いたしましたけれども、この機会の電子化等の中でもありますので、実体験をする機会が非常に失われているというようなところです。","id":"exchange-083"},{"speaker":"くにば委員","kind":"質問","question":"次に、ボーイスカウトについてお伺いします。現在、教育委員会、各学校は、それぞれボーイスカウトとの連携はどのように図っていますか尋ねました。","respondent":"米田教育次長","answer":"あるいは子ども自身が、自分自身で団体として所属し、自然体験活動を行うというようなことで理解しております。教育委員会といたしまして、活動の場所が区内ということでは、多少の関わりというものは生じる可能性もあるというふうに捉えているところです。","id":"exchange-084"},{"speaker":"くにば委員","kind":"質問","question":"児童・生徒にターゲットを絞ったお勧め電子書籍を、例えば週１回、プッシュ通知してはいかがでしょうか。配布タブレットのホーム画面に、そのリストへのリンクを張り、週１回追加更新するなどしてはいかがか尋ねました。","respondent":"米田教育次長","answer":"委員からご紹介ありましたように、しながわ電子図書館は、今、稼働を開始いたしまして３か月経過しています。児童・生徒のほうで持っております１人１台端末のほうからは、実際の書籍と電子書籍、ホームページ等の展開については図ってまいりたいと思います。","id":"exchange-085"},{"speaker":"くにば委員","kind":"提案","question":"現在この事業の導入についてどのようなご見解でしょうか。こちらの導入に当たっては、何か障害になることがあるのでしょうか、説明を求めました。","respondent":"福内健康推進部長","answer":"育児パッケージの配布のほか、都作成の「体罰などによらない子育てハンドブック」などの配布もあります。直接お子様や家庭の状況等を把握するとともに必要な支援を行っておりますので、児童福祉の多面的な観点から、引き続き検討を進めてまいります。","id":"exchange-086"},{"speaker":"くにば委員","kind":"質問・要望","question":"そこから１年経って、「今いかがですか」ということを聞くための１つのフックとしてプレゼントすると、そういった事業です。こちらは令和２年度は４園でのモデル実施でしたけれども、昨年３月の予算特別委員会にて、全保育所と幼稚園への導入促進を私が求めました。","respondent":"柏原子ども未来部長","answer":"この１年半で１回だけ、確認ということで実施しておりまして、その段階で１回だけ実績が出ているといったところです。この内容についてはもう少し検証させていただいて、今後どういうふうにするのかというのは検討していきたいというふうに思ってあります。","id":"exchange-087"},{"speaker":"くにば委員","kind":"意見","question":"ただ、１件だけしかまだ検証できていないという部分に関して、ぜひとも導入の促進を進めていってほしいと求めました。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"吉田委員","kind":"質問","question":"区民も対象の説明会にすべきだったと考えますが、なぜその点に思いが至らなかったのか見解を伺いたいと思います。区としては、広く区民に周知すべきだったと考えますが、見解を伺います。","respondent":"末元都市整備推進担当部長","answer":"委員からもご指摘のとおり、原案の説明は、地区に含まれる権利者ならびに利害関係者というふうに法令で定められております。そういうことで、都市計画手続は法令に則って適正に説明会をさせていただいたです。","id":"exchange-089"},{"speaker":"吉田委員","kind":"質問","question":"原案の縦覧のほうです。東京都は、区として、もっと広い区民に知らせるということを考えるべきだったのではないかという質問をいたしました。","respondent":"末元都市整備推進担当部長","answer":"通常、原案の説明会については、このような形でやらせていただいております。","id":"exchange-090"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですから、その中に区民の土地が入っているわけですから、なぜそこに思いが至らなかったのかということを質問いたしました。土地区画整理事業はこういう手順で進むのだというような説明が、手順の資料なども示しつつ行われるべきだったと考えますが、見解を伺います。","respondent":"末元都市整備推進担当部長","answer":"原案の説明会は、案の説明会自体は、９月２７日に全区民を対象に説明をしています。事業の施行者は、独立行政法人都市再生機構となる予定で調整を進めておりますので、これも委員のご指摘のとおりです。","id":"exchange-091"},{"speaker":"吉田委員","kind":"確認","question":"であるなら、もっと丁寧に説明がされるべきだったのではないでしょうか。いかがか尋ねました。","respondent":"末元都市整備推進担当部長","answer":"委員ご指摘の３月の事業説明会につきましては、これは任意の説明会でございまして、ＪＲ東日本の開発計画を中心に説明させていただいたというものですので、位置づけが若干異なるです。","id":"exchange-092"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう少しそれを説明するべきなのではないでしょうかという趣旨の質問ですので、お答えください。今どの段階にあるのか、決定はいつ行われるのか、伺います。","respondent":"末元都市整備推進担当部長","answer":"説明会でご説明する内容につきまして、ちょっと私もすぐに今この場で確認できませんが、ご説明はしているというふうに認識しています。区なり、ＪＲなり、他の地権者の同意を得ながら取りまとめていくというものです。","id":"exchange-093"},{"speaker":"吉田委員","kind":"質問","question":"換地計画についても、不動産鑑定を３回ぐらいされると伺っています。事業計画については、あらあらの議論の過程は報告があってしかるべきではないかと思いますが、見解を伺います。","respondent":"末元都市整備推進担当部長","answer":"これは来年度になりますけれども、実際に従前の土地を評価いたしまして、従後の土地と等価交換をするということで作業が進められる予定です。土地の評価に当たっては、学識経験を有する者を評価委員として選定し、適正な評価であることを確認する予定です。","id":"exchange-094"},{"speaker":"吉田委員","kind":"質問・要望","question":"先日の一般質問でも西本委員が要望されていましたが、第２回定例会で私も同様の質問をしました。国に対して同行援護を経済活動にも広げるよう求めるべきと考えますが、見解を伺います。","respondent":"中村都市環境部長、伊崎福祉部長","answer":"検討はこれからということですから、遅い、国のほうではしっかりそれを示していただきたいということで要望してまいります。以前も既に要望してきた中では、やはり国もスピード感を持って取り組むという回答がございました。障害者雇用を促進するという観点から、障害者雇用・福祉施策の連携強化に関する検討会を立ち上げ、その中で様々な検討をしております。","id":"exchange-095"},{"speaker":"吉田委員","kind":"質問・要望","question":"リニア中央新幹線の工事の安全性について、区としてどのように認識し、ＪＲ東海としてどのように協議しているか、伺います。個別にポスティングによるお知らせと言っていますが、区としては、ＪＲにもっと広い範囲の広報を促すべきと考えますが、見解を伺います。","respondent":"末元都市整備推進担当部長","answer":"１０月１４日から調査掘進の工事が開始されまして、現地において、周辺への影響と対策の有効性を試行すると聞いております。きゅりあんで６月に開催された品川区、大田区、世田谷区民を対象とした説明会でＪＲが説明させていただきました。","id":"exchange-096"},{"speaker":"吉田委員","kind":"質問・要望","question":"特にルート上の地域に近いところで、きめ細かく複数回の開催を求めるべきと考えますが、見解を伺います。これらも行うように求めるべきと考えますが、見解を伺います。","respondent":"末元都市整備推進担当部長","answer":"区民の不安払拭、理解の促進に向けて、丁寧な説明がなされることを求めていきたいというふうに考えております。再度、民間事業者も合理的配慮の提供が義務化されたことを伝えるとともに、どなたでも説明を聞けるよう求めてまいります。","id":"exchange-097"},{"speaker":"吉田委員","kind":"質問","question":"もし万が一、何かあったときには、必ずまず区にどうしてこういうことを許したのかという意見が来ると思います。その辺について、どのように考えておられるか、伺います。","respondent":"中村都市環境部長","answer":"大体の事柄につきましては、主体となる事業者に対して、安全の確保はこれまで常に求めてまいったです。そのほかにも保険だとか、そういったものの対策が施されてきているという説明を区としては求めて、国がそういった話をしてきているです。","id":"exchange-098"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですので、やっぱりこれは品川区がＪＲ東海とどのように真摯に向き合うかということがすごく求められていると思います。ぜひその辺をきちんと、ＪＲ東海に説明会も含めてきちんと追及していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"木村委員","kind":"質問","question":"ずばり本区の感染者数約１万３,０００人は、今後どのようになると予想されているのでしょうか。専門家からは、今後１年、長くて２年は続くだろうという予測もありますが、区としての予想はどのように読んでいるのか尋ねました。","respondent":"福内健康推進部長","answer":"中和抗体薬などの活用による重症化予防効果等が期待される一方、これまで経験したような感染拡大が中期的に反復する可能性があるともされております。区といたしましても、十分これらのことを考え、今後の対応についても準備をしていきたいというふうに考えております。","id":"exchange-100"},{"speaker":"木村委員","kind":"質問・要望","question":"緊急事態宣言も解除になった現在、区民に守っていただきたいのは、３密以外で、本区独自の対策や注意事項等はあるのでしょうか。このことに対して、命を守るために、行政としては何をすればよいとお考えか尋ねました。","respondent":"福内健康推進部長","answer":"引き続き感染予防に資すると考えられる３密の回避に加え、換気といった基本的な感染対策を継続していただきたいというふうに考えております。重症化予防が重要と考えておりまして、広報しながわ、ホームページなどで積極的に周知していきたいというふうに考えております。","id":"exchange-101"},{"speaker":"木村委員","kind":"質問","question":"させないは当然ですが、外出を抑え込む強制力がないところに問題があると思いますが、いかがでしょうか。我々も、その点についてお聞きしたいのですが、いかがか尋ねました。","respondent":"福内健康推進部長","answer":"国民へ協力が要請されるものでございまして、今後の我が国における行動制限の在り方については、国で検討されるというふうに考えております。","id":"exchange-102"},{"speaker":"木村委員","kind":"質問","question":"この３回目の接種の可能性はあると考えてよろしいでしょうか。自分、家族、または身近な人や会社の同僚を守る意味でも、ワクチン接種を受ける価値はあると思いますが、いかがか尋ねました。","respondent":"秋山保健整備担当部長","answer":"９月２２日に実施された厚生労働省の自治体説明会にて、国から３回目接種についての基本的な方針が示されました。区といたしましては、今後も接種を希望する方が接種できる体制を構築し、３回目に向けても接種ができるよう引き続き全力で取り組んでまいります。","id":"exchange-103"},{"speaker":"木村委員","kind":"質問","question":"各事業で余剰金として出た金額でしょうか。どのような事業に余りが出たのでしょうか、説明を求めました。","respondent":"黒田財政課長、滝澤災害対策担当部長","answer":"大会開催に合わせて実施を予定していた事業は中止や実施内容の変更など、見直しを行ってまいりました。令和２年６月１日に、緊急性の低い工事などについては実施時期を再検討するなど、対応を図ったところです。 私からは、災害復旧特別会計に係る質問にお答えをします。勢力がやや衰え、あるいはその中心が偏西風などの影響により太平洋上を通過したことから、大きな被害に至らなかったものと考えております。","id":"exchange-104"},{"speaker":"木村委員","kind":"質問","question":"災害の規模によって大小の被害がありますけれども、直近では、都や本区では、どのような規模の災害被害があったのでしょうか。そして、その災害に対して翌年に向かって対策を打つと思いますが、現在までの対策は功を奏していると思ってよいのか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"現在までの風水害対策の評価ですが、洪水浸水対策として、立会川流域での下水道管の整備や下流部における溢水防止板の設置などを行ってまいりました。","id":"exchange-105"},{"speaker":"木村委員","kind":"質問","question":"問題解決のお手伝いをするのでしょうが、この対策を行えば効果が出るだろうなど、絶対にやらなければいけないことは何かあるのでしょうか。ご両親の心情的なつらさなどを説き、熱くやわらかい気持ちで対応されるのでしょうが、年間どれぐらいの命を守ることができるのか尋ねました。","respondent":"福内健康推進部長","answer":"悩みを持っている方への対応で絶対に守らなければならないことですが、区では、特に昨年度から力を入れております。自殺を考えるほど悩んでいる人の悩みはとても深く重いため、必ず誰かと共有し、適切な相談窓口につなげることが必要とされております。","id":"exchange-106"},{"speaker":"木村委員","kind":"質問・要望","question":"本区では、年間どのぐらいの頭数が処理されているのでしょうか。２５kg未満に限ると紹介されていますが、２５kgを超える場合はどのように処理をされるのでしょうか、お聞かせほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"区は基本的に２５kg未満（の動物）を収集しておりまして、それ以外につきましては、専門業者のほうで扱うようにしております。区等に問合せがあった場合については、区も専門業者をご紹介をしているです。","id":"exchange-107"},{"speaker":"木村委員","kind":"質問・要望","question":"本当に我々と同じ生活をしているかわいいペットですから、今のところ、どのぐらいの頭数の犬猫が登録されているのでしょうか。登録義務があるのは、犬猫以外ではどのような種類があるのか尋ねました。","respondent":"福内健康推進部長","answer":"品川区における登録数は、令和２年度で１,２１７頭でございまして、経年的に見ると、少しずつ増えているというような状況があります。その他の動物については、猫を含めて登録制度がなく、猫についても頭数は把握できておりません。","id":"exchange-108"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"経常収支比率は７７.８％、人件費は１０.６％と健全財政を維持していることを好機と捉え、生活の維持向上をさらに進められることを要望いたします。品川区の令和４年度予算、実現していただくことをお願いし、品川区議会自民党の意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"若林委員","kind":"提案","question":"第３波で顕著になった自宅療養者等への保健業務や医療提供体制、今後の生活、品川の再生へ新たな挑戦の気概が求められます。提案事項を検討され、今後の区政運営および来年度予算に反映させるよう求め、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"高橋（伸）委員","kind":"提案","question":"経営収支比率は７７.８％、人件費比率は１０.６％であり、区政運営を行われている状況を確認いたしました。令和３年度、会派所属の各委員が発言した指摘や政策提案が、予算編成をはじめとする区政運営が区民福祉の一層の向上に寄与することを強く求めとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"中塚委員","kind":"提案","question":"住民への直接支援は考えていないと答弁したが、区民生活への支援を求める声が力となり、３万円のしながわ活力応援給付金につながりました。以上、反対理由と要望を述べ、意見表明を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"須貝委員","kind":"質問・要望","question":"１０月に入り、これからは雇用を増やす対策を優先し、収束まで４年以上かかるコロナウイルスと共生する対策に転換するべきです。そして、介護、保育、看護従事者の低賃金を改善したり、羽田新飛行ルートの固定化を避けるために、国や都に働きかけていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"田中委員","kind":"提案","question":"２ルート案が品川区上空を通過するかどうかが明確に分かるよう、地図上に示すことを区として区民に分かる形で求めてください。各款別審査で指摘、提案させていただいた意見を予算編成に生かしていただくことを要望して、品川・生活者ネットワークの意見表明を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-114"},{"speaker":"大倉委員","kind":"提案","question":"東京２０２０大会のレガシー、多様性の推進など、各課題への積極的な取組みも求めます。提案した各項目を真摯に受け止め、今後の施策に反映するよう強く要望いたしまして、しながわ無所属クラブの意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-115"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701177?Template=document&Id=1512#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":107557,"voices":258}},{"id":"r03-20211019-10","meetingId":"r03-cm10","date":"2021年10月19日","dateIso":"2021-10-19","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5428#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":8030,"voices":29}}]);
